/**
 * Slayer Suite: one task card, a readiness check at the bank, one prioritised
 * alert engine, an off-task attack guard, per-task history with a supply
 * forecast, and a couple of jingles. It reads
 * client state, draws overlays and notifies; it never acts in the game.
 */
@Slf4j
@PluginDescriptor(
	name = "Slayer Suite",
	internalName = "slayer-suite",
	description = "Slayer in one plugin: a task card with kills left, ETA, style and gear; a side panel that ranks spots for your account and guides you there; a readiness check at the bank; one alert engine with banner and sounds; task complete and level up cards; an off-task attack guard; and your own loot and history per task.",
	tags = {"slayer", "aio", "task", "alerts", "readiness", "superior", "afk", "bank", "combat", "eta", "gps", "panel", "loot", "history", "sounds"}
)
@PluginDependency(SlayerPlugin.class)
public class SlayerSuitePlugin extends Plugin
{
	public static final String VERSION = "0.8.12";

	@Inject
	private EventBus eventBus;
	@Inject
	private OverlayManager overlayManager;
	@Inject
	private KeyManager keyManager;
	@Inject
	private ClientToolbar clientToolbar;
	@Inject
	private SlayerSuiteConfig config;

	@Inject
	private SlayerDataset dataset;
	@Inject
	private TaskTracker tracker;
	@Inject
	private ReadinessChecker readiness;
	@Inject
	private AlertEngine alerts;
	@Inject
	private AttackGuard guard;
	@Inject
	private TaskHistory history;
	@Inject
	private TripTracker trip;
	@Inject
	private TravelData travelData;
	@Inject
	private Advisor advisor;
	@Inject
	private com.slayersuite.data.TravelPoints travelPoints;
	@Inject
	private com.slayersuite.advisor.LoopGuide loopGuide;
	/** Built in startUp, after RuneLite's look and feel is installed, so it gets RuneLite's scrollbar and widgets. */
	private SlayerSuitePanel panel;
	@Inject
	private HouseScanner houseScanner;
	@Inject
	private PluginOverlap pluginOverlap;

	@Inject
	private TaskCardOverlay cardOverlay;
	@Inject
	private ReadinessOverlay readinessOverlay;
	@Inject
	private AlertBannerOverlay bannerOverlay;
	@Inject
	private GpsOverlay gpsOverlay;
	@Inject
	private PathOverlay pathOverlay;
	@Inject
	private RouteService routeService;
	@Inject
	private TransportLearner transportLearner;
	@Inject
	private RouteMinimapOverlay routeMinimapOverlay;
	@Inject
	private RouteMapOverlay routeMapOverlay;
	@Inject
	private com.slayersuite.history.FloorLootOverlay floorLootOverlay;
	@Inject
	private com.slayersuite.advisor.FairyDialOverlay fairyDialOverlay;
	@Inject
	private com.slayersuite.card.SuperiorOverlay superiorOverlay;
	@Inject
	private NpcHoverOverlay hoverOverlay;
	@Inject
	private TaskCompleteOverlay completeOverlay;
	@Inject
	private TaskChoiceOverlay choiceOverlay;
	@Inject
	private OverlapOverlay overlapOverlay;

	private NavigationButton navButton;

	@Inject
	private ConfigManager configManager;
	@Inject
	private Client client;
	@Inject
	private SoundPlayer sounds;

	/** ::ss done | superior | alert | supplies | sound : fires the matching display for testing, records nothing. */
	@Subscribe
	public void onCommandExecuted(CommandExecuted e)
	{
		if (!"ss".equalsIgnoreCase(e.getCommand()) && !"slayersuite".equalsIgnoreCase(e.getCommand()))
		{
			return;
		}
		String what = e.getArguments() != null && e.getArguments().length > 0 ? e.getArguments()[0].toLowerCase() : "help";
		String task = tracker.hasTask() ? tracker.getTaskName() : "Test task";
		switch (what)
		{
			case "done":
				eventBus.post(new TaskFinished(task, 20, 12, true));
				say("test: task complete card, sound and alert");
				break;
			case "superior":
				tracker.testSuperior();
				say("test: superior card, sound and alert");
				break;
			case "level":
				history.testLevelUp();
				say("test: level up card");
				break;
			case "alert":
				alerts.testAlert();
				say("test: critical alert banner, notification and beep");
				break;
			case "supplies":
				eventBus.post(new SuppliesLow(12, 30, "food"));
				say("test: supplies-low alert");
				break;
			case "sound":
				sounds.play(SoundPlayer.Sound.TASK_DONE, config.soundVolume());
				say("test: task-done sound");
				break;
			case "vars":
				say(tracker.varReport());
				log.info("Slayer Suite ::ss vars -> {}", tracker.varReport());
				break;
			case "report":
				say(history.copyLastReport() ? "copied: " + history.getLastReport() : "no task finished yet this session");
				break;
			default:
				say("::ss done | superior | level | alert | supplies | sound | report | vars");
		}
	}

	private void say(String msg)
	{
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "<col=00a0ff>Slayer Suite:</col> " + msg, null);
	}

	@Provides
	SlayerSuiteConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SlayerSuiteConfig.class);
	}

	/** Defaults written by an earlier build that later changed. Runs once per profile. */
	private void migrateDefaults()
	{
		if (configManager.getConfiguration(SlayerSuiteConfig.GROUP, "migration") == null)
		{
			configManager.setConfiguration(SlayerSuiteConfig.GROUP, "migration", "1");
		}
	}

	@Override
	protected void startUp()
	{
		if (!dataset.isLoaded())
		{
			dataset.load();
		}
		travelData.load();
		travelPoints.load();
		migrateDefaults();
		tracker.reset();
		readiness.reset();
		alerts.reset();
		history.reset();
		trip.reset();
		advisor.reset();
		houseScanner.reset();
		pluginOverlap.reset();
		panel = injector.getInstance(SlayerSuitePanel.class);
		advisor.setListener(panel::refreshLater);
		advisor.setOwnRatesSource(history::ownRates);
		try
		{
			sounds.setDirectory(getPluginDirectory().joinSegment("sounds"));
			transportLearner.setFile(getPluginDirectory().joinSegment("learned-transports.tsv"));
			log.debug("Slayer Suite: custom sounds are read from {}", sounds.getDirectory());
		}
		catch (java.io.IOException | RuntimeException e)
		{
			log.warn("Slayer Suite: no plugin folder for custom sounds ({})", e.toString());
		}

		eventBus.register(tracker);
		eventBus.register(readiness);
		eventBus.register(alerts);
		eventBus.register(guard);
		eventBus.register(history);
		eventBus.register(trip);
		eventBus.register(advisor);
		eventBus.register(loopGuide);
		eventBus.register(houseScanner);
		eventBus.register(pluginOverlap);
		routeService.start();
		eventBus.register(routeService);
		transportLearner.load();
		eventBus.register(transportLearner);
		keyManager.registerKeyListener(alerts.getPauseHotkey());

		overlayManager.add(cardOverlay);
		overlayManager.add(readinessOverlay);
		overlayManager.add(bannerOverlay);
		overlayManager.add(gpsOverlay);
		overlayManager.add(pathOverlay);
		overlayManager.add(routeMinimapOverlay);
		overlayManager.add(routeMapOverlay);
		overlayManager.add(floorLootOverlay);
		overlayManager.add(fairyDialOverlay);
		overlayManager.add(superiorOverlay);
		eventBus.register(fairyDialOverlay);
		eventBus.register(pathOverlay);
		overlayManager.add(hoverOverlay);
		overlayManager.add(completeOverlay);
		eventBus.register(completeOverlay);
		overlayManager.add(choiceOverlay);
		overlayManager.add(overlapOverlay);
		eventBus.register(choiceOverlay);

		if (config.advisorPanel())
		{
			navButton = NavigationButton.builder()
				.tooltip("Slayer Suite")
				.icon(ImageUtil.loadImageResource(SlayerSuitePlugin.class, "/com/slayersuite/icon.png"))
				.priority(6)
				.panel(panel)
				.build();
			clientToolbar.addNavigation(navButton);
		}
		log.info("Slayer Suite {} started with {} tasks in the dataset", VERSION, dataset.getTasks().size());
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged e)
	{
		if (SlayerSuiteConfig.GROUP.equals(e.getGroup()) && "customChevronColour".equals(e.getKey()))
		{
			// picking a colour is the choice; the preset follows it without a second click
			configManager.setConfiguration(SlayerSuiteConfig.GROUP, "chevronColour", com.slayersuite.advisor.ChevronColour.CUSTOM);
		}
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(cardOverlay);
		overlayManager.remove(readinessOverlay);
		overlayManager.remove(bannerOverlay);
		overlayManager.remove(gpsOverlay);
		overlayManager.remove(pathOverlay);
		overlayManager.remove(routeMinimapOverlay);
		overlayManager.remove(routeMapOverlay);
		overlayManager.remove(floorLootOverlay);
		overlayManager.remove(fairyDialOverlay);
		overlayManager.remove(superiorOverlay);
		eventBus.unregister(fairyDialOverlay);
		eventBus.unregister(pathOverlay);
		eventBus.unregister(routeService);
		eventBus.unregister(loopGuide);
		eventBus.unregister(transportLearner);
		routeService.stop();
		overlayManager.remove(hoverOverlay);
		overlayManager.remove(completeOverlay);
		eventBus.unregister(completeOverlay);
		overlayManager.remove(choiceOverlay);
		overlayManager.remove(overlapOverlay);
		eventBus.unregister(choiceOverlay);
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
		advisor.setListener(null);
		panel = null;
		keyManager.unregisterKeyListener(alerts.getPauseHotkey());
		eventBus.unregister(pluginOverlap);
		eventBus.unregister(houseScanner);
		eventBus.unregister(advisor);
		eventBus.unregister(trip);
		eventBus.unregister(history);
		eventBus.unregister(guard);
		eventBus.unregister(alerts);
		eventBus.unregister(readiness);
		eventBus.unregister(tracker);
		alerts.reset();
		history.reset();
		trip.reset();
		advisor.reset();
		tracker.reset();
		readiness.reset();
	}
}

package com.slayersuite.advisor;

import com.slayersuite.readiness.ReadinessChecker;
import java.util.Locale;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.VarbitID;

/** Reads quest states, diary varbits, the spellbook and owned items from the client. Read-only. */
@Singleton
public class AccountState implements AccountView
{
	private final Client client;
	private final ReadinessChecker readiness;
	private final HouseScanner house;

	@Inject
	public AccountState(Client client, ReadinessChecker readiness, HouseScanner house)
	{
		this.client = client;
		this.readiness = readiness;
		this.house = house;
	}

	private QuestState state(String constant)
	{
		if (constant == null || client.getGameState() != GameState.LOGGED_IN)
		{
			return null;
		}
		try
		{
			return Quest.valueOf(constant).getState(client);
		}
		catch (IllegalArgumentException | NullPointerException e)
		{
			return null;
		}
	}

	@Override
	public boolean questFinished(String questConstant)
	{
		return state(questConstant) == QuestState.FINISHED;
	}

	@Override
	public boolean questStarted(String questConstant)
	{
		QuestState s = state(questConstant);
		return s == QuestState.FINISHED || s == QuestState.IN_PROGRESS;
	}

	@Override
	public boolean diaryComplete(String diaryKey)
	{
		if (diaryKey == null || client.getGameState() != GameState.LOGGED_IN)
		{
			return false;
		}
		int varbit;
		switch (diaryKey.toUpperCase(Locale.ROOT))
		{
			case "KOUREND_ELITE":
				varbit = VarbitID.KOUREND_DIARY_ELITE_COMPLETE;
				break;
			case "KOUREND_HARD":
				varbit = VarbitID.KOUREND_DIARY_HARD_COMPLETE;
				break;
			case "LUMBRIDGE_ELITE":
				varbit = VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE;
				break;
			case "DESERT_HARD":
				varbit = VarbitID.DESERT_DIARY_HARD_COMPLETE;
				break;
			case "DESERT_ELITE":
				varbit = VarbitID.DESERT_DIARY_ELITE_COMPLETE;
				break;
			case "MORYTANIA_HARD":
				varbit = VarbitID.MORYTANIA_DIARY_HARD_COMPLETE;
				break;
			case "MORYTANIA_ELITE":
				varbit = VarbitID.MORYTANIA_DIARY_ELITE_COMPLETE;
				break;
			case "FREMENNIK_HARD":
				varbit = VarbitID.FREMENNIK_DIARY_HARD_COMPLETE;
				break;
			case "FREMENNIK_ELITE":
				varbit = VarbitID.FREMENNIK_DIARY_ELITE_COMPLETE;
				break;
			case "KANDARIN_HARD":
				varbit = VarbitID.KANDARIN_DIARY_HARD_COMPLETE;
				break;
			case "WESTERN_ELITE":
				varbit = VarbitID.WESTERN_DIARY_ELITE_COMPLETE;
				break;
			case "WILDERNESS_HARD":
				varbit = VarbitID.WILDERNESS_DIARY_HARD_COMPLETE;
				break;
			default:
				return false;
		}
		return client.getVarbitValue(varbit) == 1;
	}

	@Override
	public int spellbook()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return -1;
		}
		return client.getVarbitValue(VarbitID.SPELLBOOK);
	}

	@Override
	public boolean ownsItem(String itemName)
	{
		return readiness.owns(itemName);
	}

	@Override
	public boolean hasHouseFacility(String facility)
	{
		return house.has(facility);
	}

	@Override
	public boolean jewelleryBoxCovers(String itemName)
	{
		return house.jewelleryBoxCovers(itemName);
	}

	@Override
	public boolean houseScanned()
	{
		return house.scanned();
	}

	@Override
	public boolean canTeleportHome()
	{
		if (ownsItem("Teleport to house") || ownsItem("Construction cape") || ownsItem("Max cape"))
		{
			return true;
		}
		return spellbook() == 0 && skillLevel("MAGIC") >= 40;
	}

	@Override
	public boolean fairyRingsUsable()
	{
		if (!questStarted("FAIRYTALE_II__CURE_A_QUEEN"))
		{
			return false;
		}
		return ownsItem("Dramen staff") || ownsItem("Lunar staff") || diaryComplete("LUMBRIDGE_ELITE");
	}

	@Override
	public boolean ownsCannon()
	{
		return ownsItem("Cannon base") && ownsItem("Cannon barrels") && ownsItem("Cannon furnace") && ownsItem("Cannon stand");
	}

	@Override
	public int skillLevel(String skillConstant)
	{
		if (skillConstant == null || client.getGameState() != GameState.LOGGED_IN)
		{
			return -1;
		}
		try
		{
			return client.getRealSkillLevel(Skill.valueOf(skillConstant.toUpperCase(Locale.ROOT)));
		}
		catch (IllegalArgumentException e)
		{
			return -1;
		}
	}

	public boolean bankEverSeen()
	{
		return readiness.getBankSeenAt() > 0;
	}
}

package com.slayersuite.advisor;

/** What the scorer needs to know about the account; implemented from the client, stubbed in tests. */
public interface AccountView
{
	boolean questFinished(String questConstant);

	boolean questStarted(String questConstant);

	boolean diaryComplete(String diaryKey);

	/** 0 standard, 1 ancient, 2 lunar, 3 arceuus, -1 unknown. */
	int spellbook();

	boolean ownsItem(String itemName);

	boolean fairyRingsUsable();

	boolean ownsCannon();

	/** Real (unboosted) level of a skill by its net.runelite.api.Skill constant name; -1 when unknown. */
	int skillLevel(String skillConstant);

	/** Your house has this teleport facility (portal, mounted item, fairy ring...). */
	boolean hasHouseFacility(String facility);

	/** Your jewellery box covers this piece of jewellery. */
	boolean jewelleryBoxCovers(String itemName);

	/** The house has been looked at at least once. */
	boolean houseScanned();

	/** You can get home: Home Teleport on the standard book, a house tablet, or a Construction cape. */
	boolean canTeleportHome();
}

