import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * On the fairy ring's dial screen: the code the route wants, which dial to turn, which way and how
 * many clicks, then the teleport button once the dials read right. The way a clockwise click moves
 * the varbit is learned from the first click seen and remembered.
 */
public class FairyDialOverlay extends Overlay
{
	private static final int[] CLOCKWISE = {InterfaceID.Fairyrings._1_CLOCKWISE, InterfaceID.Fairyrings._2_CLOCKWISE, InterfaceID.Fairyrings._3_CLOCKWISE};
	private static final int[] ANTICLOCKWISE = {InterfaceID.Fairyrings._1_ANTICLOCKWISE, InterfaceID.Fairyrings._2_ANTICLOCKWISE, InterfaceID.Fairyrings._3_ANTICLOCKWISE};
	private static final int[] VARBITS = {VarbitID.FAIRYRING_1, VarbitID.FAIRYRING_2, VarbitID.FAIRYRING_3};
	static final String SENSE_KEY = "fairyDialSense";

	private final Client client;
	private final RouteService routes;
	private final SlayerSuiteConfig config;
	private final ConfigManager configManager;

	/** A rotate click waiting for its varbit change: dial, whether it was clockwise, the value before. */
	private int pendingDial = -1;
	private boolean pendingClockwise;
	private int pendingValue;

	@Inject
	public FairyDialOverlay(Client client, RouteService routes, SlayerSuiteConfig config, ConfigManager configManager)
	{
		this.client = client;
		this.routes = routes;
		this.config = config;
		this.configManager = configManager;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_HIGH);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.fairyDialHelper())
		{
			return null;
		}
		Widget confirm = client.getWidget(InterfaceID.Fairyrings.CONFIRM);
		if (confirm == null || confirm.isHidden())
		{
			return null;
		}
		String code = routes.nextFairyCode();
		if (!FairyDial.isCode(code))
		{
			return null;
		}
		int[] now = new int[3];
		for (int i = 0; i < 3; i++)
		{
			now[i] = client.getVarbitValue(VARBITS[i]);
		}
		Color accent = config.chevronColour().resolve(config.customChevronColour());
		int sense = sense();
		boolean allSet = true;
		g.setFont(FontManager.getRunescapeBoldFont());
		FontMetrics fm = g.getFontMetrics();
		for (int i = 0; i < 3; i++)
		{
			int target = FairyDial.index(i, code.charAt(i));
			int[] turn = FairyDial.turn(now[i], target, sense);
			if (turn[0] == 0)
			{
				continue;
			}
			allSet = false;
			Widget cw = client.getWidget(CLOCKWISE[i]);
			Widget acw = client.getWidget(ANTICLOCKWISE[i]);
			Widget button = turn[1] > 0 ? cw : acw;
			if (button == null || button.isHidden())
			{
				continue;
			}
			// the two rotate buttons are the halves of the dial: mark the whole dial once, above it,
			// with a curved arrow the way to turn and the number of clicks
			Rectangle b = button.getBounds();
			Rectangle other = (turn[1] > 0 ? acw : cw) == null ? b : (turn[1] > 0 ? acw : cw).getBounds();
			int left = Math.min(b.x, other.x);
			int right = Math.max(b.x + b.width, other.x + other.width);
			int cx = (left + right) / 2;
			int top = Math.min(b.y, other.y);
			String n = turn[0] + "x";
			int r = 11;
			int ax = cx - (r + 4 + fm.stringWidth(n)) / 2 + r;
			int ay = top - r - 6;
			arrow(g, ax, ay, r, turn[1] > 0, accent);
			shadowed(g, n, ax + r + 6, ay + fm.getAscent() / 2 - 1, accent);
			// the letter to reach, on the dial's own letter window
			String want = FairyDial.DIALS[i][target];
			shadowed(g, want, cx - fm.stringWidth(want) / 2, b.y + b.height + fm.getAscent() + 2, accent);
		}
		if (allSet)
		{
			Rectangle b = confirm.getBounds();
			outline(g, b, accent);
			String t = "Teleport";
			shadowed(g, t, b.x + (b.width - fm.stringWidth(t)) / 2, b.y - 6, accent);
		}
		// the code to set, above the dials
		Widget root = client.getWidget(InterfaceID.Fairyrings.ROOT_RECT0);
		Rectangle top = root != null && !root.isHidden() ? root.getBounds() : confirm.getBounds();
		String place = TransportTable.fairyPlace(code);
		String head = "Dial " + code + (place.isEmpty() ? "" : "  -  " + place);
		Font big = FontManager.getRunescapeBoldFont().deriveFont(18f);
		g.setFont(big);
		FontMetrics fb = g.getFontMetrics();
		int hx = top.x + (top.width - fb.stringWidth(head)) / 2;
		int hy = Math.max(fb.getAscent() + 4, top.y - 10);
		shadowed(g, head, hx, hy, accent);
		if (!allSet)
		{
			g.setFont(FontManager.getRunescapeFont());
			FontMetrics fs = g.getFontMetrics();
			String sub = "now " + FairyDial.letters(now);
			shadowed(g, sub, top.x + (top.width - fs.stringWidth(sub)) / 2, hy + fs.getHeight(), new Color(220, 220, 220));
		}
		return null;
	}

	/** A three-quarter circle with an arrowhead, clockwise or anticlockwise, centred on (cx, cy). */
	private static void arrow(Graphics2D g, int cx, int cy, int r, boolean clockwise, Color c)
	{
		Stroke old = g.getStroke();
		Object aa = g.getRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING);
		g.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING, java.awt.RenderingHints.VALUE_ANTIALIAS_ON);
		g.setStroke(new BasicStroke(3f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		// arc from the bottom round to the right side; mirrored for anticlockwise
		int start = clockwise ? 240 : -60;
		int extent = clockwise ? -270 : 270;
		g.setColor(Color.BLACK);
		g.drawArc(cx - r + 1, cy - r + 1, 2 * r, 2 * r, start, extent);
		g.setColor(c);
		g.drawArc(cx - r, cy - r, 2 * r, 2 * r, start, extent);
		// arrowhead at the arc's end (top of the circle), pointing the way round
		int hx = cx;
		int hy = cy - r;
		int dir = clockwise ? 1 : -1;
		int[] xs = {hx, hx - dir * 7, hx - dir * 1};
		int[] ys = {hy, hy - 5, hy + 6};
		g.setColor(Color.BLACK);
		g.fillPolygon(new int[]{xs[0] + 1, xs[1] + 1, xs[2] + 1}, new int[]{ys[0] + 1, ys[1] + 1, ys[2] + 1}, 3);
		g.setColor(c);
		g.fillPolygon(xs, ys, 3);
		g.setStroke(old);
		g.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING, aa == null ? java.awt.RenderingHints.VALUE_ANTIALIAS_DEFAULT : aa);
	}

	private static void outline(Graphics2D g, Rectangle b, Color c)
	{
		Stroke old = g.getStroke();
		g.setStroke(new BasicStroke(2f));
		g.setColor(c);
		g.drawRoundRect(b.x - 2, b.y - 2, b.width + 4, b.height + 4, 6, 6);
		g.setStroke(old);
	}

	private static void shadowed(Graphics2D g, String s, int x, int y, Color c)
	{
		g.setColor(Color.BLACK);
		g.drawString(s, x + 1, y + 1);
		g.setColor(c);
		g.drawString(s, x, y);
	}

	/** +1 when a clockwise click raises the dial's varbit (the geometry says so), -1 once a click proved otherwise. */
	private int sense()
	{
		Integer s = configManager.getConfiguration(SlayerSuiteConfig.GROUP, SENSE_KEY, Integer.class);
		return s == null || s >= 0 ? 1 : -1;
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked e)
	{
		int id = e.getParam1();
		for (int i = 0; i < 3; i++)
		{
			if (id == CLOCKWISE[i] || id == ANTICLOCKWISE[i])
			{
				pendingDial = i;
				pendingClockwise = id == CLOCKWISE[i];
				pendingValue = client.getVarbitValue(VARBITS[i]);
				return;
			}
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed e)
	{
		if (e.getGroupId() == InterfaceID.FAIRYRINGS)
		{
			pendingDial = -1;
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged e)
	{
		if (pendingDial < 0 || e.getVarbitId() != VARBITS[pendingDial])
		{
			return;
		}
		int delta = ((e.getValue() - pendingValue) % 4 + 4) % 4;
		pendingDial = -1;
		if (delta != 1 && delta != 3)
		{
			return;
		}
		boolean raised = delta == 1;
		int sense = (raised == pendingClockwise) ? 1 : -1;
		if (sense != sense())
		{
			configManager.setConfiguration(SlayerSuiteConfig.GROUP, SENSE_KEY, sense);
		}
	}
}

package com.slayersuite.advisor;

import com.slayersuite.SlayerSuiteConfig;
import com.slayersuite.trip.TripMath;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** An arrow on the minimap edge pointing at the chosen spot, with the distance. Display only. */
public class GpsOverlay extends Overlay
{
	private static final Color ARROW = new Color(80, 220, 255);
	private static final Color OUTLINE = new Color(0, 0, 0, 180);

	private final Client client;
	private final Advisor advisor;
	private final SlayerSuiteConfig config;
	private final com.slayersuite.task.SlayerMode mode;

	@Inject
	public GpsOverlay(Client client, Advisor advisor, SlayerSuiteConfig config, com.slayersuite.task.SlayerMode mode)
	{
		this.mode = mode;
		this.client = client;
		this.advisor = advisor;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_LOW);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.gpsArrow() || advisor.getDestination() == null || advisor.isArrived() || !mode.active())
		{
			return null;
		}
		WorldPoint dest = advisor.guidePoint();
		Player me = client.getLocalPlayer();
		if (dest == null || me == null)
		{
			return null;
		}
		WorldPoint wp = me.getWorldLocation();
		int dx = dest.getX() - wp.getX();
		int dy = dest.getY() - wp.getY();
		double len = Math.hypot(dx, dy);
		if (len < 6)
		{
			return null;
		}
		WorldView wv = client.getTopLevelWorldView();
		if (wv == null)
		{
			return null;
		}
		// a point ten tiles toward the destination is always in the loaded scene
		int px = wp.getX() + (int) Math.round(dx / len * 10);
		int py = wp.getY() + (int) Math.round(dy / len * 10);
		LocalPoint toward = LocalPoint.fromWorld(wv, px, py);
		LocalPoint here = me.getLocalLocation();
		if (toward == null || here == null)
		{
			return null;
		}
		Point tip = Perspective.localToMinimap(client, toward);
		Point centre = Perspective.localToMinimap(client, here);
		if (tip == null || centre == null)
		{
			return null;
		}
		double ang = Math.atan2(tip.getY() - centre.getY(), tip.getX() - centre.getX());
		int size = 9;
		Polygon tri = new Polygon();
		tri.addPoint((int) Math.round(tip.getX() + Math.cos(ang) * size), (int) Math.round(tip.getY() + Math.sin(ang) * size));
		tri.addPoint((int) Math.round(tip.getX() + Math.cos(ang + 2.5) * size), (int) Math.round(tip.getY() + Math.sin(ang + 2.5) * size));
		tri.addPoint((int) Math.round(tip.getX() + Math.cos(ang - 2.5) * size), (int) Math.round(tip.getY() + Math.sin(ang - 2.5) * size));
		Object aa = g.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(ARROW);
		g.fillPolygon(tri);
		g.setColor(OUTLINE);
		g.setStroke(new BasicStroke(1.5f));
		g.drawPolygon(tri);
		g.setFont(FontManager.getRunescapeSmallFont());
		String label = TripMath.formatK(Math.round(len));
		int tx = (int) Math.round(tip.getX() + Math.cos(ang) * (size + 10)) - g.getFontMetrics().stringWidth(label) / 2;
		int ty = (int) Math.round(tip.getY() + Math.sin(ang) * (size + 10)) + 4;
		g.setColor(Color.BLACK);
		g.drawString(label, tx + 1, ty + 1);
		g.setColor(ARROW);
		g.drawString(label, tx, ty);
		if (aa != null)
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, aa);
		}
		return null;
	}
}

package com.slayersuite.advisor;

import com.google.gson.Gson;
import com.slayersuite.SlayerSuiteConfig;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;
import java.util.TreeSet;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ObjectComposition;
import net.runelite.api.WorldView;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.RuneScapeProfileChanged;

/**
 * Remembers what teleport furniture your house has. The client only shows the
 * house while you stand in it, so every visit updates a list saved on the
 * RuneScape profile: portals, portal nexus, jewellery box tier, mounted glory,
 * talisman, pendant and cape, fairy ring, spirit tree, spellbook altars.
 */
@Slf4j
@Singleton
public class HouseScanner
{
	static final String KEY = "house";

	/** Object names (lower case) that only exist inside a player-owned house. */
	private static final Set<String> FACILITIES = new HashSet<>(Arrays.asList(
		"portal nexus", "fairy ring", "spirit tree", "spiritual fairy tree",
		"basic jewellery box", "fancy jewellery box", "ornate jewellery box",
		"amulet of glory", "xeric's talisman", "digsite pendant", "mythical cape",
		"occult altar", "altar of the occult", "ancient altar", "lunar altar", "dark altar",
		"obelisk", "pool of restoration", "pool of revitalisation", "pool of rejuvenation", "fancy pool of rejuvenation", "ornate pool of rejuvenation"));

	public static class House
	{
		public Set<String> facilities = new TreeSet<>();
		public boolean nexus;
		public boolean nexusXeric;
		public boolean nexusDigsite;
		public long updated;
	}

	private final Client client;
	private final ConfigManager configManager;
	private final Gson gson;

	@Getter
	private House house = new House();
	private boolean loaded;
	private boolean dirty;
	private int tick;

	@Inject
	public HouseScanner(Client client, ConfigManager configManager, Gson gson)
	{
		this.client = client;
		this.configManager = configManager;
		this.gson = gson;
	}

	public void reset()
	{
		loaded = false;
		dirty = false;
	}

	// ---------------------------------------------------------------- persistence

	private void load()
	{
		house = new House();
		try
		{
			String json = configManager.getRSProfileConfiguration(SlayerSuiteConfig.GROUP, KEY);
			if (json != null && !json.isEmpty())
			{
				House h = gson.fromJson(json, House.class);
				if (h != null)
				{
					if (h.facilities == null)
					{
						h.facilities = new TreeSet<>();
					}
					house = h;
				}
			}
		}
		catch (RuntimeException e)
		{
			log.debug("house load failed", e);
		}
		loaded = true;
	}

	private void save()
	{
		if (configManager.getRSProfileKey() == null)
		{
			return;
		}
		try
		{
			house.updated = System.currentTimeMillis();
			configManager.setRSProfileConfiguration(SlayerSuiteConfig.GROUP, KEY, gson.toJson(house));
			dirty = false;
		}
		catch (RuntimeException e)
		{
			log.debug("house save failed", e);
		}
	}

	// ---------------------------------------------------------------- queries

	public boolean scanned()
	{
		return house.updated > 0;
	}

	public boolean has(String facility)
	{
		if (facility == null)
		{
			return false;
		}
		String f = facility.toLowerCase(Locale.ROOT);
		if (f.equals("portal nexus"))
		{
			return house.nexus;
		}
		if (f.equals("fairy ring"))
		{
			return house.facilities.contains("fairy ring") || house.facilities.contains("spiritual fairy tree");
		}
		if (f.equals("spirit tree"))
		{
			return house.facilities.contains("spirit tree") || house.facilities.contains("spiritual fairy tree");
		}
		if (f.equals("xeric's talisman"))
		{
			return house.facilities.contains(f) || house.nexusXeric;
		}
		if (f.equals("digsite pendant"))
		{
			return house.facilities.contains(f) || house.nexusDigsite;
		}
		return house.facilities.contains(f);
	}

	/** Jewellery box tiers: basic = dueling and games; fancy adds skills and combat; ornate adds glory and wealth. */
	public boolean jewelleryBoxCovers(String itemName)
	{
		if (itemName == null)
		{
			return false;
		}
		String n = itemName.toLowerCase(Locale.ROOT);
		boolean basic = house.facilities.contains("basic jewellery box") || house.facilities.contains("fancy jewellery box") || house.facilities.contains("ornate jewellery box");
		boolean fancy = house.facilities.contains("fancy jewellery box") || house.facilities.contains("ornate jewellery box");
		boolean ornate = house.facilities.contains("ornate jewellery box");
		if (n.startsWith("ring of dueling") || n.startsWith("games necklace"))
		{
			return basic;
		}
		if (n.startsWith("skills necklace") || n.startsWith("combat bracelet"))
		{
			return fancy;
		}
		if (n.startsWith("amulet of glory") || n.startsWith("ring of wealth"))
		{
			return ornate;
		}
		return false;
	}

	public boolean hasSpellbookAltar()
	{
		return house.facilities.contains("occult altar") || house.facilities.contains("altar of the occult")
			|| house.facilities.contains("ancient altar") || house.facilities.contains("lunar altar") || house.facilities.contains("dark altar");
	}

	public Set<String> facilities()
	{
		return Collections.unmodifiableSet(house.facilities);
	}

	public String summary()
	{
		if (!scanned())
		{
			return "Not scanned yet: stand in your house once and I will remember its teleports.";
		}
		Set<String> all = new TreeSet<>(house.facilities);
		if (house.nexus)
		{
			all.add("portal nexus" + (house.nexusXeric ? " (xeric)" : "") + (house.nexusDigsite ? " (digsite)" : ""));
		}
		return all.isEmpty() ? "House scanned: no teleport furniture seen." : String.join(", ", all);
	}

	// ---------------------------------------------------------------- events

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		if (e.getGameState() == GameState.LOGGED_IN && !loaded)
		{
			load();
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged e)
	{
		load();
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned e)
	{
		WorldView wv = client.getTopLevelWorldView();
		if (wv == null || !wv.isInstance() || e.getGameObject() == null)
		{
			return;
		}
		if (!loaded)
		{
			load();
		}
		ObjectComposition def;
		try
		{
			def = client.getObjectDefinition(e.getGameObject().getId());
		}
		catch (RuntimeException ex)
		{
			return;
		}
		if (def == null || def.getName() == null)
		{
			return;
		}
		String name = def.getName().toLowerCase(Locale.ROOT).trim();
		if (name.isEmpty() || name.equals("null"))
		{
			return;
		}
		boolean portal = name.endsWith(" portal") && !name.equals("exit portal");
		if (portal || FACILITIES.contains(name))
		{
			if (name.equals("portal nexus"))
			{
				if (!house.nexus)
				{
					house.nexus = true;
					dirty = true;
				}
			}
			else if (house.facilities.add(name))
			{
				dirty = true;
				log.debug("house: found {}", name);
			}
		}
	}

	@Subscribe
	public void onGameTick(GameTick t)
	{
		if (!loaded)
		{
			return;
		}
		if (house.nexus)
		{
			WorldView wv = client.getTopLevelWorldView();
			if (wv != null && wv.isInstance())
			{
				boolean xeric = client.getVarbitValue(VarbitID.POH_NEXUS_XERIC) == 1;
				boolean digsite = client.getVarbitValue(VarbitID.POH_NEXUS_DIGSITE) == 1;
				if (xeric != house.nexusXeric || digsite != house.nexusDigsite)
				{
					house.nexusXeric = xeric;
					house.nexusDigsite = digsite;
					dirty = true;
				}
			}
		}
		if (dirty && ++tick % 10 == 0)
		{
			save();
		}
	}
}

package com.slayersuite.advisor;

import com.slayersuite.data.LocationRecord;
import com.slayersuite.data.TaskRecord;
import java.util.ArrayList;
import java.util.List;

/**
 * Ranks a task's locations for one account. Pure: everything it reads comes
 * through AccountView and the data files, so it can be unit-tested.
 */
public class LocationScorer
{
	public static class Options
	{
		public boolean avoidWilderness = true;
		public boolean preferCannon = true;
		public boolean preferMulti = true;
		/** Spot name -> {kills/h, gp/h, xp/h} from your own history on this task. */
		public java.util.Map<String, double[]> ownRates = java.util.Collections.emptyMap();
		/** Spot name -> ticks from where you stand, from the router; absent or negative means not known yet. */
		public java.util.Map<String, Integer> travelTicks = java.util.Collections.emptyMap();
		/** Where you stand (y folded onto the surface) for the straight-line guess; -1 when not logged in. */
		public int playerX = -1;
		public int playerY = -1;
		/** Kills left and your rate on this task, so travel is weighed against how long the task runs. */
		public int remainingKills;
		public double killsPerHour;
	}

	private final TravelData travel;

	public LocationScorer(TravelData travel)
	{
		this.travel = travel;
	}

	public List<ScoredLocation> rank(TaskRecord rec, AccountView account, Options opt)
	{
		List<ScoredLocation> out = new ArrayList<>();
		if (rec == null)
		{
			return out;
		}
		boolean immune = rec.cannonImmune();
		double worth = rec.cannonWorth();
		for (LocationRecord loc : rec.getLocations())
		{
			if (Boolean.TRUE.equals(loc.getBoss()))
			{
				continue;
			}
			out.add(score(loc, account, opt, immune, worth));
		}
		out.sort((a, b) -> Integer.compare(b.getScore(), a.getScore()));
		return out;
	}

	public ScoredLocation score(LocationRecord loc, AccountView account, Options opt)
	{
		return score(loc, account, opt, false);
	}

	public ScoredLocation score(LocationRecord loc, AccountView account, Options opt, boolean monstersCannonImmune)
	{
		return score(loc, account, opt, monstersCannonImmune, 1.0);
	}

	/** As above; cannonWorth (0 to 1) is how much a cannon or multi-target method helps on this task's monster. */
	public ScoredLocation score(LocationRecord loc, AccountView account, Options opt, boolean monstersCannonImmune, double cannonWorth)
	{
		List<String> reasons = new ArrayList<>();
		int score = 0;
		boolean locked = false;
		TravelData.Entry entry = travel.find(loc.getName());
		boolean wild = isWilderness(loc) || (entry != null && entry.isWilderness());

		if (entry != null)
		{
			for (TravelData.Requirement r : entry.getRequires())
			{
				if (r.getQuest() != null)
				{
					boolean ok = r.isStarted() ? account.questStarted(r.getQuest()) : account.questFinished(r.getQuest());
					if (!ok)
					{
						locked = true;
						reasons.add("needs " + pretty(r.getQuest()) + (r.isStarted() ? " started" : ""));
					}
				}
				if (r.getDiary() != null && !account.diaryComplete(r.getDiary()))
				{
					locked = true;
					reasons.add("needs " + pretty(r.getDiary()) + " diary");
				}
				if (r.getSkill() != null && r.getLevel() > 0)
				{
					int have = account.skillLevel(r.getSkill());
					if (have >= 0 && have < r.getLevel())
					{
						locked = true;
						reasons.add("needs " + r.getLevel() + " " + pretty(r.getSkill()) + " (you have " + have + ")");
					}
				}
			}
		}

		if (Boolean.TRUE.equals(loc.getCannon()))
		{
			if (monstersCannonImmune)
			{
				reasons.add("cannon allowed but the monsters are immune");
			}
			else if (cannonWorth < 0.3)
			{
				// a cannon on monsters that die in one hit only spends cannonballs
				reasons.add("cannon allowed, little use on monsters this weak");
			}
			else if (opt.preferCannon && account.ownsCannon())
			{
				if (account.questFinished("DWARF_CANNON"))
				{
					score += (int) Math.round(30 * cannonWorth);
					reasons.add("cannon");
				}
				else
				{
					score += (int) Math.round(5 * cannonWorth);
					reasons.add("cannon (finish Dwarf Cannon first)");
				}
			}
			else
			{
				score += (int) Math.round(5 * cannonWorth);
			}
		}
		if (Boolean.TRUE.equals(loc.getMulticombat()))
		{
			// multi only pays with monsters to share it and tough enough to be worth sharing: a one-spawn
			// multi area is no better than single, and one-hit monsters gain nothing from it
			boolean worthIt = loc.getSpawnCount() == 0 || loc.getSpawnCount() >= 3;
			score += worthIt ? (int) Math.round((opt.preferMulti ? 20 : 5) * Math.max(0.1, cannonWorth)) : 2;
			reasons.add("multi");
		}
		if (Boolean.TRUE.equals(loc.getSafespot()))
		{
			score += 8;
			reasons.add("safespot");
		}
		score += Math.min(loc.getSpawnCount(), 15);
		String own = null;
		double[] mine = opt.ownRates.get(loc.getName());
		if (mine != null)
		{
			own = Math.round(mine[0]) + " kills/h, " + com.slayersuite.trip.TripMath.formatK(Math.round(mine[1])) + " gp/h for you here";
			// the spot where you have done best, by xp/h then gp/h, gets the edge once you have played two or more
			boolean best = opt.ownRates.size() >= 2;
			for (double[] other : opt.ownRates.values())
			{
				if (other != mine && (other[2] > mine[2] || (other[2] == mine[2] && other[1] > mine[1])))
				{
					best = false;
				}
			}
			if (best)
			{
				score += 15;
				reasons.add("your best spot");
			}
		}

		String travelLabel = null;
		int bestHops = 99;
		if (entry != null)
		{
			for (TravelData.Teleport t : entry.getTeleports())
			{
				int hops = t.getHops();
				boolean have;
				if (t.getPoh() != null)
				{
					have = t.getItem() != null && t.getPoh().equalsIgnoreCase("Jewellery Box")
						? account.jewelleryBoxCovers(t.getItem()) : account.hasHouseFacility(t.getPoh());
					if (have && !account.canTeleportHome())
					{
						hops += 1;
					}
				}
				else if (t.getItem() != null)
				{
					have = account.ownsItem(t.getItem());
				}
				else if (t.getFairy() != null)
				{
					have = account.fairyRingsUsable();
				}
				else if (t.getSpell() != null)
				{
					have = (t.getQuest() == null || account.questFinished(t.getQuest()))
						&& (t.getLevel() <= 0 || account.skillLevel("MAGIC") < 0 || account.skillLevel("MAGIC") >= t.getLevel());
					int book = bookIndex(t.getBook());
					if (have && book >= 0 && account.spellbook() >= 0 && account.spellbook() != book)
					{
						hops += 1; // needs a spellbook swap first
					}
				}
				else
				{
					have = false;
				}
				if (have && hops < bestHops)
				{
					bestHops = hops;
					travelLabel = t.label();
				}
			}
		}
		if (travelLabel != null)
		{
			score += bestHops <= 1 ? 25 : bestHops == 2 ? 15 : 5;
			reasons.add(travelLabel + (bestHops <= 1 ? "" : bestHops == 2 ? " + short run" : " + long run"));
		}
		else if (entry != null && !entry.getTeleports().isEmpty())
		{
			reasons.add("no teleport you own");
		}

		// Getting there costs time the task does not have: a second of travel is worth 100/T points,
		// so a two-minute trip to a cannon spot loses on a forty-kill task and wins on a two-hundred-kill one.
		int travelSeconds = travelSeconds(loc, opt, travelLabel, bestHops);
		if (travelSeconds >= 0)
		{
			double taskSeconds = opt.remainingKills > 0 && opt.killsPerHour > 0 ? opt.remainingKills * 3600.0 / opt.killsPerHour : 600;
			taskSeconds = Math.max(120, Math.min(3600, taskSeconds));
			score -= (int) Math.round(travelSeconds * 100.0 / taskSeconds);
			reasons.add(travelWords(travelSeconds) + " from here");
		}

		if (wild)
		{
			reasons.add("Wilderness");
			if (opt.avoidWilderness)
			{
				score -= 40;
			}
		}
		if (locked)
		{
			score -= 100;
		}
		return new ScoredLocation(loc, score, locked, wild, travelLabel, reasons, own, travelSeconds);
	}

	/** Seconds to the spot from where you stand: the router's plan when it has answered, else a straight-line guess against the best teleport you own. */
	int travelSeconds(LocationRecord loc, Options opt, String travelLabel, int bestHops)
	{
		Integer ticks = loc.getName() == null || opt.travelTicks == null ? null : opt.travelTicks.get(loc.getName());
		if (ticks != null && ticks >= 0)
		{
			return (int) Math.round(ticks * 0.6);
		}
		if (opt.playerX < 0 || opt.playerY < 0)
		{
			return -1;
		}
		int d = straightLine(loc, opt.playerX, opt.playerY);
		// a spot stored in a detached map area is reached through its travel anchor on the ground
		int[] anchor = travel.anchor(loc.getName());
		if (anchor != null)
		{
			int da = (int) Math.round(Math.hypot(anchor[0] - opt.playerX, fold(anchor[1]) - opt.playerY));
			d = d < 0 ? da : Math.min(d, da);
		}
		if (d < 0)
		{
			return -1;
		}
		// running covers about 3.3 tiles a second and real routes run about 1.4x the straight line
		int walk = (int) Math.round(d / 2.4);
		int teleport = travelLabel == null ? Integer.MAX_VALUE : bestHops <= 1 ? 15 : bestHops == 2 ? 45 : 90;
		return Math.min(walk, teleport);
	}

	/** Tiles from (px, py) to the spot's nearest pin or its centre, dungeon levels folded onto the surface. */
	private static int straightLine(LocationRecord loc, int px, int py)
	{
		int best = -1;
		if (loc.getPins() != null)
		{
			for (List<Integer> pin : loc.getPins())
			{
				if (pin == null || pin.size() < 2)
				{
					continue;
				}
				int d = (int) Math.round(Math.hypot(pin.get(0) - px, fold(pin.get(1)) - py));
				if (best < 0 || d < best)
				{
					best = d;
				}
			}
		}
		if (best < 0 && loc.hasCoordinates())
		{
			best = (int) Math.round(Math.hypot(loc.getX() - px, fold(loc.getY()) - py));
		}
		return best;
	}

	private static int fold(int y)
	{
		return y >= 6400 ? y - 6400 : y;
	}

	/** "27s" or "3m". */
	public static String travelWords(int seconds)
	{
		return seconds < 90 ? seconds + "s" : Math.round(seconds / 60.0) + "m";
	}

	/** Region ids with y >= 3520 inside the Wilderness x band. */
	static boolean isWilderness(LocationRecord loc)
	{
		if (loc.getName() != null && loc.getName().toLowerCase(java.util.Locale.ROOT).contains("wilderness"))
		{
			return true;
		}
		if (loc.getRegions() == null)
		{
			return false;
		}
		for (int r : loc.getRegions())
		{
			int rx = r >> 8;
			int ry = r & 0xFF;
			// surface Wilderness: x 2944..3391 (columns 46..52), y 3520..3967 (rows 55..61); column 53 is Morytania
			if (ry >= 55 && ry <= 61 && rx >= 46 && rx <= 52)
			{
				return true;
			}
		}
		return false;
	}

	static int bookIndex(String book)
	{
		if (book == null)
		{
			return -1;
		}
		switch (book.toLowerCase())
		{
			case "standard":
				return 0;
			case "ancient":
				return 1;
			case "lunar":
				return 2;
			case "arceuus":
				return 3;
			default:
				return -1;
		}
	}

	static String pretty(String constant)
	{
		String s = constant.toLowerCase().replace("__", ": ").replace('_', ' ');
		return Character.toUpperCase(s.charAt(0)) + s.substring(1);
	}
}

package com.slayersuite.advisor;

import com.slayersuite.SlayerSuiteConfig;
import com.slayersuite.data.LocationRecord;
import com.slayersuite.data.TravelPoints;
import com.slayersuite.route.RouteService;
import com.slayersuite.task.TaskTracker;
import com.slayersuite.trip.TripTracker;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Provider;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.eventbus.Subscribe;

/**
 * Keeps the route going once an assignment ends: to the nearest bank you can use when food is low
 * or the inventory is nearly full, then back to the Slayer master you took the task from. The
 * advisor asks it every tick without a task and pins whatever it answers.
 */
@Slf4j
@Singleton
public class LoopGuide
{
	/** The loop runs this long after a task ends, or until the next one. */
	public static final long LOOP_MS = 20 * 60_000L;
	/** Standing at the bank this long without opening it: move on to the master. */
	private static final long BANK_WAIT_MS = 180_000L;
	/** Give the router this long before deciding a bank cannot be reached from here. */
	private static final long PLAN_SETTLE_MS = 4_000L;
	/** The master you spoke to in the last few hours is the one whose task this was. */
	private static final long MASTER_MEMORY_MS = 6 * 3_600_000L;
	private static final int CANDIDATES = 4;
	private static final int FOOD_SHORT = 3;
	private static final int SLOTS_SHORT = 3;

	public enum Leg
	{
		NONE, BANK, MASTER
	}

	private final Client client;
	private final SlayerSuiteConfig config;
	private final TaskTracker tracker;
	private final TravelPoints points;
	private final AccountState account;
	private final Provider<TripTracker> trip;
	private final RouteService routes;

	/** The task end this loop belongs to; a new end starts a new loop. */
	private long startedFor;
	@Getter
	private volatile Leg leg = Leg.NONE;
	private volatile LocationRecord target;
	private final List<LocationRecord> candidates = new ArrayList<>();
	private int candidate;
	private long candidateAt;
	private boolean bankOpen;
	private boolean banked;
	private long arrivedAt;
	private LocationRecord masterLoc;
	@Getter
	private volatile String masterName;
	@Getter
	private volatile String bankName;

	@Inject
	public LoopGuide(Client client, SlayerSuiteConfig config, TaskTracker tracker, TravelPoints points, AccountState account, Provider<TripTracker> trip, RouteService routes)
	{
		this.client = client;
		this.config = config;
		this.tracker = tracker;
		this.points = points;
		this.account = account;
		this.trip = trip;
		this.routes = routes;
	}

	public boolean active()
	{
		return leg != Leg.NONE;
	}

	/** True for a spot this guide handed out. */
	public boolean owns(LocationRecord loc)
	{
		return loc != null && (loc == target || loc == masterLoc || candidates.contains(loc));
	}

	/** "Bank first: Edgeville bank, then Konar quo Maten" or "Back to Krystilia". */
	public String describe()
	{
		switch (leg)
		{
			case BANK:
				return "Bank first: " + bankName + (masterName != null ? ", then " + masterName : "");
			case MASTER:
				return "Back to " + masterName;
			default:
				return "";
		}
	}

	/** Called each tick without a task, on the client thread: the spot to guide to now, or null. */
	LocationRecord tick(boolean arrivedAtTarget)
	{
		long now = System.currentTimeMillis();
		long fin = tracker.getFinishedAt();
		if (config.loopGuide() == LoopMode.OFF || fin <= 0 || now - fin > LOOP_MS || tracker.hasTask())
		{
			if (leg != Leg.NONE || startedFor != 0)
			{
				reset();
			}
			return null;
		}
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			// a hop, a loading screen or a dropped connection: hold what we have rather than start again
			return leg == Leg.NONE ? null : target;
		}
		if (startedFor != fin)
		{
			begin(fin, now);
		}
		if (leg == Leg.BANK)
		{
			if (arrivedAtTarget && arrivedAt == 0)
			{
				arrivedAt = now;
			}
			boolean done = banked && !bankOpen;
			boolean gaveUp = arrivedAt > 0 && now - arrivedAt > BANK_WAIT_MS;
			if (done || gaveUp)
			{
				toMaster();
			}
			else if (!arrivedAtTarget && now - candidateAt > PLAN_SETTLE_MS && routes.plan() != null && !routes.reached())
			{
				// the router cannot get to this bank from here: the next nearest, then the master
				if (candidate + 1 < candidates.size())
				{
					candidate++;
					target = candidates.get(candidate);
					candidateAt = now;
					bankName = target.getName();
				}
				else
				{
					toMaster();
				}
			}
		}
		if (leg == Leg.MASTER && target == null)
		{
			leg = Leg.NONE;
		}
		return leg == Leg.NONE ? null : target;
	}

	private void begin(long fin, long now)
	{
		startedFor = fin;
		candidates.clear();
		candidate = 0;
		candidateAt = now;
		arrivedAt = 0;
		banked = false;
		target = null;
		masterLoc = masterSpot();
		masterName = masterLoc == null ? null : masterLoc.getName();
		if (config.loopGuide() == LoopMode.BANK_THEN_MASTER && suppliesShort())
		{
			candidates.addAll(bankCandidates());
		}
		if (!candidates.isEmpty())
		{
			leg = Leg.BANK;
			target = candidates.get(0);
			bankName = target.getName();
		}
		else
		{
			toMaster();
		}
		log.debug("Slayer Suite loop: {} ({} bank candidates, master {})", leg, candidates.size(), masterName);
	}

	private void toMaster()
	{
		bankName = null;
		target = masterLoc;
		leg = masterLoc == null ? Leg.NONE : Leg.MASTER;
	}

	private void reset()
	{
		startedFor = 0;
		leg = Leg.NONE;
		target = null;
		masterLoc = null;
		masterName = null;
		bankName = null;
		candidates.clear();
		candidate = 0;
		arrivedAt = 0;
		banked = false;
	}

	/** The master you spoke to most recently, else the one whose list the finished task came from. */
	private LocationRecord masterSpot()
	{
		TravelPoints.Point p = null;
		String who = tracker.getLastMasterName();
		if (who != null && System.currentTimeMillis() - tracker.getLastMasterAt() < MASTER_MEMORY_MS)
		{
			p = points.master(who);
		}
		if (p == null)
		{
			p = points.masterFor(tracker.getLastMasterId());
		}
		if (p == null)
		{
			return null;
		}
		String place = p.getPlace() == null || p.getPlace().isEmpty() ? "" : " (" + p.getPlace() + ")";
		return spot(p.getName() + place, p);
	}

	private List<LocationRecord> bankCandidates()
	{
		Player me = client.getLocalPlayer();
		if (me == null)
		{
			return Collections.emptyList();
		}
		WorldPoint wp = me.getWorldLocation();
		List<TravelPoints.Point> usable = new ArrayList<>();
		for (TravelPoints.Point b : points.banks())
		{
			if (meets(TravelPoints.requirement(b.getRequirement())))
			{
				usable.add(b);
			}
		}
		List<LocationRecord> out = new ArrayList<>();
		for (TravelPoints.Point b : TravelPoints.nearest(usable, wp.getX(), wp.getY(), CANDIDATES))
		{
			out.add(spot(b.getName(), b));
		}
		return out;
	}

	private boolean meets(TravelPoints.Requirement r)
	{
		switch (r.kind)
		{
			case NONE:
				return true;
			case QUEST:
				return account.questFinished(r.key);
			case SKILL:
				return account.skillLevel(r.key) >= r.level;
			case DIARY:
				return account.diaryComplete(r.key);
			default:
				return false;
		}
	}

	/** Fewer than three food, or three or fewer free inventory slots. */
	boolean suppliesShort()
	{
		TripTracker t = trip.get();
		// an inventory not read yet is not short
		int food = t == null || !t.foodKnown() ? Integer.MAX_VALUE : t.getFoodCount();
		return food < FOOD_SHORT || freeSlots() <= SLOTS_SHORT;
	}

	private int freeSlots()
	{
		ItemContainer inv = client.getItemContainer(InventoryID.INV);
		if (inv == null)
		{
			return 28;
		}
		int used = 0;
		for (Item it : inv.getItems())
		{
			if (it != null && it.getId() > 0)
			{
				used++;
			}
		}
		return Math.max(0, 28 - used);
	}

	private static LocationRecord spot(String name, TravelPoints.Point p)
	{
		LocationRecord r = new LocationRecord();
		r.setName(name);
		r.setX(p.getX());
		r.setY(p.getY());
		r.setPlane(p.getPlane());
		List<Integer> regions = new ArrayList<>();
		regions.add(((p.getX() >> 6) << 8) | (p.getY() >> 6));
		r.setRegions(regions);
		return r;
	}

	private static boolean isBank(int groupId)
	{
		return groupId == InterfaceID.BANKMAIN || groupId == InterfaceID.BANK_DEPOSITBOX;
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded e)
	{
		if (isBank(e.getGroupId()))
		{
			bankOpen = true;
			if (leg == Leg.BANK)
			{
				banked = true;
			}
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed e)
	{
		if (isBank(e.getGroupId()))
		{
			bankOpen = false;
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		if (e.getGameState() == GameState.LOGIN_SCREEN || e.getGameState() == GameState.HOPPING)
		{
			// keep the leg and what was banked; only the timing starts over
			arrivedAt = 0;
			candidateAt = System.currentTimeMillis();
			bankOpen = false;
		}
	}
}

package com.slayersuite.advisor;

/** What the route does once an assignment ends. */
public enum LoopMode
{
	OFF("Off"),
	MASTER("Back to the master"),
	BANK_THEN_MASTER("Bank when short, then the master");

	private final String label;

	LoopMode(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.slayersuite.advisor;

import com.slayersuite.SlayerSuiteConfig;
import java.awt.Color;
import com.slayersuite.ui.Palette;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * A checklist of enabled plugins that do what Slayer Suite does, so you can search the plugin
 * list and switch them off one by one. It rescans every two seconds and disappears on its own
 * once they are all off.
 */
public class OverlapOverlay extends OverlayPanel
{
	private static final Color ACCENT = new Color(255, 176, 0);
	private static final Color DIM = Palette.DIM;
	private static final long RESCAN_MS = 2000;

	private final Client client;
	private final PluginOverlap overlap;
	private final SlayerSuiteConfig config;
	private long lastScan;

	@Inject
	public OverlapOverlay(Client client, PluginOverlap overlap, SlayerSuiteConfig config)
	{
		this.client = client;
		this.overlap = overlap;
		this.config = config;
		setPosition(OverlayPosition.TOP_CENTER);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_HIGH);
		panelComponent.setPreferredSize(new Dimension(330, 0));
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.overlapNotice() || client.getGameState() != GameState.LOGGED_IN)
		{
			return null;
		}
		long now = System.currentTimeMillis();
		if (now - lastScan > RESCAN_MS)
		{
			lastScan = now;
			overlap.scan();
		}
		List<String> active = overlap.active();
		if (active.isEmpty())
		{
			return null;
		}
		panelComponent.getChildren().add(TitleComponent.builder().text("Slayer Suite does these jobs now").color(ACCENT).build());
		panelComponent.getChildren().add(LineComponent.builder().left("Turn these plugins off to avoid doubled overlays and alerts:").leftColor(Color.WHITE).build());
		for (String s : active)
		{
			int i = s.indexOf(':');
			String name = i > 0 ? s.substring(0, i) : s;
			String why = i > 0 ? s.substring(i + 1).trim() : "";
			panelComponent.getChildren().add(LineComponent.builder().left("  " + name).leftColor(Color.WHITE).right("on").rightColor(new Color(255, 90, 90)).build());
			if (!why.isEmpty())
			{
				panelComponent.getChildren().add(LineComponent.builder().left("     " + why).leftColor(DIM).build());
			}
		}
		panelComponent.getChildren().add(LineComponent.builder().left("This notice goes away by itself once they are off. To hide it instead: Slayer Suite settings, Overlapping plugins notice.").leftColor(DIM).build());
		return super.render(g);
	}
}

