	private static List<TaskHistory.LootItem> toItems(List<long[]> raw)
	{
		List<TaskHistory.LootItem> items = new ArrayList<>();
		if (raw == null)
		{
			return items;
		}
		for (long[] it : raw)
		{
			if (it != null && it.length == 3)
			{
				items.add(new TaskHistory.LootItem((int) it[0], it[1], it[2]));
			}
		}
		return items;
	}

