/**
 * One alert engine: evaluates every source each game tick, keeps one active
 * alert per kind, de-duplicates, re-notifies unresolved sticky alerts, and
 * fans out to the banner, the RuneLite notifier, the chat and the sounds.
 */
@Slf4j
@Singleton
public class AlertEngine
{
	private static final int VENOM_THRESHOLD = 1_000_000;
	private static final Skill[] BOOST_SKILLS = {Skill.ATTACK, Skill.STRENGTH, Skill.DEFENCE, Skill.RANGED, Skill.MAGIC};

	private final Client client;
	private final SlayerSuiteConfig config;
	private final TaskTracker tracker;
	private final ReadinessChecker readiness;
	private final AttackGuard guard;
	private final Notifier notifier;
	private final SoundPlayer sounds;
	private final javax.inject.Provider<com.slayersuite.task.SlayerMode> mode;
	private final javax.inject.Provider<com.slayersuite.history.TaskHistory> history;
	/** The vanish time of the floor drop last warned about, so each is called once. */
	private long floorWarnedFor;
	/** Damage you took, newest last: {time, amount}, kept for the trend window. */
	private final java.util.ArrayDeque<long[]> damage = new java.util.ArrayDeque<>();
	private long trendWarnedAt;
	/** When the superior sound last played again for a superior nobody has attacked. */
	private long superiorNudgeAt;
	private static final long SUPERIOR_NUDGE_MS = 8_000L;
	private static final long DAMAGE_WINDOW_MS = 15_000L;
	private static final long TREND_REPEAT_MS = 8_000L;

	private final Map<AlertKind, Alert> active = new EnumMap<>(AlertKind.class);
	private final Map<Skill, Integer> peakBoost = new EnumMap<>(Skill.class);
	private final Map<Skill, Integer> realLevels = new EnumMap<>(Skill.class);

	@Getter
	private boolean paused;
	@Getter
	private long pausedUntil;
	private long lastCombatAt;
	private long lastStreakWarnAt;
	private long lastMovedAt;
	private WorldPoint lastTile;
	private boolean wasInArea;
	private boolean nearlyDoneFired;
	private long lastOffTaskAt;

	@Getter
	private final HotkeyListener pauseHotkey;

	@Inject
	public AlertEngine(Client client, SlayerSuiteConfig config, TaskTracker tracker, ReadinessChecker readiness, AttackGuard guard, Notifier notifier, SoundPlayer sounds, javax.inject.Provider<com.slayersuite.task.SlayerMode> mode, javax.inject.Provider<com.slayersuite.history.TaskHistory> history)
	{
		this.mode = mode;
		this.history = history;
		this.client = client;
		this.config = config;
		this.tracker = tracker;
		this.readiness = readiness;
		this.guard = guard;
		this.notifier = notifier;
		this.sounds = sounds;
		this.pauseHotkey = new HotkeyListener(config::pauseHotkey)
		{
			@Override
			public void hotkeyPressed()
			{
				togglePause();
			}
		};
	}

	public void reset()
	{
		active.clear();
		peakBoost.clear();
		paused = false;
		pausedUntil = 0;
		lastCombatAt = System.currentTimeMillis();
		nearlyDoneFired = false;
	}

	public void togglePause()
	{
		if (paused)
		{
			paused = false;
			pausedUntil = 0;
		}
		else
		{
			paused = true;
			pausedUntil = System.currentTimeMillis() + config.pauseMinutes() * 60_000L;
			active.clear();
		}
	}

	/** The alert that owns the banner right now, or null. */
	public Alert top()
	{
		Alert best = null;
		for (Alert a : active.values())
		{
			if (best == null || a.getKind().getPriority() > best.getKind().getPriority())
			{
				best = a;
			}
		}
		return best;
	}

	public int activeCount()
	{
		return active.size();
	}

	public List<Alert> activeAlerts()
	{
		List<Alert> out = new ArrayList<>(active.values());
		out.sort((a, b) -> Integer.compare(b.getKind().getPriority(), a.getKind().getPriority()));
		return out;
	}

	// ---------------------------------------------------------------- raise / clear

	/**
	 * A superior is standing and you have not attacked it: a sticky warning with where it is, and
	 * the superior sound again every eight seconds until you do. Clears the moment you engage it.
	 */
	private void checkSuperior(long now)
	{
		NPC s = tracker.getSuperior();
		if (s == null || tracker.isSuperiorEngaged())
		{
			clear(AlertKind.SUPERIOR_UP);
			return;
		}
		String name = tracker.getSuperiorName() == null ? "Superior" : tracker.getSuperiorName();
		String where = "";
		Player me = client.getLocalPlayer();
		WorldPoint a = me == null ? null : me.getWorldLocation();
		WorldPoint b = s.getWorldLocation();
		if (a != null && b != null && a.getPlane() == b.getPlane())
		{
			int d = a.distanceTo(b);
			where = d <= 1 ? ", beside you" : ", " + d + " tiles " + direction(b.getX() - a.getX(), b.getY() - a.getY());
		}
		raise(AlertKind.SUPERIOR_UP, name + " is up" + where + ": attack it");
		long since = now - tracker.getSuperiorSpawnAt();
		if (since >= SUPERIOR_NUDGE_MS && now - superiorNudgeAt >= SUPERIOR_NUDGE_MS)
		{
			superiorNudgeAt = now;
			raise(AlertKind.SUPERIOR, name + " still up: attack it");
		}
	}

	private static String direction(int dx, int dy)
	{
		if (dx == 0 && dy == 0)
		{
			return "here";
		}
		String[] names = {"E", "NE", "N", "NW", "W", "SW", "S", "SE"};
		double ang = Math.toDegrees(Math.atan2(dy, dx));
		if (ang < 0)
		{
			ang += 360;
		}
		return names[(int) Math.round(ang / 45.0) % 8];
	}

	/** A marked drop of yours has half a minute left on the floor. */
	private void checkFloor(long now)
	{
		if (!config.alertFloorLoot() || !config.floorLoot())
		{
			return;
		}
		com.slayersuite.history.TaskHistory h = history.get();
		long value = h.getFloorValue();
		long soonest = h.getFloorSoonestAt();
		if (value <= 0 || soonest <= 0)
		{
			return;
		}
		long left = soonest - now;
		if (left > 0 && left <= com.slayersuite.history.FloorLootMath.URGENT_MS && floorWarnedFor != soonest)
		{
			floorWarnedFor = soonest;
			long going = h.getFloorSoonestValue() > 0 ? h.getFloorSoonestValue() : value;
			raise(AlertKind.FLOOR_LOOT, com.slayersuite.trip.TripMath.formatK(going) + " gp of yours on the floor vanishes in " + (left / 1000) + "s");
		}
	}

	private void raise(AlertKind kind, String message)
	{
		raise(kind, message, kind.getSeverity(), true);
	}

	private void raise(AlertKind kind, String message, Severity severity, boolean notify)
	{
		if (!config.alertsEnabled() || paused)
		{
			return;
		}
		long now = System.currentTimeMillis();
		Alert existing = active.get(kind);
		if (existing != null && !kind.isSticky())
		{
			// an event (task done, superior, cannon...) happening again is a new event: deliver it again
			active.remove(kind);
			existing = null;
		}
		if (existing != null)
		{
			existing.setMessage(message);
			if (severity.ordinal() > existing.getSeverity().ordinal())
			{
				existing.setSeverity(severity);
				deliver(existing, notify);
				existing.setLastNotifiedAt(now);
			}
			return;
		}
		Alert alert = new Alert(kind, message, severity, now);
		active.put(kind, alert);
		deliver(alert, notify);
	}

	private void clear(AlertKind kind)
	{
		active.remove(kind);
	}

	private void deliver(Alert alert, boolean notify)
	{
		if (notify)
		{
			Notification n;
			switch (alert.getSeverity())
			{
				case CRITICAL:
					n = config.notifyCritical();
					break;
				case WARNING:
					n = config.notifyWarning();
					break;
				default:
					n = config.notifyInfo();
			}
			try
			{
				notifier.notify(n, "Slayer: " + alert.getMessage());
			}
			catch (RuntimeException e)
			{
				log.debug("notify failed", e);
			}
		}
		if (config.alertChat() && client.getGameState() == GameState.LOGGED_IN)
		{
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "<col=ff5050>Slayer Suite:</col> " + alert.getMessage(), null);
		}
		int vol = config.soundVolume();
		if (alert.getKind() == AlertKind.TASK_DONE)
		{
			if (config.soundTaskDone())
			{
				sounds.play(SoundPlayer.Sound.TASK_DONE, vol);
			}
		}
		else if (alert.getKind() == AlertKind.SUPERIOR)
		{
			if (config.soundSuperior())
			{
				sounds.play(SoundPlayer.Sound.SUPERIOR, vol);
			}
		}
		else if (alert.getSeverity() == Severity.CRITICAL && config.soundCritical())
		{
			sounds.play(SoundPlayer.Sound.ALERT, vol);
		}
	}

	// ---------------------------------------------------------------- per-tick evaluation

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		if (e.getGameState() == GameState.LOGIN_SCREEN || e.getGameState() == GameState.HOPPING)
		{
			active.clear();
			realLevels.clear();
			damage.clear();
			lastCombatAt = System.currentTimeMillis();
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		long now = System.currentTimeMillis();
		if (!config.alertsEnabled())
		{
			active.clear();
			return;
		}
		if (paused && now > pausedUntil)
		{
			paused = false;
		}
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		Player me = client.getLocalPlayer();
		if (me == null)
		{
			return;
		}

		// expire transients
		active.values().removeIf(a -> a.expired(now));

		if (mode.get().active())
		{
			checkHitpoints();
			checkPrayer();
			checkPoison();
			checkBoosts();
			checkCombat(me, now);
		}
		else
		{
			clear(AlertKind.LOW_HP);
			clear(AlertKind.LOW_PRAYER);
			clear(AlertKind.POISON);
			clear(AlertKind.VENOM);
			clear(AlertKind.OUT_OF_COMBAT);
		}
		checkBank();
		checkFloor(now);
		checkSuperior(now);

		// re-notify unresolved sticky alerts
		for (Alert a : active.values())
		{
			if (a.getKind().isSticky() && now - a.getLastNotifiedAt() >= config.renotifySeconds() * 1000L)
			{
				a.setLastNotifiedAt(now);
				deliver(a, true);
			}
		}
	}

	private void checkHitpoints()
	{
		int cur = client.getBoostedSkillLevel(Skill.HITPOINTS);
		int max = client.getRealSkillLevel(Skill.HITPOINTS);
		if (max > 0 && cur * 100 <= config.hpPercent() * max)
		{
			raise(AlertKind.LOW_HP, "Hitpoints " + cur + "/" + max);
		}
		else
		{
			clear(AlertKind.LOW_HP);
			checkTrend(cur, max, System.currentTimeMillis());
		}
	}

	/**
	 * Your own Hitpoints trend: the damage you took in the last fifteen seconds, carried on at that
	 * rate, reaches the low mark within the configured seconds. Nothing here looks at what a monster
	 * is about to do; it is your own recent history, projected.
	 */
	private void checkTrend(int cur, int max, long now)
	{
		int seconds = config.hpTrendSeconds();
		if (seconds <= 0 || max <= 0)
		{
			return;
		}
		while (!damage.isEmpty() && now - damage.peekFirst()[0] > DAMAGE_WINDOW_MS)
		{
			damage.pollFirst();
		}
		if (damage.size() < 2)
		{
			return;
		}
		long taken = 0;
		for (long[] d : damage)
		{
			taken += d[1];
		}
		int threshold = (int) Math.ceil(config.hpPercent() * max / 100.0);
		if (taken <= 0 || cur <= threshold)
		{
			return;
		}
		double perSecond = taken / (DAMAGE_WINDOW_MS / 1000.0);
		double toMark = (cur - threshold) / perSecond;
		if (toMark <= seconds && now - trendWarnedAt >= TREND_REPEAT_MS)
		{
			trendWarnedAt = now;
			raise(AlertKind.HP_TREND, "Hitpoints " + cur + " falling fast: " + threshold + " in about " + Math.max(1, Math.round(toMark)) + "s at this rate");
		}
	}

	private void checkPrayer()
	{
		int cur = client.getBoostedSkillLevel(Skill.PRAYER);
		boolean relevant = readiness.hasGroup("prayer_restore") || cur < client.getRealSkillLevel(Skill.PRAYER);
		if (relevant && cur <= config.prayerPoints())
		{
			raise(AlertKind.LOW_PRAYER, "Prayer " + cur);
		}
		else
		{
			clear(AlertKind.LOW_PRAYER);
		}
	}

	private void checkPoison()
	{
		int v = client.getVarpValue(VarPlayerID.POISON);
		if (v >= VENOM_THRESHOLD)
		{
			clear(AlertKind.POISON);
			raise(AlertKind.VENOM, readiness.hasGroup("antivenom") ? "Venomed: drink anti-venom" : "Venomed and no anti-venom!");
		}
		else if (v > 0)
		{
			clear(AlertKind.VENOM);
			boolean cure = readiness.hasGroup("antipoison");
			raise(AlertKind.POISON, cure ? "Poisoned: drink antipoison" : "Poisoned and no antipoison!", cure ? Severity.WARNING : Severity.CRITICAL, true);
		}
		else
		{
			clear(AlertKind.POISON);
			clear(AlertKind.VENOM);
		}
	}

	private void checkBoosts()
	{
		for (Skill s : BOOST_SKILLS)
		{
			int boost = client.getBoostedSkillLevel(s) - client.getRealSkillLevel(s);
			int peak = peakBoost.getOrDefault(s, 0);
			if (boost >= 5)
			{
				if (boost > peak)
				{
					peakBoost.put(s, boost);
				}
			}
			else if (peak >= 5 && boost <= config.boostDropAt())
			{
				peakBoost.put(s, 0);
				raise(AlertKind.BOOST_DROPPED, pretty(s.getName()) + " boost has worn off");
			}
		}
	}

	private void checkCombat(Player me, long now)
	{
		boolean inArea = tracker.hasTask() && tracker.isInTaskArea();
		if (inArea && !wasInArea)
		{
			lastCombatAt = now;
		}
		wasInArea = inArea;
		if (me.getInteracting() != null)
		{
			lastCombatAt = now;
		}
		else
		{
			WorldView wv = client.getTopLevelWorldView();
			if (wv != null)
			{
				for (NPC npc : wv.npcs())
				{
					if (npc != null && npc.getInteracting() == me)
					{
						lastCombatAt = now;
						break;
					}
				}
			}
		}
		WorldPoint tile = me.getWorldLocation();
		if (tile != null && (lastTile == null || !tile.equals(lastTile)))
		{
			lastTile = tile;
			lastMovedAt = now;
		}
		long quietSince = Math.max(lastCombatAt, lastMovedAt);
		if (inArea && !readiness.isBankOpen() && now - quietSince >= config.idleSeconds() * 1000L)
		{
			raise(AlertKind.OUT_OF_COMBAT, "Standing idle for " + ((now - quietSince) / 1000) + "s");
		}
		else
		{
			clear(AlertKind.OUT_OF_COMBAT);
		}
	}

	private void checkBank()
	{
		if (readiness.isBankOpen() && tracker.hasTask())
		{
			List<Missing> req = readiness.requiredMissing();
			if (!req.isEmpty())
			{
				raise(AlertKind.MISSING_ITEMS, "Missing: " + joinLabels(req, 3), Severity.WARNING, false);
				return;
			}
		}
		clear(AlertKind.MISSING_ITEMS);
	}

	// ---------------------------------------------------------------- event sources

	@Subscribe
	public void onStatChanged(StatChanged e)
	{
		Integer prev = realLevels.put(e.getSkill(), e.getLevel());
		if (prev != null && e.getLevel() > prev && config.soundLevelUp() && client.getGameState() == GameState.LOGGED_IN)
		{
			sounds.play(SoundPlayer.Sound.LEVEL_UP, config.soundVolume());
		}
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied e)
	{
		if (e.getActor() == client.getLocalPlayer())
		{
			long now = System.currentTimeMillis();
			lastCombatAt = now;
			int amount = e.getHitsplat() == null ? 0 : e.getHitsplat().getAmount();
			if (amount > 0 && e.getHitsplat().getHitsplatType() != HitsplatID.HEAL)
			{
				damage.addLast(new long[]{now, amount});
				while (damage.size() > 60)
				{
					damage.pollFirst();
				}
			}
		}
	}

	@Subscribe
	public void onInteractingChanged(InteractingChanged e)
	{
		Player me = client.getLocalPlayer();
		if (me == null)
		{
			return;
		}
		Actor target = e.getTarget();
		if (e.getSource() == me && target instanceof NPC)
		{
			String who = ((NPC) target).getName();
			if (who != null && (who.equals("Turael") || who.equals("Aya") || who.equals("Spria")) && tracker.hasTask() && tracker.getTaskStreak() >= 5)
			{
				long now = System.currentTimeMillis();
				if (now - lastStreakWarnAt > 60_000L)
				{
					lastStreakWarnAt = now;
					raise(AlertKind.STREAK_RESET, "A new task from " + who + " resets your streak of " + tracker.getTaskStreak());
				}
				return;
			}
			lastCombatAt = System.currentTimeMillis();
			if (config.alertOffTask() && tracker.hasTask())
			{
				NPC npc = (NPC) target;
				if (attackable(npc) && !guard.isTaskTarget(npc))
				{
					long now = System.currentTimeMillis();
					if (now - lastOffTaskAt > 5_000L)
					{
						lastOffTaskAt = now;
						raise(AlertKind.OFF_TASK, npcName(npc) + " is not your task");
					}
				}
			}
		}
		else if (target == me && e.getSource() instanceof NPC)
		{
			lastCombatAt = System.currentTimeMillis();
		}
	}

	private static boolean attackable(NPC npc)
	{
		NPCComposition comp = npc.getTransformedComposition();
		if (comp == null)
		{
			return false;
		}
		String[] actions = comp.getActions();
		if (actions == null)
		{
			return false;
		}
		for (String a : actions)
		{
			if ("Attack".equalsIgnoreCase(a))
			{
				return true;
			}
		}
		return false;
	}

	private static String npcName(NPC npc)
	{
		NPCComposition comp = npc.getTransformedComposition();
		String n = comp == null ? npc.getName() : comp.getName();
		return n == null ? "That NPC" : n;
	}

	@Subscribe
	public void onChatMessage(ChatMessage e)
	{
		if (!config.alertCannon() || !mode.get().active())
		{
			return;
		}
		if (e.getType() != ChatMessageType.GAMEMESSAGE && e.getType() != ChatMessageType.SPAM)
		{
			return;
		}
		String msg = e.getMessage() == null ? "" : e.getMessage().replaceAll("<[^>]*>", "").toLowerCase(Locale.ROOT);
		if (!msg.contains("cannon"))
		{
			return;
		}
		if (msg.contains("out of ammo"))
		{
			raise(AlertKind.CANNON, "Cannon is out of ammo");
		}
		else if (msg.contains("broken"))
		{
			raise(AlertKind.CANNON, "Cannon has broken");
		}
		else if (msg.contains("decay"))
		{
			raise(AlertKind.CANNON, "Cannon is about to decay");
		}
	}

	@Subscribe
	public void onNotificationFired(NotificationFired e)
	{
		if (!config.alertAggression() || e.getMessage() == null || !mode.get().active())
		{
			return;
		}
		String m = e.getMessage().toLowerCase(Locale.ROOT);
		if (m.contains("aggress"))
		{
			// The source plugin already notified; banner only.
			raise(AlertKind.AGGRESSION, e.getMessage(), Severity.WARNING, false);
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed e)
	{
		if (e.getGroupId() != InterfaceID.BANKMAIN || !config.alertLeftBank() || !tracker.hasTask())
		{
			return;
		}
		List<Missing> req = readiness.requiredMissing();
		if (!req.isEmpty())
		{
			raise(AlertKind.LEFT_BANK, "Left the bank without: " + joinLabels(req, 3));
		}
	}

	@Subscribe
	public void onTaskChanged(TaskChanged e)
	{
		nearlyDoneFired = false;
		peakBoost.clear();
		lastCombatAt = System.currentTimeMillis();
		clear(AlertKind.OUT_OF_COMBAT);
		clear(AlertKind.MISSING_ITEMS);
	}

	@Subscribe
	public void onKillCounted(KillCounted e)
	{
		lastCombatAt = System.currentTimeMillis();
		if (!nearlyDoneFired && e.getRemaining() > 0 && e.getRemaining() <= config.nearlyDoneAt())
		{
			nearlyDoneFired = true;
			raise(AlertKind.NEARLY_DONE, e.getRemaining() + " kills left");
		}
	}

	@Subscribe
	public void onSuperiorSpawned(SuperiorSpawned e)
	{
		TaskRecord rec = tracker.getRecord();
		String name = rec != null && !rec.getSuperiors().isEmpty() ? rec.getSuperiors().get(0) : "Superior";
		raise(AlertKind.SUPERIOR, name + " has spawned");
	}

	@Subscribe
	public void onSuppliesLow(SuppliesLow e)
	{
		if (!mode.get().active())
		{
			return;
		}
		raise(AlertKind.SUPPLIES_LOW, "Supplies run out " + e.getShortfall() + " kills early (" + e.getResource() + "), bank after this trip");
	}

	@Subscribe
	public void onTaskFinished(TaskFinished e)
	{
		raise(AlertKind.TASK_DONE, "Task done: " + pretty(e.getName()));
	}

	/** For the ::ss alert test command: a critical alert that expires on its own. */
	public void testAlert()
	{
		boolean wasPaused = paused;
		paused = false;
		raise(AlertKind.LEFT_BANK, "Test alert: this is what a critical alert looks like", Severity.CRITICAL, true);
		paused = wasPaused;
	}

	// ---------------------------------------------------------------- helpers

	private static String joinLabels(List<Missing> list, int max)
	{
		StringBuilder sb = new StringBuilder();
		int n = 0;
		for (Missing m : list)
		{
			if (n++ == max)
			{
				sb.append(", +").append(list.size() - max);
				break;
			}
			if (sb.length() > 0)
			{
				sb.append(", ");
			}
			sb.append(m.getLabel());
		}
		return sb.toString();
	}

	public static String pretty(String s)
	{
		if (s == null || s.isEmpty())
		{
			return "";
		}
		return Character.toUpperCase(s.charAt(0)) + s.substring(1);
	}
}

package com.slayersuite.alerts;

import lombok.Getter;

/** The priority table. Higher priority wins the banner; sticky alerts stay while their condition holds. */
@Getter
public enum AlertKind
{
	LOW_HP(100, Severity.CRITICAL, true, 0),
	HP_TREND(98, Severity.CRITICAL, false, 6_000),
	VENOM(95, Severity.CRITICAL, true, 0),
	POISON(90, Severity.WARNING, true, 0),
	SUPERIOR_UP(85, Severity.WARNING, true, 0),
	LOW_PRAYER(80, Severity.WARNING, true, 0),
	OFF_TASK(75, Severity.WARNING, false, 8_000),
	MISSING_ITEMS(70, Severity.WARNING, true, 0),
	LEFT_BANK(68, Severity.WARNING, false, 20_000),
	STREAK_RESET(66, Severity.WARNING, false, 15_000),
	BOOST_DROPPED(60, Severity.WARNING, false, 20_000),
	SUPPLIES_LOW(58, Severity.WARNING, false, 25_000),
	FLOOR_LOOT(57, Severity.WARNING, false, 20_000),
	CANNON(55, Severity.WARNING, false, 20_000),
	SUPERIOR(50, Severity.INFO, false, 12_000),
	AGGRESSION(45, Severity.WARNING, false, 12_000),
	OUT_OF_COMBAT(40, Severity.WARNING, true, 0),
	NEARLY_DONE(30, Severity.INFO, false, 15_000),
	TASK_DONE(20, Severity.INFO, false, 20_000);

	private final int priority;
	private final Severity severity;
	private final boolean sticky;
	private final long ttlMs;

	AlertKind(int priority, Severity severity, boolean sticky, long ttlMs)
	{
		this.priority = priority;
		this.severity = severity;
		this.sticky = sticky;
		this.ttlMs = ttlMs;
	}
}

package com.slayersuite.alerts;

public enum Severity
{
	INFO,
	WARNING,
	CRITICAL
}

package com.slayersuite.card;

import com.slayersuite.SlayerSuiteConfig;
import com.slayersuite.data.ItemGroups;
import com.slayersuite.data.ItemRule;
import com.slayersuite.data.MonsterRecord;
import com.slayersuite.data.SlayerDataset;
import com.slayersuite.data.TaskRecord;
import com.slayersuite.guard.AttackGuard;
import com.slayersuite.readiness.ReadinessChecker;
import com.slayersuite.task.TaskTracker;
import java.awt.Color;
import com.slayersuite.ui.Palette;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.Point;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Hover a task monster: a solid card beside the cursor, drawn above everything else, with the
 * name and level, HP / max hit / attack style tiles, then weakness, Slayer xp, the finishing
 * item and any poison or cannon warning.
 */
public class NpcHoverOverlay extends Overlay
{
	private static final Color BG = new Color(18, 18, 18, 238);
	private static final Color BORDER = new Color(255, 255, 255, 45);
	private static final Color TILE = new Color(255, 255, 255, 16);
	private static final Color RULE = new Color(255, 255, 255, 30);
	private static final Color DIM = Palette.DIM;
	private static final Color OK = Palette.OK;
	private static final Color WARN = Palette.WARN;
	private static final Color BAD = Palette.BAD;
	private static final Color INFO = Palette.INFO;
	private static final Color GOLD = Palette.GOLD;
	private static final int PAD = 7;
	private static final int WIDTH = 236;

	private final Client client;
	private final TaskTracker tracker;
	private final AttackGuard guard;
	private final SlayerDataset dataset;
	private final ReadinessChecker readiness;
	private final SlayerSuiteConfig config;
	private final com.slayersuite.task.SlayerMode mode;

	private final Font std = FontManager.getRunescapeFont();
	private final Font small = FontManager.getRunescapeSmallFont();
	private final Font bold = FontManager.getRunescapeBoldFont();

	@Inject
	public NpcHoverOverlay(Client client, TaskTracker tracker, AttackGuard guard, SlayerDataset dataset, ReadinessChecker readiness, SlayerSuiteConfig config, com.slayersuite.task.SlayerMode mode)
	{
		this.mode = mode;
		this.client = client;
		this.tracker = tracker;
		this.guard = guard;
		this.dataset = dataset;
		this.readiness = readiness;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_HIGHEST);
	}

	/** Everything the card says about one monster, gathered once per frame. */
	private static final class Info
	{
		String name;
		int level;
		String tag;
		Color tagColor;
		List<String[]> tiles = new ArrayList<>();
		String maxHitNote;
		List<String[]> rows = new ArrayList<>();
		List<Object[]> warnings = new ArrayList<>();
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.hoverInfo() || !tracker.hasTask() || client.isMenuOpen() || !mode.active())
		{
			return null;
		}
		NPC npc = hovered();
		if (npc == null)
		{
			return null;
		}
		TaskRecord rec = tracker.getRecord();
		boolean target = guard.isTaskTarget(npc);
		NPCComposition comp = npc.getTransformedComposition();
		String name = comp == null ? npc.getName() : comp.getName();
		if (name == null)
		{
			return null;
		}
		MonsterRecord m = rec == null ? null : rec.monsterNamed(name);
		if (!target && m == null)
		{
			return null;
		}
		Point mouse = client.getMouseCanvasPosition();
		if (mouse == null || mouse.getX() < 0 || mouse.getY() < 0)
		{
			return null;
		}
		Info info = gather(rec, m, name, comp, target);
		int h = layout(g, false, info);
		// below and right of the cursor, under the one-line hover text the game or the Mouse Tooltips
		// plugin draws there; never over the game's own top-left action text either
		int x = mouse.getX() + 14;
		int y = mouse.getY() + 42;
		if (x + WIDTH > client.getCanvasWidth() - 4)
		{
			x = Math.max(0, mouse.getX() - WIDTH - 10);
		}
		if (y + h > client.getCanvasHeight() - 4)
		{
			y = Math.max(0, mouse.getY() - h - 12);
		}
		if (y < 30 && x < 520)
		{
			y = 30;
		}
		g.translate(x, y);
		g.setColor(BG);
		g.fillRect(0, 0, WIDTH, h);
		g.setColor(BORDER);
		g.drawRect(0, 0, WIDTH - 1, h - 1);
		layout(g, true, info);
		g.translate(-x, -y);
		return null;
	}

	private Info gather(TaskRecord rec, MonsterRecord m, String name, NPCComposition comp, boolean target)
	{
		Info i = new Info();
		i.name = name;
		i.level = comp != null ? comp.getCombatLevel() : (m != null && m.getCombat() != null ? m.getCombat() : 0);
		if (!target)
		{
			i.tag = "NOT YOUR TASK";
			i.tagColor = BAD;
		}
		else if (m != null && m.isSuperior())
		{
			i.tag = "SUPERIOR";
			i.tagColor = GOLD;
		}
		else
		{
			i.tag = "YOUR TASK";
			i.tagColor = OK;
		}
		if (m != null)
		{
			if (m.getHitpoints() != null)
			{
				i.tiles.add(new String[]{m.getHitpoints() + (m.getHitpointsMax() != null ? "-" + m.getHitpointsMax() : ""), "HP"});
			}
			if (m.getMaxHit() != null && !m.getMaxHit().isEmpty())
			{
				String mh = m.getMaxHit();
				int paren = mh.indexOf(" (");
				if (paren > 0 && mh.endsWith(")"))
				{
					i.maxHitNote = "Max hit " + mh.substring(paren + 2, mh.length() - 1);
					mh = mh.substring(0, paren);
				}
				i.tiles.add(new String[]{mh, "MAX HIT"});
			}
			if (!m.getAttackStyles().isEmpty())
			{
				List<String> st = new ArrayList<>();
				for (String s : m.getAttackStyles())
				{
					st.add(cap(s));
				}
				i.tiles.add(new String[]{String.join("/", st), st.size() > 1 ? "ATTACKS" : "ATTACK"});
			}
		}
		if (m != null)
		{
			if (m.getElementalWeakness() != null && !m.getElementalWeakness().isEmpty())
			{
				i.rows.add(new String[]{"Weak to", cap(m.getElementalWeakness()) + " spells", "info"});
			}
			if (m.getSlayerXp() != null)
			{
				i.rows.add(new String[]{"Slayer xp", fmt(m.getSlayerXp()) + (m.getSlayerXpMax() != null && !m.getSlayerXpMax().equals(m.getSlayerXp()) ? "-" + fmt(m.getSlayerXpMax()) : ""), ""});
			}
		}
		if (rec != null)
		{
			ItemRule fin = rec.getFinishingItem();
			if (fin != null && fin.getAnyOf() != null)
			{
				ItemGroups items = dataset.getItems();
				boolean have = items.anySatisfied(fin.getAnyOf(), readiness.heldNames());
				i.rows.add(new String[]{"Finish", items.describe(fin.getAnyOf()) + (fin.getThreshold() != null ? " at " + fin.getThreshold() + " HP" : "") + (have ? "" : ", not carried"), have ? "ok" : "bad"});
			}
		}
		if (m != null)
		{
			if (m.isVenomous())
			{
				i.warnings.add(new Object[]{BAD, "Venomous", readiness.hasGroup("antivenom") ? "anti-venom carried" : "no anti-venom"});
			}
			else if (m.isPoisonous())
			{
				i.warnings.add(new Object[]{BAD, "Poisons", readiness.hasGroup("antipoison") ? "antipoison carried" : "no antipoison"});
			}
			if (m.isCannonImmune())
			{
				i.warnings.add(new Object[]{WARN, "Immune to cannon", ""});
			}
		}
		return i;
	}

	private int layout(Graphics2D g, boolean draw, Info i)
	{
		int x0 = PAD;
		int cw = WIDTH - 2 * PAD;
		int y = PAD;
		FontMetrics fb = g.getFontMetrics(bold);
		FontMetrics fn = g.getFontMetrics(std);
		FontMetrics fs = g.getFontMetrics(small);

		// name and level
		String lvl = i.level > 0 ? "lvl " + i.level : "";
		int lw = fs.stringWidth(lvl);
		text(g, draw, bold, fit(fb, i.name, cw - lw - 8), x0, y + fb.getAscent(), Color.WHITE);
		if (!lvl.isEmpty())
		{
			text(g, draw, small, lvl, x0 + cw - lw, y + fb.getAscent(), DIM);
		}
		y += fb.getHeight();
		// tag chip
		int tw = fs.stringWidth(i.tag) + 8;
		int th = fs.getHeight() + 1;
		if (draw)
		{
			g.setColor(new Color(i.tagColor.getRed(), i.tagColor.getGreen(), i.tagColor.getBlue(), 40));
			g.fillRect(x0, y, tw, th);
			g.setColor(new Color(i.tagColor.getRed(), i.tagColor.getGreen(), i.tagColor.getBlue(), 150));
			g.drawRect(x0, y, tw - 1, th - 1);
		}
		text(g, draw, small, i.tag, x0 + 4, y + fs.getAscent(), i.tagColor);
		y += th + 6;

		// tiles
		if (!i.tiles.isEmpty())
		{
			int n = i.tiles.size();
			int colW = (cw - 2 * (n - 1)) / n;
			int h = fb.getHeight() + fs.getHeight();
			for (int k = 0; k < n; k++)
			{
				int x = x0 + k * (colW + 2);
				if (draw)
				{
					g.setColor(TILE);
					g.fillRect(x, y, colW, h);
				}
				String v = fit(fb, i.tiles.get(k)[0], colW - 4);
				String l = fit(fs, i.tiles.get(k)[1], colW - 4);
				text(g, draw, bold, v, x + (colW - fb.stringWidth(v)) / 2, y + 1 + fb.getAscent(), Color.WHITE);
				text(g, draw, small, l, x + (colW - fs.stringWidth(l)) / 2, y + fb.getHeight() + fs.getAscent() - 2, DIM);
			}
			y += h + 3;
			if (i.maxHitNote != null)
			{
				text(g, draw, small, fit(fs, i.maxHitNote, cw), x0, y + fs.getAscent(), DIM);
				y += fs.getHeight() + 1;
			}
		}

		// rows
		if (!i.rows.isEmpty())
		{
			y = rule(g, draw, x0, y, cw);
			int labelW = 0;
			for (String[] r : i.rows)
			{
				labelW = Math.max(labelW, fs.stringWidth(r[0]));
			}
			labelW += 8;
			for (String[] r : i.rows)
			{
				Color c = "info".equals(r[2]) ? INFO : "ok".equals(r[2]) ? OK : "bad".equals(r[2]) ? BAD : Color.WHITE;
				text(g, draw, small, r[0], x0, y + fn.getAscent(), DIM);
				text(g, draw, std, fit(fn, r[1], cw - labelW), x0 + labelW, y + fn.getAscent(), c);
				y += fn.getHeight();
			}
			y += 1;
		}

		// warnings
		if (!i.warnings.isEmpty())
		{
			y = rule(g, draw, x0, y, cw);
			for (Object[] wn : i.warnings)
			{
				Color c = (Color) wn[0];
				String right = (String) wn[2];
				int rw = right.isEmpty() ? 0 : fs.stringWidth(right);
				if (draw)
				{
					g.setColor(c);
					g.fillOval(x0, y + (fn.getHeight() - 7) / 2, 7, 7);
				}
				text(g, draw, std, fit(fn, (String) wn[1], cw - 12 - rw - 6), x0 + 12, y + fn.getAscent(), c);
				if (rw > 0)
				{
					text(g, draw, small, right, x0 + cw - rw, y + fn.getAscent(), right.startsWith("no ") ? c : DIM);
				}
				y += fn.getHeight();
			}
			y += 1;
		}
		return y + PAD - 2;
	}

	private NPC hovered()
	{
		MenuEntry[] entries = client.getMenu().getMenuEntries();
		if (entries == null)
		{
			return null;
		}
		for (int i = entries.length - 1; i >= 0; i--)
		{
			NPC npc = entries[i].getNpc();
			if (npc != null)
			{
				return npc;
			}
		}
		return null;
	}

	private int rule(Graphics2D g, boolean draw, int x0, int y, int cw)
	{
		if (draw)
		{
			g.setColor(RULE);
			g.fillRect(x0, y + 1, cw, 1);
		}
		return y + 5;
	}

	private static void text(Graphics2D g, boolean draw, Font f, String s, int x, int y, Color c)
	{
		if (!draw || s == null || s.isEmpty())
		{
			return;
		}
		g.setFont(f);
		g.setColor(Color.BLACK);
		g.drawString(s, x + 1, y + 1);
		g.setColor(c);
		g.drawString(s, x, y);
	}

	private static String fit(FontMetrics fm, String s, int max)
	{
		if (s == null)
		{
			return "";
		}
		if (fm.stringWidth(s) <= max)
		{
			return s;
		}
		String t = s;
		while (t.length() > 1 && fm.stringWidth(t + "..") > max)
		{
			t = t.substring(0, t.length() - 1);
		}
		return t.trim() + "..";
	}

	private static String fmt(double d)
	{
		return d == Math.rint(d) ? Long.toString((long) d) : String.valueOf(d);
	}

	private static String cap(String s)
	{
		return s.isEmpty() ? s : Character.toUpperCase(s.charAt(0)) + s.substring(1);
	}
}

package com.slayersuite.card;

import com.slayersuite.SlayerSuiteConfig;
import com.slayersuite.task.TaskTracker;
import com.slayersuite.ui.Palette;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.Stroke;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

/**
 * Makes a superior impossible to miss: its outline and tile pulse red with SUPERIOR over its head
 * until you attack it, then settle to amber; when it is off screen an arrow at the edge of the view
 * points at it with the distance; a dot pulses on the minimap the whole time it stands.
 */
public class SuperiorOverlay extends Overlay
{
	private static final Color OUTLINE = new Color(0, 0, 0, 180);

	private final Client client;
	private final TaskTracker tracker;
	private final SlayerSuiteConfig config;
	private final ModelOutlineRenderer outlines;

	@Inject
	public SuperiorOverlay(Client client, TaskTracker tracker, SlayerSuiteConfig config, ModelOutlineRenderer outlines)
	{
		this.client = client;
		this.tracker = tracker;
		this.config = config;
		this.outlines = outlines;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_HIGH);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.superiorHighlight())
		{
			return null;
		}
		NPC s = tracker.getSuperior();
		Player me = client.getLocalPlayer();
		if (s == null || me == null)
		{
			return null;
		}
		long now = System.currentTimeMillis();
		boolean engaged = tracker.isSuperiorEngaged();
		float pulse = engaged ? 1f : 0.6f + 0.4f * (float) Math.abs(Math.sin(now / 160.0));
		Color base = engaged ? Palette.SUPERIOR_CALM : Palette.SUPERIOR;
		Color c = new Color(base.getRed(), base.getGreen(), base.getBlue(), Math.round(255 * pulse));
		Color fill = new Color(base.getRed(), base.getGreen(), base.getBlue(), Math.round(40 * pulse));
		String name = tracker.getSuperiorName() == null ? "Superior" : tracker.getSuperiorName();
		WorldPoint mine = me.getWorldLocation();
		WorldPoint theirs = s.getWorldLocation();
		int tiles = mine != null && theirs != null && mine.getPlane() == theirs.getPlane() ? mine.distanceTo(theirs) : -1;

		Object aa = g.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		Rectangle view = new Rectangle(client.getViewportXOffset(), client.getViewportYOffset(), client.getViewportWidth(), client.getViewportHeight());
		Shape oldClip = g.getClip();
		Stroke oldStroke = g.getStroke();
		g.setClip(view);

		LocalPoint lp = s.getLocalLocation();
		NPCComposition comp = s.getTransformedComposition();
		int size = comp == null ? 1 : Math.max(1, comp.getSize());
		Polygon tile = lp == null ? null : Perspective.getCanvasTileAreaPoly(client, lp, size);
		if (tile != null)
		{
			g.setColor(fill);
			g.fill(tile);
			g.setColor(c);
			g.setStroke(new BasicStroke(2f));
			g.draw(tile);
		}
		// the creature's own silhouette, feathered into a glow, rather than a hull boxing its wings
		outlines.drawOutline(s, engaged ? 2 : 3, c, engaged ? 2 : 6);
		int plane = theirs == null ? 0 : theirs.getPlane();
		// well above the head, clear of the name tags other plugins draw there
		Point above = lp == null ? null : Perspective.localToCanvas(client, lp, plane, s.getLogicalHeight() + 110);
		boolean onScreen = above != null && view.contains(above.getX(), above.getY());
		if (onScreen)
		{
			Font big = FontManager.getRunescapeBoldFont().deriveFont(engaged ? 16f : 18f + 2f * pulse);
			g.setFont(big);
			FontMetrics fb = g.getFontMetrics();
			String head = "SUPERIOR";
			shadowed(g, head, above.getX() - fb.stringWidth(head) / 2, above.getY() - fb.getHeight(), c);
			g.setFont(FontManager.getRunescapeBoldFont());
			FontMetrics fm = g.getFontMetrics();
			String line = engaged ? name : name + "  -  attack it";
			shadowed(g, line, above.getX() - fm.stringWidth(line) / 2, above.getY(), Color.WHITE);
		}
		g.setClip(oldClip);

		if (!onScreen)
		{
			edgeArrow(g, view, me, s, lp, c, name, tiles);
		}
		// the minimap: a dot that pulses while it stands
		Point mm = lp == null ? null : Perspective.localToMinimap(client, lp);
		if (mm != null)
		{
			int r = engaged ? 4 : 4 + Math.round(3 * pulse);
			g.setColor(c);
			g.fillOval(mm.getX() - r, mm.getY() - r, 2 * r, 2 * r);
			g.setColor(OUTLINE);
			g.setStroke(new BasicStroke(1.5f));
			g.drawOval(mm.getX() - r, mm.getY() - r, 2 * r, 2 * r);
		}
		g.setStroke(oldStroke);
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, aa == null ? RenderingHints.VALUE_ANTIALIAS_DEFAULT : aa);
		return null;
	}

	/** An arrow just inside the edge of the view, pointing where the superior is, with its name and distance. */
	private void edgeArrow(Graphics2D g, Rectangle view, Player me, NPC s, LocalPoint lp, Color c, String name, int tiles)
	{
		double ang;
		WorldPoint w = s.getWorldLocation();
		Point on = lp == null ? null : Perspective.localToCanvas(client, lp, w == null ? 0 : w.getPlane(), 0);
		int cx = view.x + view.width / 2;
		int cy = view.y + view.height / 2;
		if (on != null)
		{
			ang = Math.atan2(on.getY() - cy, on.getX() - cx);
		}
		else
		{
			// behind the camera: the minimap turns with the camera, so its direction is the screen's
			LocalPoint here = me.getLocalLocation();
			Point a = here == null ? null : Perspective.localToMinimap(client, here, 2000);
			Point b = lp == null ? null : Perspective.localToMinimap(client, lp, 2000);
			if (a == null || b == null)
			{
				return;
			}
			ang = Math.atan2(b.getY() - a.getY(), b.getX() - a.getX());
		}
		int inset = 46;
		double hx = (view.width / 2.0 - inset) / Math.max(1e-6, Math.abs(Math.cos(ang)));
		double hy = (view.height / 2.0 - inset) / Math.max(1e-6, Math.abs(Math.sin(ang)));
		double reach = Math.min(hx, hy);
		int tx = (int) Math.round(cx + Math.cos(ang) * reach);
		int ty = (int) Math.round(cy + Math.sin(ang) * reach);
		int sz = 16;
		Polygon tri = new Polygon();
		tri.addPoint((int) Math.round(tx + Math.cos(ang) * sz), (int) Math.round(ty + Math.sin(ang) * sz));
		tri.addPoint((int) Math.round(tx + Math.cos(ang + 2.5) * sz), (int) Math.round(ty + Math.sin(ang + 2.5) * sz));
		tri.addPoint((int) Math.round(tx + Math.cos(ang - 2.5) * sz), (int) Math.round(ty + Math.sin(ang - 2.5) * sz));
		g.setColor(c);
		g.fillPolygon(tri);
		g.setColor(OUTLINE);
		g.setStroke(new BasicStroke(2f));
		g.drawPolygon(tri);
		g.setFont(FontManager.getRunescapeBoldFont());
		FontMetrics fm = g.getFontMetrics();
		String label = "SUPERIOR  " + name + (tiles > 0 ? "  " + tiles + " tiles" : "");
		int lx = tx - fm.stringWidth(label) / 2;
		int ly = ty - sz - 6;
		lx = Math.max(view.x + 4, Math.min(view.x + view.width - fm.stringWidth(label) - 4, lx));
		if (ly < view.y + fm.getAscent() + 2)
		{
			ly = ty + sz + fm.getAscent() + 6;
		}
		shadowed(g, label, lx, ly, c);
	}

	private static void shadowed(Graphics2D g, String s, int x, int y, Color c)
	{
		g.setColor(Color.BLACK);
		g.drawString(s, x + 1, y + 1);
		g.setColor(c);
		g.drawString(s, x, y);
	}
}

package com.slayersuite.card;

import com.slayersuite.SlayerSuiteConfig;
import com.slayersuite.advisor.Advisor;
import com.slayersuite.alerts.AlertEngine;
import com.slayersuite.data.ItemGroups;
import com.slayersuite.data.ItemRule;
import com.slayersuite.data.LocationRecord;
import com.slayersuite.data.SlayerDataset;
import com.slayersuite.data.TaskRecord;
import com.slayersuite.history.TaskHistory;
import com.slayersuite.history.TaskStats;
import com.slayersuite.readiness.Missing;
import com.slayersuite.readiness.ReadinessChecker;
import com.slayersuite.task.GameTaskTable;
import com.slayersuite.task.TaskTracker;
import com.slayersuite.trip.TripMath;
import com.slayersuite.trip.TripTracker;
import java.awt.Color;
import com.slayersuite.ui.Palette;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.time.LocalTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.BackgroundComponent;

/**
 * The one task card, drawn as four short blocks: the header (icon, name, kills left, bar),
 * the numbers (ETA, rate, points, streak as tiles), how to fight it (style, superior,
 * finishing item), where you are or where to go, and a gear checklist.
 */
public class TaskCardOverlay extends Overlay
{
	private static final Color OK = Palette.OK;
	private static final Color MISSING = Palette.BAD;
	private static final Color RECOMMENDED = Palette.WARN;
	private static final Color DIM = Palette.DIM;
	private static final Color CYAN = new Color(80, 220, 255);
	private static final Color BAR = new Color(90, 160, 90);
	private static final Color BAR_BG = new Color(60, 60, 60);
	private static final Color TILE = Palette.TILE;
	private static final Color RULE = Palette.RULE;
	private static final Color ACCENT = ColorScheme.BRAND_ORANGE;
	private static final int PAD = 6;
	private static final int DEFAULT_WIDTH = 260;

	private final TaskTracker tracker;
	private final ReadinessChecker readiness;
	private final AlertEngine alerts;
	private final SlayerDataset dataset;
	private final SlayerSuiteConfig config;
	private final TaskHistory history;
	private final TripTracker trip;
	private final Advisor advisor;
	private final com.slayersuite.task.SlayerMode mode;
	private final javax.inject.Provider<com.slayersuite.advisor.PathOverlay> pathOverlay;
	private final net.runelite.client.eventbus.EventBus eventBus;
	private final ItemManager itemManager;
	private BufferedImage itemIcon;
	private int itemIconFor = -1;

	private final Font std = FontManager.getRunescapeFont();
	private final Font small = FontManager.getRunescapeSmallFont();
	private final Font bold = FontManager.getRunescapeBoldFont();

	@Inject
	public TaskCardOverlay(TaskTracker tracker, ReadinessChecker readiness, AlertEngine alerts, SlayerDataset dataset, SlayerSuiteConfig config, TaskHistory history, TripTracker trip, Advisor advisor, com.slayersuite.task.SlayerMode mode, javax.inject.Provider<com.slayersuite.advisor.PathOverlay> pathOverlay, net.runelite.client.eventbus.EventBus eventBus, ItemManager itemManager)
	{
		this.eventBus = eventBus;
		this.pathOverlay = pathOverlay;
		this.mode = mode;
		this.advisor = advisor;
		this.tracker = tracker;
		this.readiness = readiness;
		this.alerts = alerts;
		this.dataset = dataset;
		this.config = config;
		this.history = history;
		this.trip = trip;
		this.itemManager = itemManager;
		setPosition(OverlayPosition.TOP_LEFT);
		setPriority(PRIORITY_MED);
		setResizable(true);
		setPreferredSize(new Dimension(DEFAULT_WIDTH, 0));
		// Alt + right-click the card to try the displays without finishing a task.
		addMenuEntry(net.runelite.api.MenuAction.RUNELITE_OVERLAY, "Test", "task complete card and sound", e ->
			eventBus.post(new com.slayersuite.task.TaskFinished(tracker.hasTask() ? tracker.getTaskName() : "Test task", 20, 12, true)));
		addMenuEntry(net.runelite.api.MenuAction.RUNELITE_OVERLAY, "Test", "superior card and sound", e ->
			tracker.testSuperior());
		addMenuEntry(net.runelite.api.MenuAction.RUNELITE_OVERLAY, "Test", "critical alert", e -> alerts.testAlert());
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.showCard())
		{
			return null;
		}
		if (!mode.active() && !config.cardWhenDormant() && !readiness.isBankOpen())
		{
			return null;
		}
		if (!tracker.hasTask() && !config.cardWithoutTask() && !advisor.loopActive())
		{
			return null;
		}
		Dimension pref = getPreferredSize();
		int w = pref != null && pref.width >= 180 ? pref.width : DEFAULT_WIDTH;
		int h = layout(g, false, w);
		BackgroundComponent bg = new BackgroundComponent();
		bg.setRectangle(new Rectangle(0, 0, w, h));
		bg.render(g);
		// a hairline in the chevron colour, so the card and the route read as one thing
		Color accent = config.chevronColour().resolve(config.customChevronColour());
		g.setColor(new Color(accent.getRed(), accent.getGreen(), accent.getBlue(), 200));
		g.fillRect(1, 1, w - 2, 2);
		layout(g, true, w);
		return new Dimension(w, h);
	}

	/** Lays the card out top to bottom; with draw=false it only measures. Returns the height. */
	private int layout(Graphics2D g, boolean draw, int w)
	{
		int x0 = PAD;
		int cw = w - 2 * PAD;
		int y = PAD;
		FontMetrics fb = g.getFontMetrics(bold);
		FontMetrics fs = g.getFontMetrics(small);
		FontMetrics fn = g.getFontMetrics(std);

		if (!tracker.hasTask())
		{
			if (advisor.loopActive())
			{
				return loopCard(g, draw, x0, y, cw, fb, fn, fs);
			}
			String t = "No slayer task";
			text(g, draw, small, t, x0 + (cw - fs.stringWidth(t)) / 2, y + fs.getAscent(), DIM);
			return y + fs.getHeight() + PAD;
		}

		TaskRecord rec = tracker.getRecord();
		boolean compact = config.compactCard();
		int remaining = tracker.getRemaining();
		int initial = Math.max(tracker.getInitial(), remaining);

		// ---- header: icon, name, kills left, bar
		BufferedImage icon = itemIcon(rec);
		int iconW = icon == null ? 0 : 22;
		int iconH = 20;
		String left = remaining + " left";
		String of = initial > 0 ? "  of " + initial : "";
		int rightW = fb.stringWidth(left) + fs.stringWidth(of);
		String title = rec != null ? rec.title() : AlertEngine.pretty(tracker.getTaskName());
		if (tracker.isFromChat())
		{
			title += " *";
		}
		title = fit(fb, title, cw - iconW - (iconW > 0 ? 4 : 0) - rightW - 8);
		int lineH = Math.max(fb.getHeight(), iconH);
		int base = y + (lineH + fb.getAscent() - fb.getDescent()) / 2;
		if (icon != null && draw)
		{
			g.drawImage(icon, x0, y + (lineH - iconH) / 2, iconW, iconH, null);
		}
		text(g, draw, bold, title, x0 + iconW + (iconW > 0 ? 4 : 0), base, Color.WHITE);
		int rx = x0 + cw - rightW;
		text(g, draw, bold, left, rx, base, Color.WHITE);
		text(g, draw, small, of, rx + fb.stringWidth(left), base, DIM);
		y += lineH + 4;
		if (draw)
		{
			g.setColor(BAR_BG);
			g.fillRect(x0, y, cw, 5);
			g.setColor(BAR);
			g.fillRect(x0, y, initial > 0 ? (int) Math.round(cw * (initial - remaining) / (double) initial) : 0, 5);
		}
		y += 5 + 6;

		// ---- the numbers, as tiles
		List<String[]> tiles = new ArrayList<>();
		if (config.cardShowEta())
		{
			long eta = tracker.etaMillis();
			double kph = tracker.effectiveKph();
			String done = eta < 0 ? "" : "  " + LocalTime.now().plusSeconds(eta / 1000).format(DateTimeFormatter.ofPattern("HH:mm"));
			tiles.add(new String[]{eta < 0 ? "--" : TaskTracker.formatDuration(eta), "ETA" + done});
			tiles.add(new String[]{kph > 0 ? Long.toString(Math.round(kph)) : "--", tracker.isEtaFromHistory() ? "KILLS/H  HIST" : "KILLS/H"});
		}
		if (tracker.getSlayerPoints() > 0)
		{
			tiles.add(new String[]{String.format("%,d", tracker.getSlayerPoints()), "POINTS"});
			tiles.add(new String[]{Integer.toString(tracker.getTaskStreak()), "STREAK"});
		}
		if (!tiles.isEmpty())
		{
			y += tiles(g, draw, x0, y, cw, tiles, fb, fs);
			y += 4;
		}
		if (compact)
		{
			y = checklist(g, draw, x0, y, cw, rec, true, fn, fs);
			return y + PAD - 2;
		}

		// ---- how to fight it
		List<Cell> fight = new ArrayList<>();
		if (rec != null)
		{
			if (config.cardShowPrayer() && rec.getStyle() != null)
			{
				fight.add(new Cell("STYLE", rec.getStyle(), Color.WHITE, null));
			}
			ItemRule fin = rec.getFinishingItem();
			if (fin != null && fin.getAnyOf() != null)
			{
				boolean have = dataset.getItems().anySatisfied(fin.getAnyOf(), readiness.heldNames());
				fight.add(new Cell("FINISH" + (fin.getThreshold() != null ? "  AT " + fin.getThreshold() + " HP" : ""), dataset.getItems().describe(fin.getAnyOf()), have ? OK : MISSING, null));
			}
			if (!rec.getSuperiors().isEmpty())
			{
				fight.add(new Cell("SUPERIOR", rec.getSuperiors().get(0), Color.WHITE, null));
			}
		}
		if (!fight.isEmpty())
		{
			y = rule(g, draw, x0, y, cw);
			y += cells(g, draw, x0, y, cw, fight, fn, fs);
			y += 2;
		}

		// ---- the drops you are waiting on
		if (config.cardShowOdds())
		{
			List<TaskHistory.DryOdds> odds = history.dryOdds(2, 1.0 / 64);
			if (!odds.isEmpty())
			{
				y = rule(g, draw, x0, y, cw);
				y = oddsRows(g, draw, x0, y, cw, odds, fn, fs);
				y += 2;
			}
		}

		// ---- where you are, or where to go
		if (config.cardShowLocation())
		{
			// measure first so an empty block draws no rule
			int probe = rule(g, false, x0, y, cw);
			if (place(g, false, x0, probe, cw, rec, fn, fs) > probe)
			{
				y = rule(g, draw, x0, y, cw);
				y = place(g, draw, x0, y, cw, rec, fn, fs);
			}
		}

		// ---- gear checklist
		y = checklist(g, draw, x0, y, cw, rec, false, fn, fs);

		// ---- small print
		List<String[]> foot = new ArrayList<>();
		if (config.cardShowSupplies())
		{
			if (history.getAssignmentXp() > 0 || history.getAssignmentGp() > 0)
			{
				foot.add(new String[]{"This task  " + TripMath.formatK(history.getAssignmentXp()) + " xp,  " + TripMath.formatK(history.getAssignmentGp()) + " gp"
					+ (history.getAssignmentMs() > 60_000L ? ",  " + TaskTracker.formatDuration(history.getAssignmentMs()) : ""), null});
			}
			TaskStats stats = history.getCurrent();
			if (stats != null && stats.hasRate() && history.getSessionKills() < 3)
			{
				foot.add(new String[]{"Your usual  " + TripMath.formatK(Math.round(stats.xpPerHour())) + " xp/h,  " + TripMath.formatK(Math.round(stats.gpPerHour())) + " gp/h", null});
			}
			if (history.getAdvice() != null)
			{
				foot.add(new String[]{history.getAdvice(), history.getAdvice().startsWith("Low") ? "warn" : "ok"});
			}
			if (config.floorLoot() && history.getFloorValue() > 0)
			{
				long floorLeft = history.getFloorSoonestAt() - System.currentTimeMillis();
				foot.add(new String[]{"On the floor  " + TripMath.formatK(history.getFloorValue()) + " gp" + (floorLeft > 0 ? ",  " + com.slayersuite.history.FloorLootMath.countdown(floorLeft) + " left" : ""),
					floorLeft > 0 && floorLeft <= com.slayersuite.history.FloorLootMath.URGENT_MS ? "warn" : null});
			}
		}
		GameTaskTable.GameTask gt = tracker.getGameTask();
		if (gt != null && tracker.rollChance() > 0)
		{
			foot.add(new String[]{GameTaskTable.masterName(gt.getMasterId()) + " rolls this " + Math.round(tracker.rollChance() * 100) + "% of the time", null});
		}
		if (rec == null)
		{
			foot.add(new String[]{"No dataset entry yet", null});
		}
		if (alerts.isPaused())
		{
			foot.add(new String[]{"Alerts paused", "warn"});
		}
		if (!foot.isEmpty())
		{
			y = rule(g, draw, x0, y, cw);
			for (String[] f : foot)
			{
				Color c = "warn".equals(f[1]) ? RECOMMENDED : "ok".equals(f[1]) ? OK : DIM;
				text(g, draw, small, fit(fs, f[0], cw), x0, y + fs.getAscent(), c);
				y += fs.getHeight();
			}
		}
		return y + PAD - 2;
	}

	// ---------------------------------------------------------------- blocks

	/** Between tasks: where the loop guide is taking you, the next move and the distance. */
	private int loopCard(Graphics2D g, boolean draw, int x0, int y, int cw, FontMetrics fb, FontMetrics fn, FontMetrics fs)
	{
		text(g, draw, small, "BETWEEN TASKS", x0, y + fs.getAscent(), DIM);
		y += fs.getHeight() + 2;
		for (String line : wrap(fb, advisor.loopText(), cw))
		{
			text(g, draw, bold, line, x0, y + fb.getAscent(), Color.WHITE);
			y += fb.getHeight();
		}
		if (advisor.isArrived())
		{
			text(g, draw, std, "You are there", x0, y + fn.getAscent(), OK);
			y += fn.getHeight();
		}
		else
		{
			String step = advisor.getNextStep();
			if (step != null && !step.isEmpty())
			{
				y += 2;
				for (String line : wrap(fs, step, cw))
				{
					text(g, draw, small, line, x0, y + fs.getAscent(), DIM);
					y += fs.getHeight();
				}
			}
			int dist = advisor.cachedDistance();
			if (dist >= 0)
			{
				text(g, draw, small, TripMath.formatK(dist) + " tiles " + advisor.cachedDirection(), x0, y + fs.getAscent(), DIM);
				y += fs.getHeight();
			}
		}
		return y + PAD - 2;
	}

	private int place(Graphics2D g, boolean draw, int x0, int y, int cw, TaskRecord rec, FontMetrics fn, FontMetrics fs)
	{
		LocationRecord loc = tracker.getCurrentLocation();
		LocationRecord dest = advisor.getDestination();
		boolean guiding = dest != null && !advisor.isArrived();
		if (guiding)
		{
			// a spot is pinned and you are not at its spawns yet: the route comes first, wherever you stand
			int dist = advisor.cachedDistance();
			y += dotRow(g, draw, x0, y, cw, CYAN, dest.getName(), Color.WHITE, dist >= 0 ? TripMath.formatK(dist) + " " + advisor.cachedDirection() : "", DIM, fn, fs);
			String step = advisor.getNextStep();
			if (step != null && !step.isEmpty())
			{
				y += callout(g, draw, x0 + 12, y, cw - 12, "NEXT", step, fn, fs);
			}
			String via = pathOverlay.get().entranceLabel();
			if (via != null)
			{
				int tiles = pathOverlay.get().lineTiles();
				text(g, draw, small, fit(fs, via + (tiles > 0 ? ", " + tiles + " tiles, marked on the floor" : ", marked on the floor"), cw - 12), x0 + 12, y + fs.getAscent(), CYAN);
				y += fs.getHeight();
			}
			else if (pathOverlay.get().blocked())
			{
				text(g, draw, small, fit(fs, "The chevrons stop short here: follow the arrow past it", cw - 12), x0 + 12, y + fs.getAscent(), RECOMMENDED);
				y += fs.getHeight();
			}
			if (loc != null && !Advisor.sameLocation(loc, dest))
			{
				text(g, draw, small, fit(fs, "You are at " + loc.getName(), cw - 12), x0 + 12, y + fs.getAscent(), DIM);
				y += fs.getHeight();
			}
			return y + 2;
		}
		if (loc != null)
		{
			List<String> flags = new ArrayList<>();
			if (rec != null && rec.cannonImmune())
			{
				flags.add("cannon immune");
			}
			else if (loc.getCannon() != null)
			{
				flags.add(loc.getCannon() ? "cannon" : "no cannon");
			}
			if (loc.getMulticombat() != null)
			{
				flags.add(loc.getMulticombat() ? "multi" : "single");
			}
			if (Boolean.TRUE.equals(loc.getSafespot()))
			{
				flags.add("safespot");
			}
			y += dotRow(g, draw, x0, y, cw, OK, loc.getName(), Color.WHITE, "you are here", DIM, fn, fs);
			if (!flags.isEmpty())
			{
				y += chips(g, draw, x0 + 12, y, cw - 12, flags, fs);
			}
			return y + 2;
		}
		if (tracker.getTaskLocation() != null && !tracker.getTaskLocation().isEmpty())
		{
			return y + dotRow(g, draw, x0, y, cw, CYAN, "Go to " + tracker.getTaskLocation(), Color.WHITE, "", DIM, fn, fs) + 2;
		}
		if (rec != null && !rec.getLocations().isEmpty())
		{
			return y + dotRow(g, draw, x0, y, cw, DIM, "Not in a task area", DIM, firstLocationNames(rec), DIM, fn, fs) + 2;
		}
		return y;
	}

	private int checklist(Graphics2D g, boolean draw, int x0, int y, int cw, TaskRecord rec, boolean compact, FontMetrics fn, FontMetrics fs)
	{
		List<Object[]> rows = new ArrayList<>();
		if (rec != null && !compact)
		{
			ItemGroups items = dataset.getItems();
			for (ItemRule rule : rec.getRequiredItems())
			{
				if (!rule.isRequired() || rule.getAnyOf() == null)
				{
					continue;
				}
				if (items.anySatisfied(rule.getAnyOf(), readiness.heldNames()))
				{
					String held = items.heldName(rule.getAnyOf(), readiness.heldNames());
					rows.add(new Object[]{OK, held == null ? items.describe(rule.getAnyOf()) : held, "ok"});
				}
			}
		}
		for (Missing m : readiness.getMissing())
		{
			if (!m.isRequired() && compact)
			{
				continue;
			}
			String status = m.isInBank() && readiness.isBankOpen() ? "in bank" : m.isRequired() ? "missing" : "bring";
			rows.add(new Object[]{m.isRequired() ? MISSING : RECOMMENDED, m.getLabel(), status});
		}
		if (rows.isEmpty())
		{
			return y;
		}
		y = rule(g, draw, x0, y, cw);
		int shown = 0;
		for (Object[] r : rows)
		{
			if (shown == 6)
			{
				text(g, draw, small, "+" + (rows.size() - 6) + " more", x0 + 12, y + fs.getAscent(), DIM);
				y += fs.getHeight();
				break;
			}
			Color c = (Color) r[0];
			y += dotRow(g, draw, x0, y, cw, c, (String) r[1], c == OK ? Color.WHITE : c, (String) r[2], c, fn, fs);
			shown++;
		}
		return y + 2;
	}

	// ---------------------------------------------------------------- widgets

	/** One labelled value for the fight row. */
	private static final class Cell
	{
		final String label;
		final String value;
		final Color color;
		final BufferedImage icon;

		Cell(String label, String value, Color color, BufferedImage icon)
		{
			this.label = label;
			this.value = value;
			this.color = color;
			this.icon = icon;
		}
	}

	/** Equal-width tiles: bold value over a small dim label. */
	private int tiles(Graphics2D g, boolean draw, int x0, int y, int cw, List<String[]> cells, FontMetrics fb, FontMetrics fs)
	{
		int n = cells.size();
		int colW = (cw - 2 * (n - 1)) / n;
		int h = fb.getHeight() + fs.getHeight();
		for (int i = 0; i < n; i++)
		{
			int x = x0 + i * (colW + 2);
			if (draw)
			{
				g.setColor(TILE);
				g.fillRect(x, y, colW, h);
			}
			String v = fit(fb, cells.get(i)[0], colW - 4);
			String l = fit(fs, cells.get(i)[1], colW - 4);
			text(g, draw, bold, v, x + (colW - fb.stringWidth(v)) / 2, y + 1 + fb.getAscent(), Color.WHITE);
			text(g, draw, small, l, x + (colW - fs.stringWidth(l)) / 2, y + fb.getHeight() + fs.getAscent() - 2, DIM);
		}
		return h;
	}

	/** Content-sized cells, label over value, flowing left to right and wrapping. */
	private int cells(Graphics2D g, boolean draw, int x0, int y, int cw, List<Cell> cells, FontMetrics fn, FontMetrics fs)
	{
		int gap = 14;
		int rowH = fs.getHeight() + fn.getHeight() - 2;
		int x = x0;
		int rows = 1;
		for (Cell c : cells)
		{
			int iconW = c.icon == null ? 0 : 16;
			int wv = fn.stringWidth(c.value) + iconW;
			int cellW = Math.min(cw, Math.max(wv, fs.stringWidth(c.label)));
			if (x > x0 && x + cellW > x0 + cw)
			{
				x = x0;
				y += rowH + 2;
				rows++;
			}
			text(g, draw, small, c.label, x, y + fs.getAscent(), DIM);
			int vy = y + fs.getHeight() - 2;
			if (c.icon != null && draw)
			{
				g.drawImage(c.icon, x, vy + (fn.getHeight() - 14) / 2, 14, 14, null);
			}
			text(g, draw, std, fit(fn, c.value, cw - iconW), x + iconW, vy + fn.getAscent(), c.color);
			x += cellW + gap;
		}
		return rowH * rows + 2 * (rows - 1);
	}

	/** One line per rare drop: the item and its rate on the left, your kills since the last one and the chance you would have had it by now on the right. */
	private int oddsRows(Graphics2D g, boolean draw, int x0, int y, int cw, List<TaskHistory.DryOdds> odds, FontMetrics fn, FontMetrics fs)
	{
		for (TaskHistory.DryOdds o : odds)
		{
			String pct = Math.round(o.chanceByNow() * 100) + "%";
			String since = o.getSeen() > 0 ? o.getSeen() + " seen,  " + o.getKillsSince() + " since" : o.getKillsSince() + " dry";
			String rate = o.getRarity();
			int pctW = fn.stringWidth(pct);
			int sinceW = fs.stringWidth(since);
			int rateW = fs.stringWidth(rate);
			int nameMax = cw - pctW - 8 - sinceW - 10 - rateW - 6;
			String name = fit(fn, o.getName(), Math.max(40, nameMax));
			int base = y + fn.getAscent();
			text(g, draw, std, name, x0, base, Color.WHITE);
			text(g, draw, small, rate, x0 + fn.stringWidth(name) + 6, base, DIM);
			Color pc = o.chanceByNow() >= 0.9 ? RECOMMENDED : Color.WHITE;
			text(g, draw, std, pct, x0 + cw - pctW, base, pc);
			text(g, draw, small, since, x0 + cw - pctW - 8 - sinceW, base, DIM);
			y += fn.getHeight();
		}
		return y;
	}

	/** A coloured dot, text on the left, a status word on the right. */
	private int dotRow(Graphics2D g, boolean draw, int x0, int y, int cw, Color dot, String left, Color leftColor, String right, Color rightColor, FontMetrics fn, FontMetrics fs)
	{
		int h = fn.getHeight();
		if (draw)
		{
			g.setColor(dot);
			g.fillOval(x0, y + (h - 7) / 2, 7, 7);
		}
		int rw = right == null || right.isEmpty() ? 0 : fs.stringWidth(right);
		text(g, draw, std, fit(fn, left, cw - 12 - rw - (rw > 0 ? 8 : 0)), x0 + 12, y + fn.getAscent(), leftColor);
		if (rw > 0)
		{
			text(g, draw, small, right, x0 + cw - rw, y + fn.getAscent(), rightColor);
		}
		return h;
	}

	/** Small outlined tags in a row that wraps. */
	private int chips(Graphics2D g, boolean draw, int x0, int y, int cw, List<String> labels, FontMetrics fs)
	{
		int h = fs.getHeight() + 2;
		int x = x0;
		int rows = 1;
		for (String s : labels)
		{
			int w = fs.stringWidth(s) + 8;
			if (x > x0 && x + w > x0 + cw)
			{
				x = x0;
				y += h + 3;
				rows++;
			}
			if (draw)
			{
				g.setColor(new Color(0, 0, 0, 60));
				g.fillRect(x, y, w, h);
				g.setColor(new Color(170, 170, 170, 110));
				g.drawRect(x, y, w - 1, h - 1);
			}
			text(g, draw, small, s, x + 4, y + 1 + fs.getAscent(), DIM);
			x += w + 4;
		}
		return (h + 3) * rows;
	}

	/** An accent bar, a small kicker and the step text. */
	private int callout(Graphics2D g, boolean draw, int x0, int y, int cw, String kicker, String body, FontMetrics fn, FontMetrics fs)
	{
		List<String> lines = wrap(fn, body, cw - 8);
		int h = fs.getHeight() + lines.size() * fn.getHeight() + 2;
		if (draw)
		{
			g.setColor(new Color(0, 0, 0, 50));
			g.fillRect(x0, y, cw, h);
			g.setColor(ACCENT);
			g.fillRect(x0, y, 2, h);
		}
		text(g, draw, small, kicker, x0 + 6, y + 1 + fs.getAscent(), ACCENT);
		int ly = y + fs.getHeight();
		for (String l : lines)
		{
			text(g, draw, std, l, x0 + 6, ly + fn.getAscent(), Color.WHITE);
			ly += fn.getHeight();
		}
		return h + 3;
	}

	private int rule(Graphics2D g, boolean draw, int x0, int y, int cw)
	{
		if (draw)
		{
			g.setColor(RULE);
			g.fillRect(x0, y + 1, cw, 1);
		}
		return y + 5;
	}

	private static void text(Graphics2D g, boolean draw, Font f, String s, int x, int y, Color c)
	{
		if (!draw || s == null || s.isEmpty())
		{
			return;
		}
		g.setFont(f);
		g.setColor(Color.BLACK);
		g.drawString(s, x + 1, y + 1);
		g.setColor(c);
		g.drawString(s, x, y);
	}

	private static String fit(FontMetrics fm, String s, int max)
	{
		if (s == null)
		{
			return "";
		}
		if (fm.stringWidth(s) <= max)
		{
			return s;
		}
		String t = s;
		while (t.length() > 1 && fm.stringWidth(t + "..") > max)
		{
			t = t.substring(0, t.length() - 1);
		}
		return t.trim() + "..";
	}

	private static List<String> wrap(FontMetrics fm, String s, int max)
	{
		List<String> out = new ArrayList<>();
		StringBuilder line = new StringBuilder();
		for (String word : s.split(" "))
		{
			String next = line.length() == 0 ? word : line + " " + word;
			if (fm.stringWidth(next) > max && line.length() > 0)
			{
				out.add(line.toString());
				line = new StringBuilder(word);
			}
			else
			{
				line = new StringBuilder(next);
			}
		}
		if (line.length() > 0)
		{
			out.add(line.toString());
		}
		return out;
	}

	// ---------------------------------------------------------------- icons and words

	private BufferedImage itemIcon(TaskRecord rec)
	{
		Integer id = rec == null ? null : rec.getIconItemId();
		if (id == null)
		{
			return null;
		}
		if (itemIconFor != id || itemIcon == null)
		{
			try
			{
				itemIcon = itemManager.getImage(id, 1, false);
				itemIconFor = id;
			}
			catch (RuntimeException e)
			{
				itemIcon = null;
			}
		}
		return itemIcon;
	}

	private static String firstLocationNames(TaskRecord rec)
	{
		List<String> names = new ArrayList<>();
		for (LocationRecord l : rec.getLocations())
		{
			if (names.size() == 2)
			{
				break;
			}
			names.add(l.getName());
		}
		return String.join(" / ", names);
	}
}

