package com.slayersuite.data;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;

/** Loads monsters.json and items.json from the plugin resources and answers lookups by task name. */
@Slf4j
@Singleton
public class SlayerDataset
{
	private static final String MONSTERS = "/com/slayersuite/data/monsters.json";
	private static final String ITEMS = "/com/slayersuite/data/items.json";

	private final Gson gson;

	private final Map<String, TaskRecord> byKey = new HashMap<>();
	private final Map<String, TaskRecord> byName = new HashMap<>();
	private final Map<String, TaskRecord> byMonster = new HashMap<>();

	@Getter
	private List<TaskRecord> tasks = Collections.emptyList();
	@Getter
	private ItemGroups items = new ItemGroups();
	@Getter
	private String generated = "";
	@Getter
	private boolean loaded;

	private static class DatasetFile
	{
		int schemaVersion;
		String generated;
		String source;
		List<TaskRecord> tasks;
	}

	@Inject
	public SlayerDataset(Gson gson)
	{
		this.gson = gson;
	}

	public synchronized void load()
	{
		try (Reader r = open(MONSTERS))
		{
			DatasetFile f = gson.fromJson(r, DatasetFile.class);
			tasks = f.tasks == null ? Collections.emptyList() : f.tasks;
			generated = f.generated == null ? "" : f.generated;
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Slayer Suite: could not read monsters.json", e);
			tasks = Collections.emptyList();
		}
		try (Reader r = open(ITEMS))
		{
			ItemGroups g = gson.fromJson(r, ItemGroups.class);
			items = g == null ? new ItemGroups() : g;
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Slayer Suite: could not read items.json", e);
			items = new ItemGroups();
		}
		index();
		loaded = true;
		log.debug("Slayer Suite dataset: {} tasks, {} item groups, generated {}", tasks.size(), items.keys().size(), generated);
	}

	private Reader open(String resource) throws IOException
	{
		InputStream in = SlayerDataset.class.getResourceAsStream(resource);
		if (in == null)
		{
			throw new IOException("missing resource " + resource);
		}
		return new InputStreamReader(in, StandardCharsets.UTF_8);
	}

	private void index()
	{
		byKey.clear();
		byName.clear();
		byMonster.clear();
		for (TaskRecord t : tasks)
		{
			if (t.getKey() != null)
			{
				byKey.put(t.getKey(), t);
			}
			putName(t.getName(), t);
			putName(t.getDisplayName(), t);
			for (String a : t.getAliases())
			{
				putName(a, t);
			}
			if (!t.getCoreTargetNames().isEmpty())
			{
				putName(t.getCoreTargetNames().get(0), t);
			}
		}
		for (TaskRecord t : tasks)
		{
			for (MonsterRecord m : t.getMonsters())
			{
				byMonster.putIfAbsent(ItemNames.key(m.getName()), t);
				byMonster.putIfAbsent(ItemNames.key(m.getLabel()), t);
			}
			for (String n : t.getCoreTargetNames())
			{
				byMonster.putIfAbsent(ItemNames.key(n), t);
			}
		}
	}

	private void putName(String name, TaskRecord t)
	{
		String k = ItemNames.key(name);
		if (!k.isEmpty())
		{
			byName.putIfAbsent(k, t);
		}
	}

	/** Find the record for a task name as the core Slayer plugin reports it (any case, singular or plural). */
	public TaskRecord find(String taskName)
	{
		String k = ItemNames.key(taskName);
		if (k.isEmpty())
		{
			return null;
		}
		for (String cand : variants(k))
		{
			TaskRecord t = byName.get(cand);
			if (t != null)
			{
				return t;
			}
		}
		for (String cand : variants(k))
		{
			TaskRecord t = byMonster.get(cand);
			if (t != null)
			{
				return t;
			}
		}
		return null;
	}

	/** The task a monster name belongs to, or null. */
	public TaskRecord forMonsterName(String npcName)
	{
		String k = ItemNames.key(npcName);
		if (k.isEmpty())
		{
			return null;
		}
		for (String cand : variants(k))
		{
			TaskRecord t = byMonster.get(cand);
			if (t != null)
			{
				return t;
			}
		}
		return null;
	}

	public TaskRecord byKey(String key)
	{
		return byKey.get(key);
	}

	/** The dataset location whose regions include one of the loaded map regions, or null. */
	public LocationRecord locationFor(TaskRecord rec, int[] regions)
	{
		return locationFor(rec, regions, -1);
	}

	/** The task location whose map squares you are in, on the same floor when the location names one; plane -1 ignores floors. */
	public LocationRecord locationFor(TaskRecord rec, int[] regions, int plane)
	{
		if (rec == null || regions == null)
		{
			return null;
		}
		for (LocationRecord loc : rec.getLocations())
		{
			if (plane >= 0 && loc.getPlane() != null && loc.getPlane() != plane)
			{
				continue;
			}
			for (int r : regions)
			{
				if (loc.coversRegion(r))
				{
					return loc;
				}
			}
		}
		return null;
	}

	private static List<String> variants(String k)
	{
		Set<String> set = new HashSet<>();
		List<String> out = new ArrayList<>();
		add(out, set, k);
		if (k.endsWith("ies"))
		{
			add(out, set, k.substring(0, k.length() - 3) + "y");
		}
		if (k.endsWith("es"))
		{
			add(out, set, k.substring(0, k.length() - 2));
		}
		if (k.endsWith("s"))
		{
			add(out, set, k.substring(0, k.length() - 1));
		}
		else
		{
			add(out, set, k + "s");
			add(out, set, k + "es");
		}
		if (k.startsWith("the"))
		{
			add(out, set, k.substring(3));
		}
		return out;
	}

	private static void add(List<String> out, Set<String> seen, String s)
	{
		if (!s.isEmpty() && seen.add(s))
		{
			out.add(s);
		}
	}
}

package com.slayersuite.data;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import lombok.Data;

/** One slayer assignment as the dataset describes it. */
@Data
public class TaskRecord
{
	private String key;
	private String name;
	private String displayName;
	private String wikiPage;
	private List<String> aliases = new ArrayList<>();
	private Integer slayerLevel;
	private Integer combatLevel;
	private String otherRequirements;
	private Integer taskId;
	private Map<String, MasterRange> masters = new HashMap<>();
	private List<MonsterRecord> monsters = new ArrayList<>();
	private List<String> superiors = new ArrayList<>();
	private List<LocationRecord> locations = new ArrayList<>();
	private List<ItemRule> requiredItems = new ArrayList<>();
	private ItemRule finishingItem;
	private List<ItemRule> protection = new ArrayList<>();
	private String style;
	private List<String> notes = new ArrayList<>();
	private List<String> coreTargetNames = new ArrayList<>();
	private boolean reviewed;
	private boolean fallback;
	/** Item whose sprite stands for this task (the same one the client's slayer infobox uses). */
	private Integer iconItemId;

	public String title()
	{
		return displayName != null && !displayName.isEmpty() ? displayName : name;
	}

	/** Every rule the readiness check evaluates, required ones first. */
	public List<ItemRule> allRules()
	{
		List<ItemRule> out = new ArrayList<>();
		if (requiredItems != null)
		{
			out.addAll(requiredItems);
		}
		if (finishingItem != null)
		{
			out.add(finishingItem);
		}
		if (protection != null)
		{
			out.addAll(protection);
		}
		out.sort((a, b) -> Boolean.compare(b.isRequired(), a.isRequired()));
		return out;
	}

	public MonsterRecord primaryMonster()
	{
		if (monsters == null)
		{
			return null;
		}
		for (MonsterRecord m : monsters)
		{
			if (!m.isSuperior())
			{
				return m;
			}
		}
		return monsters.isEmpty() ? null : monsters.get(0);
	}

	public boolean anyPoisonous()
	{
		if (monsters == null)
		{
			return false;
		}
		for (MonsterRecord m : monsters)
		{
			if (isRegular(m) && (m.isPoisonous() || m.isVenomous()))
			{
				return true;
			}
		}
		return false;
	}

	public boolean anyVenomous()
	{
		if (monsters == null)
		{
			return false;
		}
		for (MonsterRecord m : monsters)
		{
			if (isRegular(m) && m.isVenomous())
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * How much a cannon (or any multi-target method) helps on this task's monster, 0 to 1: nothing
	 * on things that die in a hit (crawling hands, 16 Hitpoints), everything from about 90 Hitpoints
	 * (bloodvelds, demons). Unknown Hitpoints count as full.
	 */
	public double cannonWorth()
	{
		MonsterRecord m = primaryMonster();
		Integer hp = m == null ? null : m.getHitpoints();
		if (hp == null || hp <= 0)
		{
			return 1.0;
		}
		return Math.max(0, Math.min(1, (hp - 15) / 75.0));
	}

	/** True when the monster you grind the task on cannot be hit by a cannon. */
	public boolean cannonImmune()
	{
		MonsterRecord m = primaryMonster();
		if (m != null && isRegular(m))
		{
			return m.isCannonImmune();
		}
		if (monsters == null || monsters.isEmpty())
		{
			return false;
		}
		for (MonsterRecord x : monsters)
		{
			if (isRegular(x) && !x.isCannonImmune())
			{
				return false;
			}
		}
		return true;
	}

	private transient List<DropRecord> rareCache;

	/** The rare drops of the monsters you grind this task on (superiors left out; a boss task uses the boss), rarest first, one row per item. */
	public synchronized List<DropRecord> rareDrops()
	{
		List<DropRecord> cached = rareCache;
		if (cached != null)
		{
			return cached;
		}
		List<DropRecord> out = collectRare(true);
		if (out.isEmpty())
		{
			out = collectRare(false);
		}
		out.sort((a, b) -> Double.compare(a.probability(), b.probability()));
		rareCache = out;
		return out;
	}

	private List<DropRecord> collectRare(boolean regularOnly)
	{
		List<DropRecord> out = new ArrayList<>();
		Map<String, DropRecord> seen = new HashMap<>();
		if (monsters != null)
		{
			for (MonsterRecord m : monsters)
			{
				if (m.isSuperior() || (regularOnly && !isRegular(m)) || m.getDrops() == null || m.getName() == null)
				{
					continue;
				}
				for (DropRecord d : m.getDrops())
				{
					if (d.getName() == null || d.probability() <= 0 || "superior".equals(d.getWhere()))
					{
						continue;
					}
					String k = ItemNames.key(d.getName()) + "|" + d.getWhere();
					DropRecord first = seen.get(k);
					if (first == null)
					{
						d.getFrom().clear();
						d.getFrom().add(m.getName());
						seen.put(k, d);
						out.add(d);
					}
					else if (!first.getFrom().contains(m.getName()))
					{
						first.getFrom().add(m.getName());
					}
				}
			}
		}
		return out;
	}

	/** The dataset monster matching an NPC name, or null. */
	public MonsterRecord monsterNamed(String npcName)
	{
		if (npcName == null || monsters == null)
		{
			return null;
		}
		for (MonsterRecord m : monsters)
		{
			if (npcName.equalsIgnoreCase(m.getName()) || npcName.equalsIgnoreCase(m.getLabel()))
			{
				return m;
			}
		}
		return null;
	}

	/** Not a superior and not a boss: the monsters you actually grind the task on. */
	private static boolean isRegular(MonsterRecord m)
	{
		if (m.isSuperior())
		{
			return false;
		}
		String cat = m.getCategory();
		return cat == null || !cat.toLowerCase().contains("boss");
	}
}

package com.slayersuite.data;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import javax.inject.Singleton;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Quest;

/** Every bank and every Slayer master with a map position, from banks.tsv and masters.tsv (built from the wiki). */
@Slf4j
@Singleton
public class TravelPoints
{
	private static final String BANKS = "/com/slayersuite/data/banks.tsv";
	private static final String MASTERS = "/com/slayersuite/data/masters.tsv";

	@Value
	public static class Point
	{
		String name;
		int x;
		int y;
		int plane;
		boolean members;
		/** Plain words from the wiki: a quest name, "Farming 85", a diary, or empty. */
		String requirement;
		/** The id the game's task tables use for this master's list; -1 for a bank or a master not in them. */
		int masterId;
		/** The place a master stands in, for the label. */
		String place;
	}

	/** What a bank asks of you before you can use it, as far as the plugin can check. */
	public static final class Requirement
	{
		public enum Kind
		{
			NONE, QUEST, SKILL, DIARY, UNKNOWN
		}

		public final Kind kind;
		/** Quest constant, skill constant or diary key, by kind. */
		public final String key;
		public final int level;

		Requirement(Kind kind, String key, int level)
		{
			this.kind = kind;
			this.key = key;
			this.level = level;
		}
	}

	private volatile List<Point> banks = Collections.emptyList();
	private volatile List<Point> masters = Collections.emptyList();

	public synchronized void load()
	{
		banks = read(BANKS, false);
		masters = read(MASTERS, true);
		log.debug("Slayer Suite travel points: {} banks, {} masters", banks.size(), masters.size());
	}

	private static List<Point> read(String resource, boolean masterFile)
	{
		List<Point> out = new ArrayList<>();
		try (InputStream in = TravelPoints.class.getResourceAsStream(resource))
		{
			if (in == null)
			{
				throw new IOException("missing resource " + resource);
			}
			BufferedReader r = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8));
			String line;
			while ((line = r.readLine()) != null)
			{
				if (line.isEmpty() || line.startsWith("#"))
				{
					continue;
				}
				String[] f = line.split("\t", -1);
				if (f.length < 4)
				{
					continue;
				}
				try
				{
					int x = Integer.parseInt(f[1].trim());
					int y = Integer.parseInt(f[2].trim());
					int plane = Integer.parseInt(f[3].trim());
					if (masterFile)
					{
						int id = f.length > 4 && !f[4].trim().isEmpty() ? Integer.parseInt(f[4].trim()) : -1;
						out.add(new Point(f[0].trim(), x, y, plane, true, "", id, f.length > 5 ? f[5].trim() : ""));
					}
					else
					{
						boolean members = f.length > 4 && f[4].trim().equalsIgnoreCase("yes");
						out.add(new Point(f[0].trim(), x, y, plane, members, f.length > 5 ? f[5].trim() : "", -1, ""));
					}
				}
				catch (NumberFormatException e)
				{
					log.debug("bad travel point line: {}", line);
				}
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Slayer Suite: could not read {}", resource, e);
		}
		return out;
	}

	public List<Point> banks()
	{
		return banks;
	}

	public List<Point> masters()
	{
		return masters;
	}

	/** The Slayer master with this NPC name, or null. */
	public Point master(String npcName)
	{
		if (npcName == null)
		{
			return null;
		}
		for (Point p : masters)
		{
			if (p.getName().equalsIgnoreCase(npcName))
			{
				return p;
			}
		}
		return null;
	}

	/** The first master whose task list has this id, or null. */
	public Point masterFor(int masterId)
	{
		if (masterId < 0)
		{
			return null;
		}
		for (Point p : masters)
		{
			if (p.getMasterId() == masterId)
			{
				return p;
			}
		}
		return null;
	}

	/** Dungeon levels are stored 6400 tiles north of the ground they lie under; fold them back for distances. */
	public static int surfaceY(int y)
	{
		return y >= 6400 ? y - 6400 : y;
	}

	/** The n points nearest to (x, y) in straight-line tiles, dungeons folded onto the surface. */
	public static List<Point> nearest(List<Point> points, int x, int y, int n)
	{
		List<Point> sorted = new ArrayList<>(points);
		sorted.sort((a, b) -> Integer.compare(distance(a, x, y), distance(b, x, y)));
		return sorted.size() > n ? new ArrayList<>(sorted.subList(0, n)) : sorted;
	}

	public static int distance(Point p, int x, int y)
	{
		return Math.max(Math.abs(p.getX() - x), Math.abs(surfaceY(p.getY()) - surfaceY(y)));
	}

	/** Reads a requirement cell: nothing, a quest the client knows, "Skill N", "<Tier> <Area> Diary", or something the plugin cannot check. */
	public static Requirement requirement(String text)
	{
		String s = text == null ? "" : text.trim();
		if (s.isEmpty() || s.equalsIgnoreCase("none"))
		{
			return new Requirement(Requirement.Kind.NONE, null, 0);
		}
		java.util.regex.Matcher skill = java.util.regex.Pattern.compile("^([A-Za-z]+) (\\d+)$").matcher(s);
		if (skill.matches())
		{
			return new Requirement(Requirement.Kind.SKILL, skill.group(1).toUpperCase(Locale.ROOT), Integer.parseInt(skill.group(2)));
		}
		java.util.regex.Matcher diary = java.util.regex.Pattern.compile("^(Easy|Medium|Hard|Elite) ([A-Za-z' ]+?) Diary$", java.util.regex.Pattern.CASE_INSENSITIVE).matcher(s);
		if (diary.matches())
		{
			String area = diary.group(2).toUpperCase(Locale.ROOT).replace("'", "").replace(' ', '_');
			return new Requirement(Requirement.Kind.DIARY, area + "_" + diary.group(1).toUpperCase(Locale.ROOT), 0);
		}
		String constant = questConstant(s);
		if (constant != null)
		{
			return new Requirement(Requirement.Kind.QUEST, constant, 0);
		}
		return new Requirement(Requirement.Kind.UNKNOWN, s, 0);
	}

	/** The Quest constant a wiki quest name stands for, or null when the client has no such quest. */
	public static String questConstant(String name)
	{
		if (name == null)
		{
			return null;
		}
		String base = name.toUpperCase(Locale.ROOT).replace("'", "").replace("’", "").replaceAll("[^A-Z0-9]+", "_").replaceAll("^_+|_+$", "");
		if (base.isEmpty())
		{
			return null;
		}
		String[] tries = {base, "THE_" + base, base.startsWith("THE_") ? base.substring(4) : base};
		for (String t : tries)
		{
			try
			{
				Quest.valueOf(t);
				return t;
			}
			catch (IllegalArgumentException ignored)
			{
				// not this spelling
			}
		}
		return null;
	}
}

package com.slayersuite.guard;

import com.slayersuite.SlayerSuiteConfig;
import com.slayersuite.data.SlayerDataset;
import com.slayersuite.data.TaskRecord;
import com.slayersuite.task.TaskTracker;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.PostMenuSort;
import net.runelite.client.eventbus.Subscribe;

/**
 * Removes or deprioritises the Attack option on NPCs that do not count for the
 * current task. Reads menu entries and edits the menu only; never clicks.
 */
@Singleton
public class AttackGuard
{
	private final Client client;
	private final SlayerSuiteConfig config;
	private final TaskTracker tracker;
	private final SlayerDataset dataset;
	private final javax.inject.Provider<com.slayersuite.task.SlayerMode> mode;

	@Inject
	public AttackGuard(Client client, SlayerSuiteConfig config, TaskTracker tracker, SlayerDataset dataset, javax.inject.Provider<com.slayersuite.task.SlayerMode> mode)
	{
		this.client = client;
		this.config = config;
		this.tracker = tracker;
		this.dataset = dataset;
		this.mode = mode;
	}

	private boolean active()
	{
		if (!config.guardEnabled() || !mode.get().active())
		{
			return false;
		}
		return tracker.hasTask() || config.guardWithoutTask();
	}

	private static boolean isNpcOption(MenuAction type)
	{
		return type == MenuAction.NPC_FIRST_OPTION || type == MenuAction.NPC_SECOND_OPTION
			|| type == MenuAction.NPC_THIRD_OPTION || type == MenuAction.NPC_FOURTH_OPTION
			|| type == MenuAction.NPC_FIFTH_OPTION;
	}

	/** True when the NPC should keep its Attack option. */
	public boolean isTaskTarget(NPC npc)
	{
		if (npc == null)
		{
			return true;
		}
		if (!tracker.hasTask())
		{
			return false;
		}
		if (tracker.getTargets().contains(npc))
		{
			return true;
		}
		// The core plugin matches by name as well; fall back to the dataset in case its list lags a tick.
		NPCComposition comp = npc.getTransformedComposition();
		String name = comp == null ? npc.getName() : comp.getName();
		if (name == null)
		{
			return false;
		}
		TaskRecord rec = tracker.getRecord();
		if (rec != null)
		{
			for (String n : rec.getCoreTargetNames())
			{
				if (name.equalsIgnoreCase(n))
				{
					return true;
				}
			}
			TaskRecord byMonster = dataset.forMonsterName(name);
			return byMonster == rec;
		}
		return false;
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded e)
	{
		if (!active() || config.guardMode() != GuardMode.DEPRIORITIZE)
		{
			return;
		}
		if (!isNpcOption(e.getMenuEntry().getType()) || !"Attack".equalsIgnoreCase(e.getOption()))
		{
			return;
		}
		NPC npc = e.getMenuEntry().getNpc();
		if (npc != null && !isTaskTarget(npc))
		{
			e.getMenuEntry().setDeprioritized(true);
		}
	}

	@Subscribe
	public void onPostMenuSort(PostMenuSort sort)
	{
		if (!active() || config.guardMode() != GuardMode.HIDE || client.isMenuOpen())
		{
			return;
		}
		MenuEntry[] entries = client.getMenu().getMenuEntries();
		if (entries == null || entries.length == 0)
		{
			return;
		}
		List<MenuEntry> kept = null;
		for (int i = 0; i < entries.length; i++)
		{
			MenuEntry me = entries[i];
			boolean drop = false;
			if (isNpcOption(me.getType()) && "Attack".equalsIgnoreCase(me.getOption()))
			{
				NPC npc = me.getNpc();
				drop = npc != null && !isTaskTarget(npc);
			}
			if (drop)
			{
				if (kept == null)
				{
					kept = new ArrayList<>(entries.length);
					for (int j = 0; j < i; j++)
					{
						kept.add(entries[j]);
					}
				}
			}
			else if (kept != null)
			{
				kept.add(me);
			}
		}
		if (kept != null)
		{
			client.getMenu().setMenuEntries(kept.toArray(new MenuEntry[0]));
		}
	}
}

