	@Subscribe
	public void onKillCounted(KillCounted e)
	{
		if (current == null)
		{
			return;
		}
		long now = System.currentTimeMillis();
		if (lastKillAt > 0 && now - lastKillAt < BREAK_GAP_MS)
		{
			sessionActiveMs += now - lastKillAt;
		}
		com.slayersuite.data.LocationRecord here = tracker.getCurrentLocation();
		TaskStats.SpotStats spot;
		synchronized (this)
		{
			spot = here == null ? null : current.spot(here.getName());
		}
		if (spot != null)
		{
			spot.kills += e.getDelta();
		}
		if (lastKillAt > 0 && now - lastKillAt < BREAK_GAP_MS)
		{
			long gap = now - lastKillAt;
			assignmentMs += gap;
			if (spot != null)
			{
				spot.activeMs += gap;
			}
			if (gap >= IDLE_GAP_MS)
			{
				if (tracker.getCurrentLocation() != null)
				{
					assignmentIdleMs += gap;
				}
				else
				{
					assignmentAwayMs += gap;
				}
			}
			synchronized (this)
			{
				ledger().activeMs += gap;
				today(ledger())[1] += gap;
			}
		}
		lastKillAt = now;
		lastKillCountedAt = now;
		for (PickupMatcher.Pending pd : pending)
		{
			if (!pd.killConfirmed && now - pd.at <= KILL_MATCH_MS)
			{
				pd.killConfirmed = true;
			}
		}
		sessionKills += e.getDelta();
		assignmentKills += e.getDelta();
		synchronized (this)
		{
			ledger().kills += e.getDelta();
			today(ledger())[0] += e.getDelta();
		}
		dirty = true;
		if (sessionKills >= 3)
		{
			advice = null;
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged e)
	{
		Integer prev = levels.put(e.getSkill(), e.getLevel());
		if (prev != null && e.getLevel() > prev && client.getGameState() == GameState.LOGGED_IN)
		{
			levelUp(e.getSkill(), e.getLevel(), false);
		}
		else if (prev == null && e.getSkill() == Skill.SLAYER && client.getGameState() == GameState.LOGGED_IN)
		{
			seedSlayerMark();
		}
		if (e.getSkill() != Skill.SLAYER)
		{
			return;
		}
		int xp = e.getXp();
		slayerXp = xp;
		if (current != null && lastSlayerXp >= 0 && xp > lastSlayerXp)
		{
			sessionXp += xp - lastSlayerXp;
			synchronized (this)
			{
				today(ledger())[2] += xp - lastSlayerXp;
			}
			assignmentXp += xp - lastSlayerXp;
			com.slayersuite.data.LocationRecord here = tracker.getCurrentLocation();
			if (here != null)
			{
				synchronized (this)
				{
					current.spot(here.getName()).xp += xp - lastSlayerXp;
				}
			}
			dirty = true;
		}
		lastSlayerXp = xp;
	}

	@Subscribe
	public void onNpcLootReceived(NpcLootReceived e)
	{
		if (current == null)
		{
			return;
		}
		NPC npc = e.getNpc();
		if (npc == null || !guard.isTaskTarget(npc))
		{
			return;
		}
		long gp = 0;
		long now = System.currentTimeMillis();
		WorldPoint where = npc.getWorldLocation();
		boolean killConfirmed = now - lastKillCountedAt <= KILL_MATCH_MS;
		TaskRecord rec = tracker.getRecord();
		String monsterKey = monsterKeyFor(rec, npc.getName());
		if (monsterKey != null)
		{
			synchronized (this)
			{
				current.monsterKill(monsterKey);
			}
		}
		for (ItemStack s : e.getItems())
		{
			int id = itemManager.canonicalize(s.getId());
			long price = id == ItemID.COINS ? 1 : itemManager.getItemPrice(id);
			gp += price * s.getQuantity();
			// counted as loot only once it reaches the inventory, near where the monster died, and
			// only if the task's kill counter moved for this death (see onItemContainerChanged)
			PickupMatcher.Pending pd = new PickupMatcher.Pending(id, s.getQuantity(), price, now,
				where == null ? -1 : where.getX(), where == null ? -1 : where.getY(), where == null ? -1 : where.getPlane(), killConfirmed);
			pd.rawId = s.getId();
			pd.windowMs = tradeable(id) ? PICKUP_WINDOW_TRADEABLE_MS : PICKUP_WINDOW_MS;
			String name;
			synchronized (this)
			{
				// the panel reads these maps on its own thread
				Ledger l = ledger();
				pd.task = taskIndex(l);
				name = l.names.get(String.valueOf(id));
				if (name == null)
				{
					try
					{
						name = itemManager.getItemComposition(id).getName();
						l.names.put(String.valueOf(id), name);
					}
					catch (RuntimeException ignored)
					{
						// name unknown
					}
				}
			}
			markRareDrop(rec, name, now);
			// a carried herb sack or seed box swallows these on pickup without touching the inventory
			if (name != null)
			{
				String n = name.toLowerCase(Locale.ROOT);
				boolean herbSack = inventory.containsKey(ItemID.SLAYER_HERB_SACK) || inventory.containsKey(ItemID.SLAYER_HERB_SACK_OPEN);
				boolean seedBox = inventory.containsKey(ItemID.SEED_BOX) || inventory.containsKey(ItemID.SEED_BOX_OPEN);
				pd.autoStored = (herbSack && n.startsWith("grimy ")) || (seedBox && n.endsWith(" seed"));
			}
			pending.add(pd);
		}
		sessionGp += gp;
		assignmentGp += gp;
		dirty = true;
	}

	/** The dataset name of the monster an NPC stands for, or its own name; null without a name. */
	private static String monsterKeyFor(TaskRecord rec, String npcName)
	{
		if (npcName == null || npcName.isEmpty())
		{
			return null;
		}
		MonsterRecord m = rec == null ? null : rec.monsterNamed(npcName);
		return m != null && m.getName() != null ? m.getName() : npcName;
	}

	/** Remembers a rare drop of this task the moment it hits the floor, with your kill count of the monsters that drop it. */
	private void markRareDrop(TaskRecord rec, String name, long now)
	{
		if (rec == null || name == null || current == null)
		{
			return;
		}
		String k = ItemNames.key(name);
		for (DropRecord d : rec.rareDrops())
		{
			if (ItemNames.key(d.getName()).equals(k))
			{
				synchronized (this)
				{
					long[] m = current.drop(d.getName());
					m[0]++;
					m[1] = killsOf(current, d);
					m[2] = now;
				}
				dirty = true;
				return;
			}
		}
	}

	/** Your kills on this task of the monsters that drop an item. */
	private static long killsOf(TaskStats s, DropRecord d)
	{
		long n = 0;
		for (String mon : d.getFrom())
		{
			n += s.monsterKills(mon);
		}
		return n;
	}

	/** One rare drop of the current task with your own numbers behind it. */
	@lombok.Value
	public static class DryOdds
	{
		String name;
		String rarity;
		double p;
		long seen;
		/** Kills of the monsters that drop it since you last saw it (all your kills when never). */
		long killsSince;
		long lastAt;

		/** The chance you would have had at least one by now, over the kills since the last. */
		public double chanceByNow()
		{
			return DropRecord.chanceBy(p, killsSince);
		}

		public long expectedEvery()
		{
			return p > 0 ? Math.round(1 / p) : 0;
		}
	}

	/** The current task's rare drops at maxP or rarer, rarest first, from the monsters you have been killing on it (the main one before any kill), at most max rows. */
	public List<DryOdds> dryOdds(int max, double maxP)
	{
		TaskRecord rec = tracker.getRecord();
		if (rec == null || max <= 0)
		{
			return java.util.Collections.emptyList();
		}
		TaskStats s = current;
		int master = tracker.currentMasterId();
		com.slayersuite.data.LocationRecord here = tracker.getCurrentLocation();
		String place = here == null ? null : here.getName();
		boolean anyKills = s != null && s.anyMonsterKills();
		MonsterRecord primary = rec.primaryMonster();
		String primaryKey = primary == null ? null : primary.getName();
		List<DryOdds> out = new ArrayList<>();
		for (DropRecord d : rec.rareDrops())
		{
			if (d.probability() > maxP || !d.appliesTo(master, place))
			{
				continue;
			}
			boolean relevant = false;
			for (String mon : d.getFrom())
			{
				if (anyKills ? s.monsterKills(mon) > 0 : mon.equals(primaryKey))
				{
					relevant = true;
					break;
				}
			}
			if (!relevant)
			{
				continue;
			}
			long[] m = s == null ? null : s.dropMark(d.getName());
			long kills = s == null ? 0 : killsOf(s, d);
			long seen = m == null ? 0 : m[0];
			long since = m == null ? kills : Math.max(0, kills - m[1]);
			out.add(new DryOdds(d.getName(), d.shownRarity(), d.probability(), seen, since, m == null ? 0 : m[2]));
			if (out.size() >= max)
			{
				break;
			}
		}
		return out;
	}

