	/** Inventory gains that match a recent drop from a task monster become picked-up loot. */
	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged e)
	{
		if (e.getContainerId() != InventoryID.INV)
		{
			return;
		}
		ItemContainer inv = e.getItemContainer();
		Map<Integer, Integer> now = new HashMap<>();
		if (inv != null)
		{
			for (Item it : inv.getItems())
			{
				if (it != null && it.getId() > 0 && it.getQuantity() > 0)
				{
					now.merge(itemManager.canonicalize(it.getId()), it.getQuantity(), Integer::sum);
				}
			}
		}
		Map<Integer, Integer> before = inventory;
		inventory = now;
		long t = System.currentTimeMillis();
		expirePending(t);
		if (bankOpen || pending.isEmpty())
		{
			return;
		}
		WorldPoint me = client.getLocalPlayer() == null ? null : client.getLocalPlayer().getWorldLocation();
		int px = me == null ? -1 : me.getX();
		int py = me == null ? -1 : me.getY();
		int pplane = me == null ? -1 : me.getPlane();
		// the last task's drops still on the floor match too: a drop is credited to the task it came from
		for (long[] take : PickupMatcher.match(before, now, pending, t, PICKUP_WINDOW_MS, px, py, pplane, PICKUP_TILES))
		{
			takeLoot((int) take[0], take[1], take[2], t, (int) take[3]);
		}
	}

	private boolean tradeable(int id)
	{
		try
		{
			return itemManager.getItemComposition(id).isTradeable();
		}
		catch (RuntimeException e)
		{
			return false;
		}
	}

	/** Each tick: retire drops past their window, and credit herb sack / seed box pickups when you stand on the drop. */
	private void tickPending()
	{
		if (pending.isEmpty())
		{
			floorValue = 0;
			floorSoonestAt = 0;
			return;
		}
		long t = System.currentTimeMillis();
		expirePending(t);
		refreshFloor();
		WorldPoint me = client.getLocalPlayer() == null ? null : client.getLocalPlayer().getWorldLocation();
		if (me == null)
		{
			return;
		}
		for (Iterator<PickupMatcher.Pending> it = pending.iterator(); it.hasNext(); )
		{
			PickupMatcher.Pending pd = it.next();
			if (pd.autoStored && pd.killConfirmed && pd.x >= 0 && pd.near(me.getX(), me.getY(), me.getPlane(), 0))
			{
				takeLoot(pd.id, pd.quantity, pd.quantity * pd.priceEach, t, pd.task);
				it.remove();
			}
		}
	}

	/** Value of your marked drops still on the floor, and when the first of them vanishes; refreshed each tick, safe from Swing. */
	@Getter
	private volatile long floorValue;
	@Getter
	private volatile long floorSoonestAt;
	/** Value of the drop(s) that vanish first. */
	@Getter
	private volatile long floorSoonestValue;

	private void refreshFloor()
	{
		long value = 0;
		long soonest = Long.MAX_VALUE;
		long soonValue = 0;
		long min = config.floorLootMin();
		long now = System.currentTimeMillis();
		WorldView wv = client.getTopLevelWorldView();
		Tile[][][] tiles = wv == null || wv.getScene() == null ? null : wv.getScene().getTiles();
		for (long[] d : floorDrops())
		{
			if (d[5] < min || d[6] <= now)
			{
				continue;
			}
			// a drop whose tile is loaded but holds no such item is gone: taken by someone, or vanished
			if (tiles != null && LocalPoint.fromWorld(wv, (int) d[0], (int) d[1]) != null
				&& FloorLootOverlay.locate(wv, tiles, (int) d[0], (int) d[1], (int) d[2], (int) d[7]) == null)
			{
				continue;
			}
			value += d[5];
			if (d[6] < soonest)
			{
				soonest = d[6];
				soonValue = d[5];
			}
			else if (d[6] == soonest)
			{
				soonValue += d[5];
			}
		}
		floorValue = value;
		floorSoonestAt = soonest == Long.MAX_VALUE ? 0 : soonest;
		floorSoonestValue = soonest == Long.MAX_VALUE ? 0 : soonValue;
	}

	/** Your drops still lying where they fell: {x, y, plane, item id, quantity, value, vanishes at (ms)}. Client thread. */
	public List<long[]> floorDrops()
	{
		List<long[]> out = new ArrayList<>();
		for (PickupMatcher.Pending pd : pending)
		{
			if (pd.x < 0 || pd.autoStored || pd.quantity <= 0)
			{
				continue;
			}
			long window = pd.windowMs > 0 ? pd.windowMs : PICKUP_WINDOW_MS;
			out.add(new long[]{pd.x, pd.y, pd.plane, pd.id, pd.quantity, pd.quantity * pd.priceEach, pd.at + FloorLootMath.vanishAfter(window), pd.rawId >= 0 ? pd.rawId : pd.id});
		}
		return out;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		if (e.getGameState() == GameState.LOGGED_IN)
		{
			lastSlayerXp = -1;
		}
		else if (e.getGameState() == GameState.LOGIN_SCREEN || e.getGameState() == GameState.HOPPING)
		{
			saveLedger();
			ledger = null;
			levels.clear();
			slayerXp = -1;
			inventory = new HashMap<>();
			pending.clear();
			if (current != null && dirty)
			{
				save(snapshot());
			}
			lastKillAt = 0;
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		tickPending();
		if (++pointsTick % 25 == 1)
		{
			computePointsSummary();
		}
		if (current != null && dirty && System.currentTimeMillis() - lastSaveAt > SAVE_EVERY_MS)
		{
			save(snapshot());
			saveAssignment();
		}
		int mort = tracker.getMortimerTasks();
		if (mort > 0)
		{
			Ledger l = ledger();
			boolean changed;
			synchronized (l)
			{
				changed = l.mortimerTasks != mort;
				if (changed)
				{
					l.mortimerTasks = mort;
				}
			}
			if (changed)
			{
				saveLedger();
			}
		}
	}

	/** Mortimer tasks completed: this session's chat count, else the last one remembered; 0 when never seen. */
	public int mortimerTasks()
	{
		int live = tracker.getMortimerTasks();
		if (live > 0)
		{
			return live;
		}
		Ledger l = ledger();
		synchronized (l)
		{
			return l.mortimerTasks;
		}
	}

	// ---------------------------------------------------------------- advice

	/** "92/h, 41k xp/h, 160k gp/h over 3 tasks", or "no history yet". */
	public String summary(TaskStats s)
	{
		if (s == null || !s.hasRate())
		{
			return "No history for this task yet.";
		}
		return "Your history: " + Math.round(s.killsPerHour()) + " kills/h, " + TripMath.formatK(Math.round(s.xpPerHour())) + " xp/h, "
			+ TripMath.formatK(Math.round(s.gpPerHour())) + " gp/h " + (s.getTasksFinished() == 0 ? "from " + s.getKills() + " kills so far." : "over " + s.getTasksFinished() + (s.getTasksFinished() == 1 ? " task." : " tasks."));
	}

	/** Compares this task's measured xp/h with the median of every task you have history for. */
	String computeAdvice(TaskStats s)
	{
		if (s == null || s.getKills() < ADVICE_MIN_KILLS || !s.hasRate())
		{
			return null;
		}
		List<Double> rates = new ArrayList<>();
		for (TaskStats t : all())
		{
			if (t.getKills() >= ADVICE_MIN_KILLS && t.hasRate())
			{
				rates.add(t.xpPerHour());
			}
		}
		if (rates.size() < 3)
		{
			return null;
		}
		rates.sort(Double::compare);
		double median = rates.get(rates.size() / 2);
		if (median <= 0)
		{
			return null;
		}
		double pct = s.xpPerHour() / median * 100.0;
		if (pct < config.skipBelowPercent())
		{
			double chance = tracker.rollChance();
			String roll = chance > 0 ? " It is " + Math.round(chance * 100) + "% of this master's rolls" + (chance >= 0.06 ? ": worth blocking." : ": skipping is enough.") : "";
			int have = tracker.getSlayerPoints();
			PointsSummary ps = pointsSummary;
			String payback = ps != null && ps.getSkipPaybackTasks() > 0 ? ", about " + String.format("%.1f", ps.getSkipPaybackTasks()) + " tasks of points at " + ps.getMaster() : "";
			String cost = have > 0 ? " A skip costs 30 points" + payback + " (you have " + String.format("%,d", have) + ")" + (chance >= 0.06 ? ", a block 100." : ".") : "";
			return "Low for you: " + Math.round(pct) + "% of your median xp/h. Consider skipping." + roll + cost;
		}
		if (pct > 150)
		{
			return "One of your best tasks (" + Math.round(pct) + "% of your median xp/h).";
		}
		return null;
	}
}

package com.slayersuite.history;

import lombok.Data;

/** Everything we have measured for one task across every assignment, stored per RuneScape profile. */
@Data
public class TaskStats
{
	private String key;
	private String name;
	private int tasksStarted;
	private int tasksFinished;
	private long kills;
	/** Milliseconds spent actually killing (gaps longer than a short break are not counted). */
	private long activeMs;
	private long slayerXp;
	private long lootGp;
	private long lastSeen;
	/** Exponential moving averages of consumption per kill, fed by the trip tracker. */
	private double foodPerKill;
	private double dosesPerKill;
	private double prayerPerKill;
	/** Slayer points earned finishing this task, and how many finishes that covers. */
	private long points;
	private int pointSamples;
	/** Times this task was skipped or blocked, and the points that cost. */
	private int skips;
	private int blocks;
	private long pointsSpent;
	/** Your fastest assignment of this task (20+ kills): rate and how much of it was idle or away. */
	private double bestKph;
	private long bestIdleMs;
	private long bestAwayMs;
	private long bestMs;
	/** Kills per hour with and without a cannon, smoothed over assignments; 0 until seen. */
	private double cannonKph;
	private double plainKph;
	private int superiors;
	/** What you did at each spot of this task: kills, active time, Slayer xp and picked-up loot. */
	private java.util.Map<String, SpotStats> spots = new java.util.LinkedHashMap<>();
	/** Rare drops seen on this task, by item name: {times seen, kills of the monsters that drop it when it last came, wall time}. */
	private java.util.Map<String, long[]> drops = new java.util.LinkedHashMap<>();
	/** Kills per monster on this task (deaths that dropped loot), by dataset monster name. */
	private java.util.Map<String, Long> monsterKills = new java.util.LinkedHashMap<>();
	/** Set when the stored record could not be read: nothing is saved over it. */
	private transient boolean unreadable;

	public static class SpotStats
	{
		public long kills;
		public long activeMs;
		public long xp;
		public long loot;

		public double killsPerHour()
		{
			return activeMs > 0 ? kills * 3_600_000.0 / activeMs : 0;
		}

		public double gpPerHour()
		{
			return activeMs > 0 ? loot * 3_600_000.0 / activeMs : 0;
		}

		public double xpPerHour()
		{
			return activeMs > 0 ? xp * 3_600_000.0 / activeMs : 0;
		}

		/** Enough play at this spot for a rate to mean something. */
		public boolean hasRate()
		{
			return kills >= 15 && activeMs >= 120_000L;
		}
	}

	public long[] drop(String key)
	{
		if (drops == null)
		{
			drops = new java.util.LinkedHashMap<>();
		}
		return drops.computeIfAbsent(key, k -> new long[3]);
	}

	/** The stored mark for an item, or null when never seen. */
	public long[] dropMark(String key)
	{
		return drops == null ? null : drops.get(key);
	}

	public void monsterKill(String monster)
	{
		if (monsterKills == null)
		{
			monsterKills = new java.util.LinkedHashMap<>();
		}
		monsterKills.merge(monster, 1L, Long::sum);
	}

	public long monsterKills(String monster)
	{
		Long n = monsterKills == null ? null : monsterKills.get(monster);
		return n == null ? 0 : n;
	}

	public boolean anyMonsterKills()
	{
		return monsterKills != null && !monsterKills.isEmpty();
	}

	public SpotStats spot(String name)
	{
		if (spots == null)
		{
			spots = new java.util.LinkedHashMap<>();
		}
		return spots.computeIfAbsent(name, k -> new SpotStats());
	}

	public double avgPoints()
	{
		return pointSamples > 0 ? points / (double) pointSamples : 0;
	}

	public boolean hasRate()
	{
		return kills >= 5 && activeMs > 60_000L;
	}

	public double killsPerHour()
	{
		return hasRate() ? kills * 3_600_000.0 / activeMs : 0;
	}

	public double xpPerHour()
	{
		return hasRate() ? slayerXp * 3_600_000.0 / activeMs : 0;
	}

	public double gpPerHour()
	{
		return hasRate() ? lootGp * 3_600_000.0 / activeMs : 0;
	}

	public double xpPerKill()
	{
		return kills > 0 ? slayerXp / (double) kills : 0;
	}

	public double gpPerKill()
	{
		return kills > 0 ? lootGp / (double) kills : 0;
	}

	/** Adds one session's measurements. */
	public void add(long sessionKills, long sessionActiveMs, long sessionXp, long sessionGp)
	{
		kills += Math.max(0, sessionKills);
		activeMs += Math.max(0, sessionActiveMs);
		slayerXp += Math.max(0, sessionXp);
		lootGp += Math.max(0, sessionGp);
		lastSeen = System.currentTimeMillis();
	}

	public TaskStats copy()
	{
		TaskStats c = new TaskStats();
		c.key = key;
		c.name = name;
		c.tasksStarted = tasksStarted;
		c.tasksFinished = tasksFinished;
		c.kills = kills;
		c.activeMs = activeMs;
		c.slayerXp = slayerXp;
		c.lootGp = lootGp;
		c.lastSeen = lastSeen;
		c.foodPerKill = foodPerKill;
		c.dosesPerKill = dosesPerKill;
		c.prayerPerKill = prayerPerKill;
		c.points = points;
		c.pointSamples = pointSamples;
		c.skips = skips;
		c.blocks = blocks;
		c.pointsSpent = pointsSpent;
		c.bestKph = bestKph;
		c.bestIdleMs = bestIdleMs;
		c.bestAwayMs = bestAwayMs;
		c.bestMs = bestMs;
		c.cannonKph = cannonKph;
		c.plainKph = plainKph;
		c.superiors = superiors;
		c.unreadable = unreadable;
		c.monsterKills = monsterKills == null ? new java.util.LinkedHashMap<>() : new java.util.LinkedHashMap<>(monsterKills);
		c.drops = new java.util.LinkedHashMap<>();
		if (drops != null)
		{
			for (java.util.Map.Entry<String, long[]> e : drops.entrySet())
			{
				c.drops.put(e.getKey(), e.getValue() == null ? new long[3] : e.getValue().clone());
			}
		}
		c.spots = new java.util.LinkedHashMap<>();
		if (spots != null)
		{
			for (java.util.Map.Entry<String, SpotStats> e : spots.entrySet())
			{
				SpotStats x = new SpotStats();
				x.kills = e.getValue().kills;
				x.activeMs = e.getValue().activeMs;
				x.xp = e.getValue().xp;
				x.loot = e.getValue().loot;
				c.spots.put(e.getKey(), x);
			}
		}
		return c;
	}
}

package com.slayersuite.readiness;

import lombok.Value;

/** One unsatisfied readiness rule. */
@Value
public class Missing
{
	String label;
	String why;
	boolean required;
	/** The item was seen in the bank the last time it was open. */
	boolean inBank;
}

package com.slayersuite.readiness;

import com.slayersuite.SlayerSuiteConfig;
import com.slayersuite.advisor.AccountState;
import com.slayersuite.advisor.Advisor;
import com.slayersuite.advisor.ScoredLocation;
import com.slayersuite.advisor.TravelData;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.util.TreeSet;
import java.util.regex.Pattern;
import com.slayersuite.data.LocationRecord;
import com.slayersuite.data.ItemGroups;
import com.slayersuite.data.ItemNames;
import com.slayersuite.data.ItemRule;
import com.slayersuite.data.SlayerDataset;
import com.slayersuite.data.TaskRecord;
import com.slayersuite.task.TaskChanged;
import com.slayersuite.task.TaskTracker;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Provider;
import javax.inject.Singleton;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.game.ItemManager;

/**
 * Scans worn equipment, the inventory and (while open) the bank, and compares
 * them with the task record's item rules. Read-only: it never moves an item.
 */
@Singleton
public class ReadinessChecker
{
	private final Client client;
	/** Prayer points this task has cost per kill in your history, pushed by the trip tracker each tick (no injection cycle). */
	private volatile double prayerPerKill;
	private final ItemManager itemManager;
	private final SlayerDataset dataset;
	private final TaskTracker tracker;
	private final SlayerSuiteConfig config;
	private final Provider<Advisor> advisor;
	private final Provider<AccountState> account;
	private final TravelData travel;
	private final ConfigManager configManager;
	private final Gson gson;

	private static final String OWNED_KEY = "ownedItems";
	private static final Pattern DEAD_SUFFIX = Pattern.compile("\\((inert|uncharged|empty|broken|0)\\)");
	/** Normalised names of teleport and task items seen in the bank in any session, saved on the profile. */
	private final Set<String> remembered = new TreeSet<>();
	private boolean rememberedLoaded;
	private Set<String> relevant;

	private final Map<Integer, String> nameCache = new HashMap<>();
	private final Map<Integer, Boolean> edibleCache = new HashMap<>();

	private final Set<String> held = new HashSet<>();
	private final Set<String> bankNames = new HashSet<>();
	@Getter
	private int foodCount;
	@Getter
	private long bankSeenAt;
	@Getter
	private boolean bankOpen;
	@Getter
	private List<Missing> missing = Collections.emptyList();
	private boolean dirty = true;

	@Inject
	public ReadinessChecker(Client client, ItemManager itemManager, SlayerDataset dataset, TaskTracker tracker, SlayerSuiteConfig config,
		Provider<Advisor> advisor, Provider<AccountState> account, TravelData travel, ConfigManager configManager, Gson gson)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.dataset = dataset;
		this.tracker = tracker;
		this.config = config;
		this.advisor = advisor;
		this.account = account;
		this.travel = travel;
		this.configManager = configManager;
		this.gson = gson;
	}

	/** Names worth remembering across sessions: every teleport item in travel.json and every item group member. */
	private Set<String> relevantNames()
	{
		if (relevant == null)
		{
			Set<String> r = new HashSet<>();
			for (String n : travel.itemNames())
			{
				r.add(ItemNames.normalize(n));
			}
			for (String key : dataset.getItems().keys())
			{
				ItemGroups.Group g = dataset.getItems().get(key);
				if (g != null)
				{
					for (String n : g.getNames())
					{
						r.add(ItemNames.normalize(n));
					}
				}
			}
			for (String n : new String[]{"Teleport to house", "Construction cape", "Max cape"})
			{
				r.add(ItemNames.normalize(n));
			}
			relevant = r;
		}
		return relevant;
	}

	private void loadRemembered()
	{
		remembered.clear();
		try
		{
			String json = configManager.getRSProfileConfiguration(SlayerSuiteConfig.GROUP, OWNED_KEY);
			if (json != null && !json.isEmpty())
			{
				List<String> list = gson.fromJson(json, new TypeToken<List<String>>()
				{
				}.getType());
				if (list != null)
				{
					remembered.addAll(list);
				}
			}
		}
		catch (RuntimeException e)
		{
			// nothing remembered
		}
		rememberedLoaded = true;
	}

	private void rememberBank()
	{
		if (configManager.getRSProfileKey() == null)
		{
			return;
		}
		if (!rememberedLoaded)
		{
			loadRemembered();
		}
		Set<String> rel = relevantNames();
		boolean changed = false;
		for (String n : bankNames)
		{
			if (matchesRelevant(n, rel) && remembered.add(n))
			{
				changed = true;
			}
		}
		for (String n : held)
		{
			if (matchesRelevant(n, rel) && remembered.add(n))
			{
				changed = true;
			}
		}
		if (changed)
		{
			try
			{
				configManager.setRSProfileConfiguration(SlayerSuiteConfig.GROUP, OWNED_KEY, gson.toJson(new ArrayList<>(remembered)));
			}
			catch (RuntimeException e)
			{
				// ignore
			}
		}
	}

	private static boolean matchesRelevant(String normalised, Set<String> rel)
	{
		if (rel.contains(normalised))
		{
			return true;
		}
		for (String r : rel)
		{
			if (normalised.startsWith(r + " ") || normalised.startsWith(r + "("))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * You own the item: carried or worn now, seen in the bank this session, or seen in any earlier
	 * session. Charge variants count ("Slayer ring (eternal)"), dead ones do not ("(inert)", "(uncharged)").
	 */
	public boolean owns(String itemName)
	{
		if (!rememberedLoaded && client.getGameState() == GameState.LOGGED_IN)
		{
			loadRemembered();
		}
		String want = ItemNames.normalize(itemName);
		if (want.isEmpty())
		{
			return false;
		}
		for (Set<String> pool : java.util.Arrays.asList(held, bankNames, remembered))
		{
			if (pool.contains(want))
			{
				return true;
			}
			for (String have : pool)
			{
				if ((have.startsWith(want + " ") || have.startsWith(want + "(")) && !DEAD_SUFFIX.matcher(have).find())
				{
					return true;
				}
			}
		}
		return false;
	}

	public boolean anythingRemembered()
	{
		return bankSeenAt > 0 || !remembered.isEmpty();
	}

	public void setPrayerPerKill(double perKill)
	{
		prayerPerKill = perKill;
	}

	public void reset()
	{
		held.clear();
		bankNames.clear();
		foodCount = 0;
		bankOpen = false;
		missing = Collections.emptyList();
		dirty = true;
	}

	public boolean hasGroup(String groupKey)
	{
		return dataset.getItems().satisfied(groupKey, held);
	}

	public boolean holds(String itemName)
	{
		return held.contains(ItemNames.normalize(itemName));
	}

	public Set<String> heldNames()
	{
		return Collections.unmodifiableSet(held);
	}

	/** Normalised names of everything seen in the bank the last time it was open. */
	public Set<String> bankNames()
	{
		return Collections.unmodifiableSet(bankNames);
	}

	public List<Missing> requiredMissing()
	{
		List<Missing> out = new ArrayList<>();
		for (Missing m : missing)
		{
			if (m.isRequired())
			{
				out.add(m);
			}
		}
		return out;
	}

	public boolean isReady()
	{
		return requiredMissing().isEmpty();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		if (e.getGameState() == GameState.LOGGED_IN)
		{
			dirty = true;
		}
		else if (e.getGameState() == GameState.LOGIN_SCREEN)
		{
			bankOpen = false;
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged e)
	{
		int id = e.getContainerId();
		if (id == InventoryID.INV || id == InventoryID.WORN)
		{
			rescanHeld();
			dirty = true;
		}
		else if (id == InventoryID.BANK)
		{
			rescanBank(e.getItemContainer());
			dirty = true;
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded e)
	{
		if (e.getGroupId() == InterfaceID.BANKMAIN)
		{
			bankOpen = true;
			ItemContainer bank = client.getItemContainer(InventoryID.BANK);
			if (bank != null)
			{
				rescanBank(bank);
			}
			rescanHeld();
			dirty = true;
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed e)
	{
		if (e.getGroupId() == InterfaceID.BANKMAIN)
		{
			bankOpen = false;
			dirty = true;
		}
	}

	@Subscribe
	public void onTaskChanged(TaskChanged e)
	{
		dirty = true;
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (dirty)
		{
			if (held.isEmpty() && foodCount == 0)
			{
				rescanHeld();
			}
			recompute();
			dirty = false;
		}
	}

	private void rescanHeld()
	{
		held.clear();
		foodCount = 0;
		scanInto(client.getItemContainer(InventoryID.INV), held, true);
		scanInto(client.getItemContainer(InventoryID.WORN), held, false);
	}

	private void rescanBank(ItemContainer bank)
	{
		bankNames.clear();
		scanInto(bank, bankNames, false);
		bankSeenAt = System.currentTimeMillis();
		rememberBank();
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged e)
	{
		rememberedLoaded = false;
	}

	private void scanInto(ItemContainer container, Set<String> names, boolean countFood)
	{
		if (container == null)
		{
			return;
		}
		for (Item item : container.getItems())
		{
			if (item == null || item.getId() <= 0)
			{
				continue;
			}
			int id = item.getId();
			String name = nameCache.get(id);
			Boolean edible = edibleCache.get(id);
			if (name == null || edible == null)
			{
				ItemComposition comp = itemManager.getItemComposition(id);
				name = ItemNames.normalize(comp.getName());
				edible = hasAction(comp, "Eat");
				nameCache.put(id, name);
				edibleCache.put(id, edible);
			}
			names.add(name);
			if (countFood && edible)
			{
				foodCount += Math.max(1, item.getQuantity());
			}
		}
	}

	/** You carry a cannon: say when it cannot be used where you are, or where you are going. */
	private void cannonWarnings(TaskRecord rec, List<Missing> out)
	{
		try
		{
			if (!account.get().questFinished("DWARF_CANNON") && client.getGameState() == net.runelite.api.GameState.LOGGED_IN)
			{
				out.add(new Missing("Dwarf Cannon quest", "you cannot set a cannon up before finishing it", false, false));
			}
		}
		catch (RuntimeException e)
		{
			// quest state unavailable; say nothing
		}
		boolean immune = rec != null && rec.cannonImmune();
		LocationRecord here = tracker.getCurrentLocation();
		if (here != null)
		{
			if (immune)
			{
				out.add(new Missing("Cannon is useless here", "the monsters are immune to cannon damage", false, false));
			}
			else if (Boolean.FALSE.equals(here.getCannon()))
			{
				out.add(new Missing("Cannon cannot be placed here", here.getName() + " does not allow one", false, false));
			}
			return;
		}
		if (bankOpen)
		{
			Advisor a = advisor.get();
			LocationRecord dest = a.getDestination();
			if (dest == null)
			{
				ScoredLocation best = a.best();
				dest = best == null ? null : best.getLocation();
			}
			if (dest != null)
			{
				if (immune)
				{
					out.add(new Missing("Leave the cannon", "the task monsters are immune to it", false, false));
				}
				else if (Boolean.FALSE.equals(dest.getCannon()))
				{
					out.add(new Missing("Leave the cannon", dest.getName() + " does not allow one", false, false));
				}
			}
		}
	}

	private static boolean hasAction(ItemComposition comp, String action)
	{
		String[] actions = comp.getInventoryActions();
		if (actions == null)
		{
			return false;
		}
		for (String a : actions)
		{
			if (action.equalsIgnoreCase(a))
			{
				return true;
			}
		}
		return false;
	}

	private void recompute()
	{
		TaskRecord rec = tracker.getRecord();
		if (!tracker.hasTask())
		{
			missing = Collections.emptyList();
			return;
		}
		ItemGroups items = dataset.getItems();
		List<Missing> out = new ArrayList<>();
		boolean hasPoisonRule = false;
		if (rec != null)
		{
			for (ItemRule rule : rec.allRules())
			{
				List<String> groups = rule.getAnyOf();
				if (groups == null || groups.isEmpty())
				{
					continue;
				}
				if (groups.contains("antipoison") || groups.contains("antivenom"))
				{
					hasPoisonRule = true;
				}
				if (!rule.isRequired() && !config.readinessRecommended())
				{
					continue;
				}
				if (!items.anySatisfied(groups, held))
				{
					out.add(new Missing(items.describe(groups), rule.getWhy(), rule.isRequired(), items.anySatisfied(groups, bankNames)));
				}
			}
			if (!hasPoisonRule && config.readinessRecommended() && rec.anyPoisonous() && !items.satisfied("antipoison", held))
			{
				String key = rec.anyVenomous() ? "antivenom" : "antipoison";
				out.add(new Missing(items.label(key), rec.anyVenomous() ? "the monsters inflict venom" : "the monsters poison", false, items.satisfied(key, bankNames)));
			}
			if (config.readinessPrayer() && prayerPerKill > 0.2 && !items.satisfied("prayer_restore", held))
			{
				out.add(new Missing(items.label("prayer_restore"), "this task has cost you prayer points before", false, items.satisfied("prayer_restore", bankNames)));
			}
		}
		if (config.readinessFood() && foodCount == 0)
		{
			out.add(new Missing("Food", "nothing edible in your inventory", false, true));
		}
		if (config.readinessCannon() && items.satisfied("cannon_parts", held))
		{
			if (!items.satisfied("cannonballs", held))
			{
				out.add(new Missing(items.label("cannonballs"), "you carry a cannon", true, items.satisfied("cannonballs", bankNames)));
			}
			cannonWarnings(rec, out);
		}
		missing = out;
	}
}

package com.slayersuite.readiness;

import com.slayersuite.SlayerSuiteConfig;
import com.slayersuite.data.ItemGroups;
import com.slayersuite.data.ItemRule;
import com.slayersuite.data.SlayerDataset;
import com.slayersuite.data.TaskRecord;
import com.slayersuite.task.TaskTracker;
import java.awt.Color;
import com.slayersuite.ui.Palette;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/** The "you have everything for this task" list, shown while the bank is open. */
public class ReadinessOverlay extends OverlayPanel
{
	private static final Color OK = Palette.OK;
	private static final Color MISSING = Palette.BAD;
	private static final Color RECOMMENDED = Palette.WARN;
	private static final Color DIM = Palette.DIM;

	private final ReadinessChecker checker;
	private final TaskTracker tracker;
	private final SlayerDataset dataset;
	private final SlayerSuiteConfig config;
	private final com.slayersuite.task.SlayerMode mode;
	private final com.slayersuite.history.TaskHistory history;
	private final com.slayersuite.trip.TripTracker trip;
	private final net.runelite.api.Client client;

	@Inject
	public ReadinessOverlay(ReadinessChecker checker, TaskTracker tracker, SlayerDataset dataset, SlayerSuiteConfig config, com.slayersuite.task.SlayerMode mode,
		com.slayersuite.history.TaskHistory history, com.slayersuite.trip.TripTracker trip, net.runelite.api.Client client)
	{
		this.history = history;
		this.trip = trip;
		this.client = client;
		this.mode = mode;
		this.checker = checker;
		this.tracker = tracker;
		this.dataset = dataset;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		setPriority(PRIORITY_HIGH);
		panelComponent.setPreferredSize(new Dimension(230, 0));
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.readinessOverlay() || !checker.isBankOpen() || !tracker.hasTask() || (!mode.active() && !mode.helmWithYou()))
		{
			return null;
		}
		TaskRecord rec = tracker.getRecord();
		String title = rec != null ? rec.title() : tracker.getTaskName();
		boolean ready = checker.isReady();
		panelComponent.getChildren().add(TitleComponent.builder()
			.text((ready ? "Ready: " : "Not ready: ") + title)
			.color(ready ? OK : MISSING)
			.build());

		if (rec == null)
		{
			panelComponent.getChildren().add(LineComponent.builder().left("No dataset entry for this task yet.").leftColor(DIM).build());
		}
		else
		{
			ItemGroups items = dataset.getItems();
			for (ItemRule rule : rec.allRules())
			{
				if (!rule.isRequired() || rule.getAnyOf() == null || !items.anySatisfied(rule.getAnyOf(), checker.heldNames()))
				{
					continue;
				}
				String heldName = items.heldName(rule.getAnyOf(), checker.heldNames());
				panelComponent.getChildren().add(LineComponent.builder()
					.left(heldName == null ? items.describe(rule.getAnyOf()) : heldName)
					.leftColor(OK)
					.right("ok")
					.rightColor(OK)
					.build());
			}
		}
		for (Missing m : checker.getMissing())
		{
			Color c = m.isRequired() ? MISSING : RECOMMENDED;
			panelComponent.getChildren().add(LineComponent.builder()
				.left((m.isRequired() ? "Missing: " : "Bring: ") + m.getLabel())
				.leftColor(c)
				.right(m.isInBank() ? "in bank" : "")
				.rightColor(DIM)
				.build());
			if (m.getWhy() != null && !m.getWhy().isEmpty())
			{
				panelComponent.getChildren().add(LineComponent.builder().left("  " + m.getWhy()).leftColor(DIM).build());
			}
		}
		packingList();
		return super.render(g);
	}

	/** What to take for the kills left, from your own rates on this task. */
	private void packingList()
	{
		int remaining = tracker.getRemaining();
		com.slayersuite.history.TaskStats stats = history.getCurrent();
		if (remaining <= 0)
		{
			return;
		}
		boolean session = trip.getSessionKills() >= 5;
		double fpk = session ? trip.foodPerKill() : stats == null ? 0 : stats.getFoodPerKill();
		double ppk = session ? trip.prayerPerKill() : stats == null ? 0 : stats.getPrayerPerKill();
		double dpk = session ? trip.dosesPerKill() : stats == null ? 0 : stats.getDosesPerKill();
		double antifireMin = 0;
		if (trip.taskNeedsAntifire() && tracker.effectiveKph() > 0)
		{
			antifireMin = remaining / tracker.effectiveKph() * 60.0;
		}
		if (fpk <= 0 && ppk <= 0 && dpk <= 0 && antifireMin <= 0)
		{
			panelComponent.getChildren().add(LineComponent.builder().left("Pack: no rates for this task yet").leftColor(DIM).build());
			return;
		}
		int level = client.getGameState() == net.runelite.api.GameState.LOGGED_IN ? client.getRealSkillLevel(net.runelite.api.Skill.PRAYER) : 1;
		com.slayersuite.trip.PackingMath.Pack pack = com.slayersuite.trip.PackingMath.pack(remaining, fpk, ppk, dpk,
			com.slayersuite.trip.TripTracker.prayerPerDose("prayer potion", level), antifireMin, 6, 0.15);
		panelComponent.getChildren().add(LineComponent.builder()
			.left("Pack for " + remaining + " kills").leftColor(Color.WHITE)
			.right(pack.getTrips() <= 1 ? "one trip" : pack.getTrips() + " trips").rightColor(pack.getTrips() <= 1 ? OK : RECOMMENDED).build());
		if (pack.getFood() > 0)
		{
			panelComponent.getChildren().add(LineComponent.builder().left("  Food").leftColor(DIM).right(pack.getFood() + " pieces").rightColor(Color.WHITE).build());
		}
		if (pack.getPrayerDoses() > 0)
		{
			panelComponent.getChildren().add(LineComponent.builder().left("  Prayer").leftColor(DIM).right(pack.getPrayerDoses() + " doses (" + pack.getPrayerPotions() + " potions)").rightColor(Color.WHITE).build());
		}
		if (pack.getOtherDoses() > 0)
		{
			panelComponent.getChildren().add(LineComponent.builder().left("  Other potions").leftColor(DIM).right(pack.getOtherDoses() + " doses (" + pack.getOtherPotions() + ")").rightColor(Color.WHITE).build());
		}
		if (pack.getAntifireDoses() > 0)
		{
			panelComponent.getChildren().add(LineComponent.builder().left("  Antifire").leftColor(DIM).right(pack.getAntifireDoses() + " doses").rightColor(Color.WHITE).build());
		}
		panelComponent.getChildren().add(LineComponent.builder().left("  15% spare, from " + (session ? "this session" : "your history")).leftColor(DIM).build());
	}
}

package com.slayersuite.route;

import java.util.Arrays;

/** An int to int map with open addressing, for the search's hundreds of thousands of tiles without boxing. */
final class IntIntMap
{
	private static final int EMPTY = Integer.MIN_VALUE;
	private int[] keys;
	private int[] values;
	private int size;
	private int limit;

	IntIntMap(int expected)
	{
		int cap = Integer.highestOneBit(Math.max(16, expected * 2) - 1) << 1;
		keys = new int[cap];
		values = new int[cap];
		Arrays.fill(keys, EMPTY);
		limit = cap / 2;
	}

	private static int mix(int k)
	{
		k *= 0x9E3779B1;
		return k ^ (k >>> 16);
	}

	int get(int key, int absent)
	{
		int mask = keys.length - 1;
		int i = mix(key) & mask;
		while (true)
		{
			int k = keys[i];
			if (k == key)
			{
				return values[i];
			}
			if (k == EMPTY)
			{
				return absent;
			}
			i = (i + 1) & mask;
		}
	}

	void put(int key, int value)
	{
		if (size >= limit)
		{
			grow();
		}
		int mask = keys.length - 1;
		int i = mix(key) & mask;
		while (true)
		{
			int k = keys[i];
			if (k == key)
			{
				values[i] = value;
				return;
			}
			if (k == EMPTY)
			{
				keys[i] = key;
				values[i] = value;
				size++;
				return;
			}
			i = (i + 1) & mask;
		}
	}

	int size()
	{
		return size;
	}

	private void grow()
	{
		int[] oldKeys = keys;
		int[] oldValues = values;
		keys = new int[oldKeys.length * 2];
		values = new int[oldKeys.length * 2];
		Arrays.fill(keys, EMPTY);
		limit = keys.length / 2;
		size = 0;
		for (int i = 0; i < oldKeys.length; i++)
		{
			if (oldKeys[i] != EMPTY)
			{
				put(oldKeys[i], oldValues[i]);
			}
		}
	}
}

package com.slayersuite.route;

import net.runelite.api.coords.WorldPoint;

/** A world tile packed into one int: 15 bits of x, 15 bits of y, 2 bits of plane, the layout the routing data uses. */
public final class Packed
{
	private Packed()
	{
	}

	public static int of(int x, int y, int plane)
	{
		return (x & 0x7FFF) | ((y & 0x7FFF) << 15) | ((plane & 3) << 30);
	}

	public static int of(WorldPoint wp)
	{
		return of(wp.getX(), wp.getY(), wp.getPlane());
	}

	public static int x(int p)
	{
		return p & 0x7FFF;
	}

	public static int y(int p)
	{
		return (p >>> 15) & 0x7FFF;
	}

	public static int plane(int p)
	{
		return (p >>> 30) & 3;
	}

	public static WorldPoint toWorld(int p)
	{
		return new WorldPoint(x(p), y(p), plane(p));
	}

	/** Tiles between two points on the ground, the way the game counts a diagonal as one step. */
	public static int chebyshev(int a, int b)
	{
		return Math.max(Math.abs(x(a) - x(b)), Math.abs(y(a) - y(b)));
	}
}

package com.slayersuite.route;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Chooses between walking from where you stand and teleporting first: the route is searched from
 * your tile and from every landing you can reach, and the plan with the fewest ticks wins. A spot
 * within a short walk is always walked to.
 */
public final class Planner
{
	/** Walks this short are never worth a teleport: a charge is a charge, and the chevrons are the point. */
	static final int NEAR_TILES = 100;
	/** A teleport or ride must save at least this many ticks, and this share of the walk, to replace it. */
	static final int MARGIN_TICKS = 25;
	static final double MARGIN_SHARE = 0.7;
	/** Tiles a search to or from a network stop may look at; stops are close to roads, so this is plenty. */
	static final int NETWORK_EXPANSIONS = 120_000;

	/** Where a teleport you own puts you, and what it costs to use. */
	public static final class Landing
	{
		public final String label;
		public final String status;
		public final int tile;
		/** Ticks to use it, including any detour it implies (a bank visit, a spellbook swap). */
		public final int ticks;

		public Landing(String label, String status, int tile, int ticks)
		{
			this.label = label;
			this.status = status;
			this.tile = tile;
			this.ticks = ticks;
		}
	}

	public static final class Plan
	{
		/** The teleport to use first, or null to walk from where you are. */
		public final Landing teleport;
		/** From your tile, or from the landing. */
		public final Router.Route route;
		/** Where the plan was made from. */
		public final int start;
		public final int ticks;
		/** The plain walk from where you stand, when one reaches the spot; null otherwise. */
		public final Router.Route walk;

		Plan(Landing teleport, Router.Route route, int start, int ticks)
		{
			this(teleport, route, start, ticks, null);
		}

		Plan(Landing teleport, Router.Route route, int start, int ticks, Router.Route walk)
		{
			this.teleport = teleport;
			this.route = route;
			this.start = start;
			this.ticks = ticks;
			this.walk = walk;
		}

		/** Ticks the plain walk would take; -1 when there is none. */
		public int walkTicks()
		{
			return walk != null && walk.reached ? ticksFor(walk.cost) : -1;
		}

		public boolean reached()
		{
			return route != null && route.reached;
		}
	}

	private Planner()
	{
	}

	/** The n stops nearest a tile as the crow flies, dungeons folded onto the ground above them. */
	static List<Transport> nearest(List<Transport> stops, int tile, int n)
	{
		List<Transport> sorted = new ArrayList<>(stops);
		sorted.sort(Comparator.comparingInt(s -> Router.heuristic(s.origin, tile)));
		return sorted.size() > n ? new ArrayList<>(sorted.subList(0, n)) : sorted;
	}

	/** Ticks to cover a route: running covers two tiles a tick; transports already count their own ticks. */
	public static int ticksFor(int cost)
	{
		return (cost + 1) / 2;
	}

	public static Plan plan(WorldMap map, TransportTable table, Set<Transport> usable, int start, int goal, List<Landing> landings, boolean avoidWilderness, int maxExpansions, long budgetNanos)
	{
		return plan(map, table, usable, start, goal, landings, avoidWilderness, maxExpansions, budgetNanos, 200);
	}

	/**
	 * As above; walkUpTo is how long a walk is still searched for the chevrons when a teleport is
	 * quicker, so there is a line to follow from where you stand whenever one exists.
	 */
	public static Plan plan(WorldMap map, TransportTable table, Set<Transport> usable, int start, int goal, List<Landing> landings, boolean avoidWilderness, int maxExpansions, long budgetNanos, int walkUpTo)
	{
		// A short walk first: cheap, and it settles most cases.
		Router.Route near = Router.find(map, table, usable, start, goal, maxExpansions, System.nanoTime() + budgetNanos, avoidWilderness, NEAR_TILES + 1);
		if (near.reached && near.cost <= NEAR_TILES)
		{
			return new Plan(null, near, start, ticksFor(near.cost), near);
		}
		// Then the landings, nearest the spot first; once one plan exists, a later landing only
		// searches as far as it could still beat it, so a landing on the wrong continent fails fast.
		List<Landing> ordered = new ArrayList<>(landings);
		ordered.sort(Comparator.comparingInt(l -> Router.heuristic(l.tile, goal)));
		Plan best = null;
		for (Landing l : ordered)
		{
			int cap = best == null ? Integer.MAX_VALUE : 2 * (best.ticks - l.ticks) + 1;
			if (cap <= 0)
			{
				continue;
			}
			int from = map.isBlocked(l.tile) && !table.from(l.tile).isEmpty() ? l.tile : Router.walkableNear(map, l.tile);
			Router.Route r = Router.find(map, table, usable, from, goal, maxExpansions, System.nanoTime() + budgetNanos, avoidWilderness, cap);
			if (!r.reached)
			{
				continue;
			}
			int ticks = l.ticks + ticksFor(r.cost);
			if (best == null || ticks < best.ticks)
			{
				best = new Plan(l, r, start, ticks);
			}
		}
		// Rides: from a stop near you to a stop near the spot, for every network you can use. Each
		// search is small, pairs that cannot beat the best plan by straight line are skipped, and the
		// walk to a stop near you is searched once however many far stops it serves.
		for (Transport.Kind kind : table.networks())
		{
			List<Transport> usableStops = new ArrayList<>();
			for (Transport s : table.stops(kind))
			{
				if (usable.contains(s))
				{
					usableStops.add(s);
				}
			}
			if (usableStops.size() < 2)
			{
				continue;
			}
			List<Transport> nearMe = nearest(usableStops, start, 2);
			List<Transport> nearGoal = nearest(usableStops, goal, 2);
			Map<Transport, Router.Route> heads = new HashMap<>();
			for (Transport far : nearGoal)
			{
				int farCap = best == null ? Integer.MAX_VALUE : 2 * best.ticks + 1;
				int bound = ticksFor(Router.heuristic(start, nearMe.get(0).origin)) + kind.defaultDuration() + ticksFor(Router.heuristic(far.origin, goal));
				if (best != null && bound >= best.ticks)
				{
					continue;
				}
				Router.Route tail = Router.find(map, table, usable, far.origin, goal, NETWORK_EXPANSIONS, System.nanoTime() + budgetNanos, avoidWilderness, farCap);
				if (!tail.reached)
				{
					continue;
				}
				for (Transport stopNear : nearMe)
				{
					if (stopNear == far || Packed.chebyshev(stopNear.origin, far.origin) <= 5)
					{
						continue;
					}
					Transport ride = Transport.ride(stopNear, far);
					int cap = best == null ? Integer.MAX_VALUE : 2 * (best.ticks - ride.duration - ticksFor(tail.cost)) + 1;
					if (cap <= 0)
					{
						continue;
					}
					Router.Route head = heads.get(stopNear);
					if (head == null)
					{
						head = Router.find(map, table, usable, start, stopNear.origin, NETWORK_EXPANSIONS, System.nanoTime() + budgetNanos, avoidWilderness, cap);
						heads.put(stopNear, head);
					}
					if (!head.reached)
					{
						continue;
					}
					Router.Route whole = Router.join(head, ride, tail);
					int ticks = ticksFor(whole.cost);
					if (best == null || ticks < best.ticks)
					{
						best = new Plan(null, whole, start, ticks);
					}
				}
			}
		}
		// Finally the full walk, but only as far as it could still beat the best plan so far. (The
		// straight line is no lower bound here: a well or a cave can jump the route a long way.)
		// A teleport or ride only replaces a walk it beats clearly, so the walk is searched a little
		// beyond the point where it would tie.
		int cap = best == null ? Integer.MAX_VALUE : (int) Math.max(walkUpTo + 1, Math.min(Integer.MAX_VALUE, 2L * ((best.ticks + MARGIN_TICKS) / MARGIN_SHARE) + 1));
		int walkBudget = best == null ? maxExpansions : Math.min(maxExpansions, 400_000);
		Router.Route walk = Router.find(map, table, usable, start, goal, walkBudget, System.nanoTime() + budgetNanos, avoidWilderness, cap);
		if (walk.reached)
		{
			int walkTicks = ticksFor(walk.cost);
			boolean clearlyBetter = best != null && best.ticks + MARGIN_TICKS <= walkTicks && best.ticks <= walkTicks * MARGIN_SHARE;
			if (!clearlyBetter)
			{
				return new Plan(null, walk, start, walkTicks, walk);
			}
			return new Plan(best.teleport, best.route, start, best.ticks, walk);
		}
		return best != null ? best : new Plan(null, walk, start, Integer.MAX_VALUE);
	}
}

package com.slayersuite.route;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import javax.inject.Inject;
import javax.inject.Singleton;
import com.slayersuite.SlayerSuiteConfig;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.eventbus.Subscribe;

/**
 * Keeps a plan from you to the pinned spot: walk, or teleport first and walk from the landing.
 * The map and the transport tables load once on a background thread, searches run there too,
 * and each tick the route is trimmed to where you stand or the plan is remade when you have
 * left it. Which transports you may use is decided on the client thread from your levels,
 * quests and var values, and refreshed every minute.
 */
@Slf4j
@Singleton
public class RouteService
{
	private static final int MAX_EXPANSIONS = 1_500_000;
	private static final long SEARCH_BUDGET_NANOS = 4_000_000_000L;
	private static final long REQUEST_GAP_MS = 1_200L;
	private static final int OFF_ROUTE_TILES = 2;
	private static final int SNAPSHOT_EVERY_TICKS = 100;

	private final Client client;
	private final SlayerSuiteConfig config;
	private final ExecutorService executor = Executors.newSingleThreadExecutor(r ->
	{
		Thread t = new Thread(r, "slayer-suite-route");
		t.setDaemon(true);
		return t;
	});

	private volatile WorldMap map;
	private volatile TransportTable table;
	/** Transports learned before the tables were ready, applied once they are. */
	private final List<Transport> extra = Collections.synchronizedList(new ArrayList<>());
	private volatile boolean loadFailed;
	private volatile Set<Transport> usable = Collections.emptySet();
	private volatile Planner.Plan plan;
	private volatile Router.Route route;
	private volatile int from;
	private volatile boolean onRoute;
	/** True while the chevrons follow the plain walk although the plan names a quicker teleport. */
	private volatile boolean showingWalk;
	private volatile WorldPoint target;
	private volatile List<Planner.Landing> landings = Collections.emptyList();
	private Future<?> pending;
	private Future<?> estimating;
	private long lastRequestMs;
	private int tick;
	private int snapshotTick = -1;
	private volatile boolean fairyRings;
	private int lastTile = Integer.MIN_VALUE;
	/** The tick you logged in; the first snapshot after login is retaken once the game has sent your quest and var state. */
	private int loginTick = -1;

	@Inject
	public RouteService(Client client, SlayerSuiteConfig config)
	{
		this.client = client;
		this.config = config;
	}

	/** Starts loading the map; cheap to call again. */
	public void start()
	{
		if (map == null && !loadFailed)
		{
			executor.submit(() ->
			{
				try
				{
					long t0 = System.currentTimeMillis();
					WorldMap m = WorldMap.load();
					TransportTable t = TransportTable.load();
					synchronized (extra)
					{
						if (!extra.isEmpty())
						{
							t = t.withAdded(new ArrayList<>(extra));
						}
					}
					table = t;
					map = m;
					log.debug("Slayer Suite: routing data ready in {} ms ({} regions, {} transports)", System.currentTimeMillis() - t0, m.regionCount(), t.size());
				}
				catch (RuntimeException e)
				{
					loadFailed = true;
					log.warn("Slayer Suite: routing data could not be loaded", e);
				}
			});
		}
	}

	public void stop()
	{
		executor.shutdownNow();
		plan = null;
		route = null;
		target = null;
	}

	public boolean ready()
	{
		return map != null && table != null;
	}

	public WorldMap map()
	{
		return map;
	}

	public TransportTable table()
	{
		return table;
	}

	/** The stops of a network you may use, or none until the tables are loaded. */
	public List<Transport> stops(Transport.Kind kind)
	{
		TransportTable t = table;
		if (t == null)
		{
			return Collections.emptyList();
		}
		List<Transport> out = new ArrayList<>();
		for (Transport s : t.stops(kind))
		{
			if (usable.contains(s))
			{
				out.add(s);
			}
		}
		return out;
	}

	/** Whether you can use fairy rings (Fairytale II started with a staff, or the Lumbridge elite diary). Client thread. */
	public void setFairyRingsUsable(boolean usable)
	{
		if (usable != fairyRings)
		{
			fairyRings = usable;
			snapshotTick = -1;
		}
	}

	/** Adds transports found by using them; they need nothing and are usable at once. Client thread. */
	public void addTransports(List<Transport> found)
	{
		TransportTable t = table;
		if (t == null)
		{
			extra.addAll(found);
			return;
		}
		table = t.withAdded(found);
		Set<Transport> u = new HashSet<>(usable);
		u.addAll(found);
		usable = u;
		plan = null;
		route = null;
	}

	/** The spot to route to, or null for none, with the teleports that could start the trip. Client thread. */
	public void setTarget(WorldPoint wp, List<Planner.Landing> teleports)
	{
		WorldPoint old = target;
		List<Planner.Landing> l = teleports == null ? Collections.emptyList() : teleports;
		boolean sameSpot = wp == null ? old == null : wp.equals(old);
		boolean sameTeleports = l.size() == landings.size();
		for (int i = 0; sameTeleports && i < l.size(); i++)
		{
			sameTeleports = l.get(i).tile == landings.get(i).tile && l.get(i).ticks == landings.get(i).ticks;
		}
		if (sameSpot && sameTeleports)
		{
			return;
		}
		target = wp;
		landings = l;
		plan = null;
		route = null;
		from = 0;
		onRoute = false;
		showingWalk = false;
		if (wp != null)
		{
			request(true);
		}
	}

	public void setTarget(WorldPoint wp)
	{
		setTarget(wp, Collections.emptyList());
	}

	/** A spot to cost from where you stand: a key to report it under, its tile, and the teleports that could start the trip. */
	public static final class Target
	{
		public final String key;
		public final int tile;
		public final List<Planner.Landing> landings;

		public Target(String key, int tile, List<Planner.Landing> landings)
		{
			this.key = key;
			this.tile = tile;
			this.landings = landings == null ? Collections.emptyList() : landings;
		}
	}

	private static final int ESTIMATE_EXPANSIONS = 300_000;
	private static final long ESTIMATE_BUDGET_NANOS = 800_000_000L;
	/** The whole batch of estimates shares this much of the executor; the pin's own route must not wait behind them. */
	private static final long ESTIMATE_BATCH_NANOS = 1_500_000_000L;

	/**
	 * Costs each target from where you stand on the background thread, teleports and rides weighed
	 * like a real plan, and hands back ticks per key, -1 where nothing reaches. Client thread.
	 */
	public void estimate(List<Target> targets, java.util.function.Consumer<Map<String, Integer>> done)
	{
		if (!client.isClientThread())
		{
			return;
		}
		Player me = client.getLocalPlayer();
		if (me == null || targets.isEmpty() || !ready() || client.getGameState() != GameState.LOGGED_IN || inInstance())
		{
			return;
		}
		if (snapshotTick < 0 || tick - snapshotTick >= SNAPSHOT_EVERY_TICKS)
		{
			usable = computeUsable();
			snapshotTick = tick;
		}
		if (estimating != null && !estimating.isDone())
		{
			estimating.cancel(true);
		}
		final int start = Packed.of(me.getWorldLocation());
		final Set<Transport> allowed = usable;
		final WorldMap m = map;
		final TransportTable tt = table;
		final boolean keepOut = config.avoidWilderness();
		final List<Target> list = new ArrayList<>(targets);
		final long deadline = System.nanoTime() + ESTIMATE_BATCH_NANOS;
		estimating = executor.submit(() ->
		{
			Map<String, Integer> out = new HashMap<>();
			for (Target t : list)
			{
				if (Thread.currentThread().isInterrupted())
				{
					return;
				}
				long left = deadline - System.nanoTime();
				if (left <= 0)
				{
					out.put(t.key, -1);
					continue;
				}
				try
				{
					int goal = Router.walkableNear(m, t.tile);
					Planner.Plan made = Planner.plan(m, tt, allowed, start, goal, t.landings, keepOut, ESTIMATE_EXPANSIONS, Math.min(ESTIMATE_BUDGET_NANOS, left), 0);
					out.put(t.key, made != null && made.reached() ? made.ticks : -1);
				}
				catch (RuntimeException e)
				{
					out.put(t.key, -1);
				}
			}
			if (!Thread.currentThread().isInterrupted())
			{
				done.accept(out);
			}
		});
	}

	/** The current plan, or null while none is known. */
	public Planner.Plan plan()
	{
		return plan;
	}

	/** True while you stand on (or beside) the route; false before a teleport the plan asks for. */
	public boolean onRoute()
	{
		return onRoute;
	}

	/** True while the chevrons show the plain walk and the plan's teleport is only offered as quicker. */
	public boolean showingWalk()
	{
		return showingWalk;
	}

	public WorldPoint getTarget()
	{
		return target;
	}

	/** The current route, or null while none is known. */
	public Router.Route current()
	{
		return route;
	}

	/** Index of your tile on the route. */
	public int from()
	{
		return from;
	}

	/** Tiles still to walk; 0 when there is no route. */
	public int remainingTiles()
	{
		Router.Route r = route;
		return r == null ? 0 : Math.max(0, r.tiles.size() - 1 - from);
	}

	/** The transports still ahead, with their index on the route. */
	public List<Router.Step> remainingSteps()
	{
		Router.Route r = route;
		if (r == null)
		{
			return Collections.emptyList();
		}
		int f = from;
		List<Router.Step> out = new ArrayList<>();
		for (Router.Step s : r.steps)
		{
			if (s.index >= f)
			{
				out.add(s);
			}
		}
		return out;
	}

	/** The fairy ring code the route wants next: the first ring ride ahead, else a house ring landing's code; null when none. */
	public String nextFairyCode()
	{
		for (Router.Step s : remainingSteps())
		{
			if (s.transport.kind == Transport.Kind.FAIRY_RING && s.transport.display != null && s.transport.display.matches("[A-D][IJKL][PQRS]"))
			{
				return s.transport.display;
			}
		}
		Planner.Plan p = plan;
		if (p != null && p.teleport != null && p.teleport.label != null && !onRoute)
		{
			java.util.regex.Matcher m = java.util.regex.Pattern.compile("(?i)fairy ring to ([A-D][IJKL][PQRS])\\b").matcher(p.teleport.label);
			if (m.find())
			{
				return m.group(1).toUpperCase(java.util.Locale.ROOT);
			}
		}
		return null;
	}

	/** True when the route gets all the way to the target. */
	public boolean reached()
	{
		Router.Route r = route;
		return r != null && r.reached;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		if (e.getGameState() == GameState.LOGIN_SCREEN || e.getGameState() == GameState.HOPPING)
		{
			// the pin stays; the way there is searched again once you are back in the world
			plan = null;
			route = null;
			onRoute = false;
			lastTile = Integer.MIN_VALUE;
		}
		else if (e.getGameState() == GameState.LOGGED_IN)
		{
			loginTick = tick;
		}
	}

	private boolean inInstance()
	{
		WorldView wv = client.getTopLevelWorldView();
		return wv != null && wv.isInstance();
	}

	@Subscribe
	public void onGameTick(GameTick t)
	{
		tick++;
		if (target == null || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		if (!ready())
		{
			if (tick % 5 == 0)
			{
				start();
			}
			return;
		}
		Player me = client.getLocalPlayer();
		if (me == null)
		{
			return;
		}
		if (loginTick >= 0 && tick - loginTick == 8)
		{
			// quests and vars arrive a few ticks after login: take the snapshot again and plan afresh
			snapshotTick = -1;
			request(true);
			return;
		}
		if (inInstance())
		{
			// the map has no instances; the search over the loaded area stands in until you leave
			plan = null;
			route = null;
			onRoute = false;
			return;
		}
		int here = Packed.of(me.getWorldLocation());
		boolean jumped = lastTile != Integer.MIN_VALUE && (Packed.plane(here) != Packed.plane(lastTile) || Packed.chebyshev(here, lastTile) > 25);
		lastTile = here;
		Planner.Plan p = plan;
		Router.Route r = route;
		if (jumped && (r == null || r.indexOf(here) < 0))
		{
			// you teleported, rode or climbed somewhere the route did not expect: plan again from here now
			request(true);
			return;
		}
		if (p == null || r == null)
		{
			request(false);
			return;
		}
		int idx = r.indexOf(here);
		if (idx >= 0)
		{
			from = idx;
			onRoute = true;
			return;
		}
		// beside the route is still on it (a ride lands you next to its stop); further away means a new plan
		int nearest = Integer.MAX_VALUE;
		int nearestAt = -1;
		int plane = Packed.plane(here);
		for (int i = 0; i < r.tiles.size(); i++)
		{
			int tile = r.tiles.get(i);
			if (Packed.plane(tile) != plane)
			{
				continue;
			}
			int d = Packed.chebyshev(tile, here);
			if (d < nearest || (d == nearest && i > from))
			{
				nearest = d;
				nearestAt = i;
			}
		}
		if (nearest <= OFF_ROUTE_TILES)
		{
			from = nearestAt;
			onRoute = true;
			return;
		}
		onRoute = false;
		if (p.teleport != null && Packed.chebyshev(here, p.start) <= 25 && Packed.plane(here) == Packed.plane(p.start))
		{
			// still where the plan was made, waiting to teleport
			return;
		}
		request(false);
	}

	/** Searches from where you stand to the target on the background thread. Client thread. */
	private void request(boolean force)
	{
		WorldPoint to = target;
		Player me = client.getLocalPlayer();
		if (to == null || me == null || !ready())
		{
			return;
		}
		long now = System.currentTimeMillis();
		if (!force && (now - lastRequestMs < REQUEST_GAP_MS || (pending != null && !pending.isDone())))
		{
			return;
		}
		if (pending != null && !pending.isDone())
		{
			pending.cancel(true);
		}
		lastRequestMs = now;
		if (snapshotTick < 0 || tick - snapshotTick >= SNAPSHOT_EVERY_TICKS)
		{
			usable = computeUsable();
			snapshotTick = tick;
		}
		if (inInstance())
		{
			return;
		}
		final int start = Packed.of(me.getWorldLocation());
		final int goal = Router.walkableNear(map, Packed.of(to));
		final Set<Transport> allowed = usable;
		final WorldMap m = map;
		final TransportTable tt = table;
		final boolean keepOut = config.avoidWilderness();
		final int walkUpTo = Math.max(100, config.floorPathMaxDistance());
		final List<Planner.Landing> l = landings;
		pending = executor.submit(() ->
		{
			try
			{
				Planner.Plan made = Planner.plan(m, tt, allowed, start, goal, l, keepOut, MAX_EXPANSIONS, SEARCH_BUDGET_NANOS, walkUpTo);
				if (to.equals(target))
				{
					from = 0;
					// whenever a walk exists it is drawn, even when a teleport is quicker: the chevrons
					// are what people follow, and the card still names the teleport
					boolean walkShown = made.teleport != null && made.walk != null && made.walk.reached;
					showingWalk = walkShown;
					onRoute = made.teleport == null || walkShown;
					route = walkShown ? made.walk : made.route;
					plan = made;
				}
			}
			catch (RuntimeException e)
			{
				log.debug("Slayer Suite: route search failed", e);
			}
		});
	}

	/** The transports whose levels, quests and var conditions you meet. Client thread. */
	private Set<Transport> computeUsable()
	{
		TransportTable tt = table;
		if (tt == null)
		{
			return Collections.emptySet();
		}
		Map<Quest, Boolean> done = new HashMap<>();
		Set<Transport> out = new HashSet<>(tt.size());
		for (Transport t : tt.all())
		{
			if (t.needsItems || !skillsMet(t) || !questsMet(t, done) || !varsMet(t))
			{
				continue;
			}
			if (t.kind == Transport.Kind.FAIRY_RING && !fairyRings)
			{
				continue;
			}
			out.add(t);
		}
		return out;
	}

	private boolean skillsMet(Transport t)
	{
		for (Map.Entry<Skill, Integer> e : t.skills.entrySet())
		{
			if (client.getRealSkillLevel(e.getKey()) < e.getValue())
			{
				return false;
			}
		}
		return true;
	}

	private boolean questsMet(Transport t, Map<Quest, Boolean> done)
	{
		for (Quest q : t.quests)
		{
			Boolean finished = done.get(q);
			if (finished == null)
			{
				try
				{
					finished = q.getState(client) == QuestState.FINISHED;
				}
				catch (RuntimeException e)
				{
					finished = false;
				}
				done.put(q, finished);
			}
			if (!finished)
			{
				return false;
			}
		}
		return true;
	}

	private boolean varsMet(Transport t)
	{
		for (Transport.VarCheck c : t.varbits)
		{
			if (!c.holds(client.getVarbitValue(c.id)))
			{
				return false;
			}
		}
		for (Transport.VarCheck c : t.varplayers)
		{
			if (!c.holds(client.getVarpValue(c.id)))
			{
				return false;
			}
		}
		return true;
	}
}

package com.slayersuite.route;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Finds a way from one tile to another over the world map, stepping tile to tile and using any
 * transport you are allowed. A* with the straight-line tile distance as its guide. When the
 * target cannot be reached within the budget, the route runs to the tile that got nearest.
 */
public final class Router
{
	/** A transport used on the route, at the given index of its tiles. */
	public static final class Step
	{
		public final int index;
		public final Transport transport;

		Step(int index, Transport transport)
		{
			this.index = index;
			this.transport = transport;
		}
	}

	public static final class Route
	{
		/** Packed tiles from the start to the end, inclusive. */
		public final List<Integer> tiles;
		public final List<Step> steps;
		public final boolean reached;
		public final int cost;
		private final IntIntMap index;

		Route(List<Integer> tiles, List<Step> steps, boolean reached, int cost)
		{
			this.tiles = Collections.unmodifiableList(tiles);
			this.steps = Collections.unmodifiableList(steps);
			this.reached = reached;
			this.cost = cost;
			index = new IntIntMap(tiles.size());
			for (int i = 0; i < tiles.size(); i++)
			{
				index.put(tiles.get(i), i);
			}
		}

		/** Where a tile sits on the route, or -1. */
		public int indexOf(int packed)
		{
			return index.get(packed, -1);
		}

		public int end()
		{
			return tiles.get(tiles.size() - 1);
		}
	}

	private Router()
	{
	}

	/**
	 * @param usable the transports whose requirements you meet; others are ignored
	 * @param maxExpansions tiles to look at before giving up on reaching the target
	 * @param deadlineNanos System.nanoTime() after which the search stops and returns its best
	 */
	public static Route find(WorldMap map, TransportTable transports, Set<Transport> usable, int start, int target, int maxExpansions, long deadlineNanos)
	{
		return find(map, transports, usable, start, target, maxExpansions, deadlineNanos, false);
	}

	/** As above; with avoidWilderness the route never sets foot in the Wilderness, on the surface or below it. */
	public static Route find(WorldMap map, TransportTable transports, Set<Transport> usable, int start, int target, int maxExpansions, long deadlineNanos, boolean avoidWilderness)
	{
		return find(map, transports, usable, start, target, maxExpansions, deadlineNanos, avoidWilderness, Integer.MAX_VALUE);
	}

	/** As above; a route costing more than maxCost is not worth finding, so the search stops growing past it. */
	public static Route find(WorldMap map, TransportTable transports, Set<Transport> usable, int start, int target, int maxExpansions, long deadlineNanos, boolean avoidWilderness, int maxCost)
	{
		IntIntMap g = new IntIntMap(1 << 16);
		IntIntMap parent = new IntIntMap(1 << 16);
		Map<Integer, Transport> via = new HashMap<>();
		IntHeap open = new IntHeap(1 << 14);
		g.put(start, 0);
		open.push(heuristic(start, target), start);
		int best = start;
		int bestH = heuristic(start, target);
		boolean reached = false;
		int expanded = 0;
		while (!open.isEmpty())
		{
			int f = open.peekKey();
			int node = open.pop();
			int gn = g.get(node, Integer.MAX_VALUE);
			if (f > gn + heuristic(node, target))
			{
				continue;
			}
			if (node == target)
			{
				reached = true;
				best = node;
				break;
			}
			if (++expanded > maxExpansions || (expanded & 1023) == 0 && (System.nanoTime() > deadlineNanos || Thread.currentThread().isInterrupted()))
			{
				break;
			}
			if (gn >= maxCost)
			{
				continue;
			}
			int h = heuristic(node, target);
			if (h < bestH)
			{
				bestH = h;
				best = node;
			}
			for (int nb : map.neighbours(node))
			{
				if (avoidWilderness && inWilderness(nb))
				{
					continue;
				}
				int ng = gn + 1;
				if (ng < g.get(nb, Integer.MAX_VALUE))
				{
					g.put(nb, ng);
					parent.put(nb, node);
					via.remove(nb);
					open.push(ng + heuristic(nb, target), nb);
				}
			}
			// a stop that is solid in the map (a fairy ring, a tree) is stepped onto from beside it
			int nx = Packed.x(node);
			int ny = Packed.y(node);
			int nz = Packed.plane(node);
			for (int dx = -1; dx <= 1; dx++)
			{
				for (int dy = -1; dy <= 1; dy++)
				{
					if (dx == 0 && dy == 0)
					{
						continue;
					}
					int adj = Packed.of(nx + dx, ny + dy, nz);
					if (!map.isBlocked(adj) || (!transports.isStop(adj) && transports.from(adj).isEmpty()) || (avoidWilderness && inWilderness(adj)))
					{
						continue;
					}
					int ng = gn + 1;
					if (ng < g.get(adj, Integer.MAX_VALUE))
					{
						g.put(adj, ng);
						parent.put(adj, node);
						via.remove(adj);
						open.push(ng + heuristic(adj, target), adj);
					}
				}
			}
			for (Transport t : transports.from(node))
			{
				if (!usable.contains(t) || (avoidWilderness && inWilderness(t.destination)))
				{
					continue;
				}
				int ng = gn + t.duration;
				if (ng < g.get(t.destination, Integer.MAX_VALUE))
				{
					g.put(t.destination, ng);
					parent.put(t.destination, node);
					via.put(t.destination, t);
					open.push(ng + heuristic(t.destination, target), t.destination);
				}
			}
		}
		List<Integer> tiles = new ArrayList<>();
		List<Step> steps = new ArrayList<>();
		for (int at = best; ; at = parent.get(at, Integer.MIN_VALUE))
		{
			tiles.add(at);
			if (at == start || parent.get(at, Integer.MIN_VALUE) == Integer.MIN_VALUE)
			{
				break;
			}
		}
		Collections.reverse(tiles);
		for (int i = 1; i < tiles.size(); i++)
		{
			Transport t = via.get(tiles.get(i));
			if (t != null && t.origin == tiles.get(i - 1))
			{
				steps.add(new Step(i - 1, t));
			}
		}
		return new Route(tiles, steps, reached, g.get(best, 0));
	}

	/** One route: the head, then a ride at its last tile, then the tail. */
	static Route join(Route head, Transport ride, Route tail)
	{
		List<Integer> tiles = new ArrayList<>(head.tiles.size() + tail.tiles.size());
		tiles.addAll(head.tiles);
		tiles.addAll(tail.tiles);
		List<Step> steps = new ArrayList<>(head.steps);
		steps.add(new Step(head.tiles.size() - 1, ride));
		for (Step s : tail.steps)
		{
			steps.add(new Step(s.index + head.tiles.size(), s.transport));
		}
		return new Route(tiles, steps, head.reached && tail.reached, head.cost + ride.duration + tail.cost);
	}

	/**
	 * Tiles between the two points as the crow flies, with dungeons folded onto the ground above
	 * them (they are stored 6400 tiles north), so a search for a spot underground heads for the
	 * ground over it, where its entrance usually is. Floors are ignored; a staircase bridges them.
	 */
	static int heuristic(int a, int b)
	{
		int ay = Packed.y(a);
		int by = Packed.y(b);
		if (ay >= 6400)
		{
			ay -= 6400;
		}
		if (by >= 6400)
		{
			by -= 6400;
		}
		return Math.max(Math.abs(Packed.x(a) - Packed.x(b)), Math.abs(ay - by));
	}

	/**
	 * The tile itself when it can be stood on, else the same spot on another floor that can: the
	 * data's spawn pins carry no floor, and some basements sit on floor 3 in the map.
	 */
	public static int walkableNear(WorldMap map, int packed)
	{
		if (!map.isBlocked(packed))
		{
			return packed;
		}
		int x = Packed.x(packed);
		int y = Packed.y(packed);
		for (int plane = 0; plane < 4; plane++)
		{
			int p = Packed.of(x, y, plane);
			if (!map.isBlocked(p))
			{
				return p;
			}
		}
		return packed;
	}

	/** The Wilderness on the surface, and the dungeons under it, whose caves run further east than the ditch line. */
	static boolean inWilderness(int p)
	{
		int x = Packed.x(p);
		int y = Packed.y(p);
		if (y >= 9920 && y <= 10367)
		{
			return x >= 2944 && x <= 3455;
		}
		return x >= 2944 && x <= 3391 && y >= 3525 && y <= 3967;
	}

	/** A binary heap of (key, value) ints, smallest key first. */
	static final class IntHeap
	{
		private int[] keys;
		private int[] vals;
		private int size;

		IntHeap(int capacity)
		{
			keys = new int[capacity];
			vals = new int[capacity];
		}

		boolean isEmpty()
		{
			return size == 0;
		}

		int peekKey()
		{
			return keys[0];
		}

		void push(int key, int val)
		{
			if (size == keys.length)
			{
				keys = java.util.Arrays.copyOf(keys, size * 2);
				vals = java.util.Arrays.copyOf(vals, size * 2);
			}
			int i = size++;
			while (i > 0)
			{
				int p = (i - 1) >>> 1;
				if (keys[p] <= key)
				{
					break;
				}
				keys[i] = keys[p];
				vals[i] = vals[p];
				i = p;
			}
			keys[i] = key;
			vals[i] = val;
		}

		int pop()
		{
			int out = vals[0];
			int key = keys[--size];
			int val = vals[size];
			int i = 0;
			while (true)
			{
				int l = 2 * i + 1;
				if (l >= size)
				{
					break;
				}
				int r = l + 1;
				int c = r < size && keys[r] < keys[l] ? r : l;
				if (keys[c] >= key)
				{
					break;
				}
				keys[i] = keys[c];
				vals[i] = vals[c];
				i = c;
			}
			if (size > 0)
			{
				keys[i] = key;
				vals[i] = val;
			}
			return out;
		}
	}
}

package com.slayersuite.route;

import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Quest;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;

/**
 * One way of moving between two tiles that is not a step: a door, a staircase, a cave mouth, a
 * trapdoor, an Agility shortcut. Standing on the origin tile and using the object puts you on
 * the destination tile after about {@code duration} ticks.
 */
public final class Transport
{
	public final int origin;
	public final int destination;
	/** The menu option, such as Open, Climb-down or Investigate. */
	public final String action;
	/** The object's name, such as Door or Statue; empty when the row names none. */
	public final String name;
	public final int objectId;
	public final int duration;
	public final String display;
	public final Map<Skill, Integer> skills;
	public final Set<Quest> quests;
	public final List<VarCheck> varbits;
	public final List<VarCheck> varplayers;
	/** Needs something carried that the plugin does not track yet; left out of routes. */
	public final boolean needsItems;
	public final Kind kind;

	/** Which table a transport came from, which also says what it is. */
	public enum Kind
	{
		OBJECT, SHORTCUT, SPIRIT_TREE, FAIRY_RING, GLIDER, BOAT, SHIP, CHARTER, MUSHTREE, QUETZAL, PORTAL, LEVER, LEARNED;

		/** Rows of these tables are stops of one network: every stop reaches every other. */
		public boolean network()
		{
			return this == SPIRIT_TREE || this == FAIRY_RING || this == GLIDER || this == MUSHTREE || this == QUETZAL;
		}

		/** Ticks a ride takes when the table leaves it blank. */
		public int defaultDuration()
		{
			switch (this)
			{
				case SPIRIT_TREE:
					return 6;
				case FAIRY_RING:
					return 5;
				case GLIDER:
					return 8;
				case MUSHTREE:
					return 4;
				case QUETZAL:
					return 6;
				default:
					return 1;
			}
		}
	}

	Transport(int origin, int destination, String action, String name, int objectId, int duration, String display,
			Map<Skill, Integer> skills, Set<Quest> quests, List<VarCheck> varbits, List<VarCheck> varplayers, boolean needsItems, Kind kind)
	{
		this.origin = origin;
		this.destination = destination;
		this.action = action;
		this.name = name;
		this.objectId = objectId;
		this.duration = duration;
		this.display = display;
		this.skills = skills;
		this.quests = quests;
		this.varbits = varbits;
		this.varplayers = varplayers;
		this.needsItems = needsItems;
		this.kind = kind;
	}

	/** A ride from one stop of a network to another, carrying both stops' requirements. */
	static Transport ride(Transport from, Transport to)
	{
		Map<Skill, Integer> skills = new java.util.EnumMap<>(Skill.class);
		skills.putAll(from.skills);
		for (Map.Entry<Skill, Integer> e : to.skills.entrySet())
		{
			skills.merge(e.getKey(), e.getValue(), Math::max);
		}
		Set<Quest> quests = java.util.EnumSet.noneOf(Quest.class);
		quests.addAll(from.quests);
		quests.addAll(to.quests);
		List<VarCheck> varbits = new java.util.ArrayList<>(from.varbits);
		varbits.addAll(to.varbits);
		List<VarCheck> varplayers = new java.util.ArrayList<>(from.varplayers);
		varplayers.addAll(to.varplayers);
		String display = to.display.isEmpty() ? "" : to.display;
		return new Transport(from.origin, to.origin, from.action, from.name, from.objectId, Math.max(from.duration, to.duration), display,
			skills, quests, varbits, varplayers, from.needsItems || to.needsItems, from.kind);
	}

	/** "Climb-down Trapdoor", or just the action when the object has no name; a ride names where it goes: "Fairy ring to CKS". */
	public String label()
	{
		if (kind.network() && display != null && !display.isEmpty())
		{
			return (name.isEmpty() ? action : name) + " to " + display;
		}
		return name.isEmpty() ? action : action + " " + name;
	}

	public WorldPoint originPoint()
	{
		return Packed.toWorld(origin);
	}

	public WorldPoint destinationPoint()
	{
		return Packed.toWorld(destination);
	}

	@Override
	public String toString()
	{
		return label() + " " + originPoint() + " -> " + destinationPoint();
	}

	/** A condition on a varbit or varplayer value: {@code id op value} with op one of = > < &; @ (a cooldown) always holds. */
	public static final class VarCheck
	{
		public final int id;
		public final char op;
		public final int value;

		VarCheck(int id, char op, int value)
		{
			this.id = id;
			this.op = op;
			this.value = value;
		}

		public boolean holds(int current)
		{
			switch (op)
			{
				case '=':
					return current == value;
				case '>':
					return current > value;
				case '<':
					return current < value;
				case '&':
					return (current & value) != 0;
				default:
					return true;
			}
		}
	}
}

package com.slayersuite.route;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Filepath;
import net.runelite.client.util.Text;

/**
 * Learns a transport the first time you use one the tables do not know: you click an object and
 * a moment later you are somewhere you could not have walked to. The pair is kept in
 * learned-transports.tsv under the plugin's folder, in the tables' own layout, and routes use it
 * from then on.
 */
@Slf4j
@Singleton
public class TransportLearner
{
	private static final int WATCH_TICKS = 25;
	private static final String HEADER = "# Origin\tDestination\tmenuOption menuTarget objectID\tSkills\tItems\tQuests\tVarbits\tVarPlayers\tDuration\tDisplay info";

	private final Client client;
	private final RouteService routes;
	private volatile Filepath file;
	private int tick;
	private int lastTile = Integer.MIN_VALUE;
	private int clickObject = -1;
	private String clickOption;
	private String clickTarget;
	private int clickTick = -1;
	private final Set<Integer> announced = new HashSet<>();

	@Inject
	public TransportLearner(Client client, RouteService routes)
	{
		this.client = client;
		this.routes = routes;
	}

	public void setFile(Filepath file)
	{
		this.file = file;
	}

	/** Reads what earlier sessions learned. */
	public void load()
	{
		Filepath f = file;
		if (f == null || !f.exists())
		{
			return;
		}
		try (InputStream in = f.openInputStream())
		{
			List<Transport> learned = TransportTable.parse(in, Transport.Kind.LEARNED);
			if (!learned.isEmpty())
			{
				routes.addTransports(learned);
				log.debug("Slayer Suite: {} learned transports", learned.size());
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("Slayer Suite: learned transports could not be read", e);
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked e)
	{
		MenuAction a = e.getMenuAction();
		if (a != MenuAction.GAME_OBJECT_FIRST_OPTION && a != MenuAction.GAME_OBJECT_SECOND_OPTION && a != MenuAction.GAME_OBJECT_THIRD_OPTION
			&& a != MenuAction.GAME_OBJECT_FOURTH_OPTION && a != MenuAction.GAME_OBJECT_FIFTH_OPTION)
		{
			return;
		}
		String option = e.getMenuOption() == null ? "" : Text.removeTags(e.getMenuOption()).trim();
		if (option.isEmpty() || option.equalsIgnoreCase("Examine") || option.equalsIgnoreCase("Walk here") || option.equalsIgnoreCase("Cancel"))
		{
			return;
		}
		clickObject = e.getId();
		clickOption = option;
		clickTarget = e.getMenuTarget() == null ? "" : Text.removeTags(e.getMenuTarget()).trim();
		clickTick = tick;
	}

	@Subscribe
	public void onGameTick(GameTick t)
	{
		tick++;
		Player me = client.getLocalPlayer();
		WorldView wv = client.getTopLevelWorldView();
		if (client.getGameState() != GameState.LOGGED_IN || me == null || wv == null || wv.isInstance())
		{
			lastTile = Integer.MIN_VALUE;
			return;
		}
		int here = Packed.of(me.getWorldLocation());
		if (clickTick >= 0 && tick - clickTick > WATCH_TICKS)
		{
			clickTick = -1;
		}
		if (lastTile != Integer.MIN_VALUE && clickTick >= 0 && here != lastTile)
		{
			boolean jump = Packed.plane(here) != Packed.plane(lastTile) || Packed.chebyshev(here, lastTile) > 2;
			if (jump)
			{
				learn(lastTile, here);
				clickTick = -1;
			}
		}
		lastTile = here;
	}

	private void learn(int origin, int destination)
	{
		WorldMap map = routes.map();
		TransportTable table = routes.table();
		if (map == null || table == null || table.knows(origin, clickObject))
		{
			return;
		}
		// a jump you could have walked in a few steps is running or lag, not a transport
		Router.Route walk = Router.find(map, table, Collections.emptySet(), origin, destination, 3_000, System.nanoTime() + 50_000_000L, false, 8);
		if (walk.reached)
		{
			return;
		}
		int duration = Math.max(1, Math.min(10, tick - clickTick));
		Transport t = new Transport(origin, destination, clickOption, clickTarget, clickObject, duration, "", Collections.emptyMap(), Collections.emptySet(), Collections.emptyList(), Collections.emptyList(), false, Transport.Kind.LEARNED);
		List<Transport> one = new ArrayList<>(1);
		one.add(t);
		routes.addTransports(one);
		save(t);
		if (announced.add(clickObject))
		{
			client.addChatMessage(ChatMessageType.CONSOLE, "", "<col=00bfff>Slayer Suite:</col> learned the way through " + t.label() + " here; routes will use it.", null);
		}
	}

	private void save(Transport t)
	{
		Filepath f = file;
		if (f == null)
		{
			return;
		}
		try
		{
			Filepath dir = f.getParent();
			if (dir != null && !dir.exists())
			{
				dir.createDirectories();
			}
			String row = Packed.x(t.origin) + " " + Packed.y(t.origin) + " " + Packed.plane(t.origin) + "\t"
				+ Packed.x(t.destination) + " " + Packed.y(t.destination) + " " + Packed.plane(t.destination) + "\t"
				+ t.action + " " + t.name + " " + t.objectId + "\t\t\t\t\t\t" + t.duration + "\t\n";
			if (!f.exists())
			{
				f.write(HEADER + "\n" + row);
			}
			else
			{
				f.write(row, StandardOpenOption.APPEND);
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("Slayer Suite: learned transport could not be saved", e);
		}
	}
}

package com.slayersuite.route;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Quest;
import net.runelite.api.Skill;

/**
 * The transports of the game, read from the Shortest Path project's tables (BSD 2-Clause, see
 * THIRD-PARTY-NOTICES.md) by column name: Origin, Destination, "menuOption menuTarget objectID",
 * Skills ("70 Agility"), Items, Quests, Varbits and VarPlayers ("id=value;id>value"), Duration.
 */
public final class TransportTable
{
	private static final String DIR = "/com/slayersuite/route/transports/";

	private final Map<Integer, List<Transport>> byOrigin;
	private final List<Transport> all;
	private final Map<Transport.Kind, List<Transport>> stops;
	private final Set<Integer> stopTiles;

	private TransportTable(List<Transport> all)
	{
		this.all = Collections.unmodifiableList(all);
		Map<Integer, List<Transport>> map = new HashMap<>();
		Map<Transport.Kind, List<Transport>> byKind = new java.util.EnumMap<>(Transport.Kind.class);
		Set<Integer> tiles = new java.util.HashSet<>();
		for (Transport t : all)
		{
			if (t.kind.network())
			{
				// a stop of a network: rides between stops are planned, not searched tile by tile
				byKind.computeIfAbsent(t.kind, k -> new ArrayList<>()).add(t);
				tiles.add(t.origin);
				continue;
			}
			map.computeIfAbsent(t.origin, k -> new ArrayList<>(2)).add(t);
		}
		this.byOrigin = map;
		this.stops = byKind;
		this.stopTiles = tiles;
	}

	/** Reads every bundled table: objects, shortcuts, and the rides between the stops of each network. */
	public static TransportTable load()
	{
		List<Transport> all = new ArrayList<>(80000);
		all.addAll(parse(resource("transports.tsv"), Transport.Kind.OBJECT));
		all.addAll(parse(resource("extra-transports.tsv"), Transport.Kind.OBJECT));
		all.addAll(parse(resource("agility_shortcuts.tsv"), Transport.Kind.SHORTCUT));
		all.addAll(parse(resource("boats.tsv"), Transport.Kind.BOAT));
		all.addAll(parse(resource("ships.tsv"), Transport.Kind.SHIP));
		all.addAll(parse(resource("charter_ships.tsv"), Transport.Kind.CHARTER));
		all.addAll(parse(resource("teleportation_portals.tsv"), Transport.Kind.PORTAL));
		all.addAll(parse(resource("teleportation_levers.tsv"), Transport.Kind.LEVER));
		all.addAll(parse(resource("spirit_trees.tsv"), Transport.Kind.SPIRIT_TREE));
		all.addAll(withFairyCodes(parse(resource("fairy_rings.tsv"), Transport.Kind.FAIRY_RING)));
		all.addAll(parse(resource("gnome_gliders.tsv"), Transport.Kind.GLIDER));
		all.addAll(parse(resource("magic_mushtrees.tsv"), Transport.Kind.MUSHTREE));
		all.addAll(parse(resource("quetzals.tsv"), Transport.Kind.QUETZAL));
		return new TransportTable(all);
	}

	/** A stop of a network sits here (a ring, a tree, a glider pad), possibly on a solid tile. */
	public boolean isStop(int packed)
	{
		return stopTiles.contains(packed);
	}

	private static final String FAIRY_CODES = "/com/slayersuite/data/fairy-codes.tsv";

	/** Fairy ring stops get their code (CKS, BKP...) as display, from the wiki's code table matched by tile; a ride then reads "Fairy ring to CKS". */
	static List<Transport> withFairyCodes(List<Transport> rings)
	{
		Map<Integer, String> codes = fairyCodes();
		if (codes.isEmpty())
		{
			return rings;
		}
		List<Transport> out = new ArrayList<>(rings.size());
		for (Transport t : rings)
		{
			String code = null;
			for (Map.Entry<Integer, String> e : codes.entrySet())
			{
				int tile = e.getKey();
				if (Packed.plane(tile) == Packed.plane(t.origin) && Packed.chebyshev(tile, t.origin) <= 3)
				{
					code = e.getValue();
					break;
				}
			}
			out.add(code == null ? t : new Transport(t.origin, t.destination, t.action, t.name, t.objectId, t.duration, code,
				t.skills, t.quests, t.varbits, t.varplayers, t.needsItems, t.kind));
		}
		return out;
	}

	private static volatile Map<String, String> fairyPlaces;

	/** Where a fairy ring code lands, in the wiki's words ("Morytania: Canifis"), or "" when unknown. */
	public static String fairyPlace(String code)
	{
		Map<String, String> places = fairyPlaces;
		if (places == null)
		{
			places = new HashMap<>();
			try (InputStream in = TransportTable.class.getResourceAsStream(FAIRY_CODES))
			{
				if (in != null)
				{
					java.io.BufferedReader r = new java.io.BufferedReader(new java.io.InputStreamReader(in, java.nio.charset.StandardCharsets.UTF_8));
					String line;
					while ((line = r.readLine()) != null)
					{
						String[] f = line.split("\t");
						if (!line.startsWith("#") && f.length >= 4)
						{
							places.put(f[0].trim(), f[3].trim());
						}
					}
				}
			}
			catch (IOException | RuntimeException e)
			{
				// no places
			}
			fairyPlaces = places;
		}
		String p = code == null ? null : places.get(code.toUpperCase(java.util.Locale.ROOT));
		return p == null ? "" : p;
	}

	/** Ring tile (plane 0) -> code, from fairy-codes.tsv; empty when the file is missing. */
	static Map<Integer, String> fairyCodes()
	{
		Map<Integer, String> out = new HashMap<>();
		try (InputStream in = TransportTable.class.getResourceAsStream(FAIRY_CODES))
		{
			if (in == null)
			{
				return out;
			}
			java.io.BufferedReader r = new java.io.BufferedReader(new java.io.InputStreamReader(in, java.nio.charset.StandardCharsets.UTF_8));
			String line;
			while ((line = r.readLine()) != null)
			{
				if (line.isEmpty() || line.startsWith("#"))
				{
					continue;
				}
				String[] f = line.split("\t");
				if (f.length >= 3)
				{
					out.put(Packed.of(Integer.parseInt(f[1].trim()), Integer.parseInt(f[2].trim()), 0), f[0].trim());
				}
			}
		}
		catch (IOException | RuntimeException e)
		{
			// no codes: rings stay unnamed
		}
		return out;
	}

	private static InputStream resource(String name)
	{
		InputStream in = TransportTable.class.getResourceAsStream(DIR + name);
		if (in == null)
		{
			throw new IllegalStateException("missing " + DIR + name);
		}
		return in;
	}

	/** A table with these transports added; the old one is untouched, so a running search keeps its view. */
	public TransportTable withAdded(List<Transport> extra)
	{
		List<Transport> merged = new ArrayList<>(all.size() + extra.size());
		merged.addAll(all);
		merged.addAll(extra);
		return new TransportTable(merged);
	}

	/** The stops of a network, each with its own requirements and name. */
	public List<Transport> stops(Transport.Kind kind)
	{
		List<Transport> list = stops.get(kind);
		return list == null ? Collections.emptyList() : list;
	}

	/** Every network kind that has stops. */
	public Set<Transport.Kind> networks()
	{
		return stops.keySet();
	}

	/** True when a transport through this object already leaves the tile. */
	public boolean knows(int origin, int objectId)
	{
		for (Transport t : from(origin))
		{
			if (t.objectId == objectId)
			{
				return true;
			}
		}
		return false;
	}

	public List<Transport> from(int packed)
	{
		List<Transport> list = byOrigin.get(packed);
		return list == null ? Collections.emptyList() : list;
	}

	public List<Transport> all()
	{
		return all;
	}

	public int size()
	{
		return all.size();
	}

	static List<Transport> parse(InputStream source, Transport.Kind kind)
	{
		boolean network = kind.network();
		List<Transport> out = new ArrayList<>();
		try (BufferedReader in = new BufferedReader(new InputStreamReader(source, StandardCharsets.UTF_8)))
		{
			String header = in.readLine();
			if (header == null)
			{
				return out;
			}
			String[] names = header.replaceFirst("^#\\s*", "").split("\t");
			Map<String, Integer> col = new HashMap<>();
			for (int i = 0; i < names.length; i++)
			{
				col.put(names[i].trim(), i);
			}
			for (String key : new String[]{"Origin", "Destination", "menuOption menuTarget objectID"})
			{
				if (!col.containsKey(key))
				{
					throw new IllegalStateException("transport table without a " + key + " column");
				}
			}
			String line;
			String heading = "";
			while ((line = in.readLine()) != null)
			{
				if (line.startsWith("#"))
				{
					heading = line.substring(1).trim();
					continue;
				}
				if (line.isEmpty())
				{
					continue;
				}
				String[] f = line.split("\t", -1);
				int origin = point(cell(f, col, "Origin"));
				int destination = point(cell(f, col, "Destination"));
				if (origin == Integer.MIN_VALUE || (destination == Integer.MIN_VALUE && !network))
				{
					continue;
				}
				if (network)
				{
					// a stop: its destination is filled in when the rides are made
					destination = origin;
				}
				String option = cell(f, col, "menuOption menuTarget objectID").trim();
				String[] tok = option.isEmpty() ? new String[0] : option.split(" +");
				int objectId = -1;
				int nameEnd = tok.length;
				if (tok.length > 1 && tok[tok.length - 1].matches("\\d+"))
				{
					objectId = Integer.parseInt(tok[tok.length - 1]);
					nameEnd--;
				}
				String action = tok.length == 0 ? "Use" : tok[0];
				String name = nameEnd > 1 ? String.join(" ", java.util.Arrays.copyOfRange(tok, 1, nameEnd)) : "";
				String items = cell(f, col, "Items").trim();
				int duration = kind.defaultDuration();
				try
				{
					String d = cell(f, col, "Duration").trim();
					duration = d.isEmpty() ? kind.defaultDuration() : Math.max(1, Integer.parseInt(d));
				}
				catch (NumberFormatException ignored)
				{
					// a blank or odd duration counts as the kind's usual one
				}
				String display = cell(f, col, "Display info").trim();
				if (display.isEmpty() && network)
				{
					display = heading;
				}
				out.add(new Transport(origin, destination, action, name, objectId, duration, display,
					skills(cell(f, col, "Skills")), quests(cell(f, col, "Quests")), vars(cell(f, col, "Varbits")), vars(cell(f, col, "VarPlayers")),
					needsItems(items), kind));
			}
		}
		catch (IOException e)
		{
			throw new UncheckedIOException(e);
		}
		return out;
	}

	private static String cell(String[] f, Map<String, Integer> col, String name)
	{
		Integer i = col.get(name);
		return i == null || i >= f.length ? "" : f[i];
	}

	/** "x y plane" to a packed tile; MIN_VALUE when blank or malformed. */
	private static int point(String s)
	{
		String[] p = s.trim().split(" +");
		if (p.length != 3)
		{
			return Integer.MIN_VALUE;
		}
		try
		{
			return Packed.of(Integer.parseInt(p[0]), Integer.parseInt(p[1]), Integer.parseInt(p[2]));
		}
		catch (NumberFormatException e)
		{
			return Integer.MIN_VALUE;
		}
	}

	private static Map<Skill, Integer> skills(String s)
	{
		if (s == null || s.trim().isEmpty())
		{
			return Collections.emptyMap();
		}
		Map<Skill, Integer> out = new EnumMap<>(Skill.class);
		for (String part : s.split(";"))
		{
			String[] p = part.trim().split(" +");
			if (p.length != 2)
			{
				continue;
			}
			int level;
			try
			{
				level = "Max".equals(p[0]) ? 99 : Integer.parseInt(p[0]);
			}
			catch (NumberFormatException e)
			{
				continue;
			}
			for (Skill sk : Skill.values())
			{
				if (sk.getName().equalsIgnoreCase(p[1]))
				{
					out.put(sk, Math.max(level, out.getOrDefault(sk, 0)));
				}
			}
			// total level, combat level and quest points are not checked and count as met
		}
		return out.isEmpty() ? Collections.emptyMap() : out;
	}

	private static Set<Quest> quests(String s)
	{
		if (s == null || s.trim().isEmpty())
		{
			return Collections.emptySet();
		}
		Set<Quest> out = EnumSet.noneOf(Quest.class);
		for (String part : s.split(";"))
		{
			String want = part.trim();
			for (Quest q : Quest.values())
			{
				if (q.getName().equals(want))
				{
					out.add(q);
					break;
				}
			}
		}
		return out.isEmpty() ? Collections.emptySet() : out;
	}

	private static List<Transport.VarCheck> vars(String s)
	{
		if (s == null || s.trim().isEmpty())
		{
			return Collections.emptyList();
		}
		List<Transport.VarCheck> out = new ArrayList<>(2);
		for (String part : s.split(";"))
		{
			String r = part.trim();
			int at = -1;
			for (int i = 0; i < r.length(); i++)
			{
				if ("=><&@".indexOf(r.charAt(i)) >= 0)
				{
					at = i;
					break;
				}
			}
			if (at <= 0 || at >= r.length() - 1)
			{
				continue;
			}
			try
			{
				out.add(new Transport.VarCheck(Integer.parseInt(r.substring(0, at)), r.charAt(at), Integer.parseInt(r.substring(at + 1))));
			}
			catch (NumberFormatException ignored)
			{
				// a malformed condition is skipped rather than blocking the row
			}
		}
		return out.isEmpty() ? Collections.emptyList() : out;
	}

	/**
	 * True when the row asks for an item the plugin cannot see. A quantity of zero asks for
	 * nothing, and coins are assumed carried.
	 */
	private static boolean needsItems(String items)
	{
		if (items.isEmpty())
		{
			return false;
		}
		for (String and : items.replace(" ", "").split("&"))
		{
			boolean satisfied = false;
			for (String or : and.split("\\|"))
			{
				String[] p = or.split("=");
				if (p.length == 2 && ("0".equals(p[1]) || "COINS".equals(p[0])))
				{
					satisfied = true;
				}
			}
			if (!satisfied)
			{
				return true;
			}
		}
		return false;
	}
}

package com.slayersuite.route;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.UncheckedIOException;
import java.util.Arrays;
import java.util.BitSet;
import java.util.HashMap;
import java.util.Map;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;
import net.runelite.api.Constants;

/**
 * Every walkable tile of the game, decoded from the Shortest Path project's collision map
 * (BSD 2-Clause, see THIRD-PARTY-NOTICES.md; the decoding follows its SplitFlagMap and
 * CollisionMap). Each tile carries four bits per plane: whether its north and east edges can be
 * crossed, and whether a wall or door sits on those edges. A tile with no open edge is solid.
 */
public final class WorldMap
{
	private static final String RESOURCE = "/com/slayersuite/route/collision-map.zip";
	private static final int REGION_SIZE = Constants.REGION_SIZE;
	private static final int FLAG_NORTH = 0;
	private static final int FLAG_EAST = 1;
	private static final int FLAG_COUNT = 4;
	private static final int BITS_PER_PLANE = REGION_SIZE * REGION_SIZE * FLAG_COUNT;
	private static final int WORDS_PER_PLANE = BITS_PER_PLANE / Long.SIZE;
	private static final int REGION_MASK = REGION_SIZE - 1;
	private static final int[] DX = {0, 1, 1, 1, 0, -1, -1, -1};
	private static final int[] DY = {1, 1, 0, -1, -1, -1, 0, 1};

	private final int minRegionX;
	private final int minRegionY;
	private final int regionsWide;
	private final int regionsHigh;
	private final byte[] planeCounts;
	private final int[] wordOffset;
	private final long[] words;
	private final int regionCount;

	private WorldMap(Map<Integer, byte[]> regions, int minX, int minY, int maxX, int maxY)
	{
		minRegionX = minX;
		minRegionY = minY;
		regionsWide = maxX - minX + 1;
		regionsHigh = maxY - minY + 1;
		int slots = regionsWide * regionsHigh;
		planeCounts = new byte[slots];
		wordOffset = new int[slots];
		Arrays.fill(wordOffset, -1);
		Map<Integer, long[]> decoded = new HashMap<>(regions.size());
		int total = 0;
		for (Map.Entry<Integer, byte[]> e : regions.entrySet())
		{
			int index = index(e.getKey() & 0xFFFF, (e.getKey() >>> 16) & 0xFFFF);
			BitSet bits = BitSet.valueOf(e.getValue());
			int planes = (bits.size() + BITS_PER_PLANE - 1) / BITS_PER_PLANE;
			planeCounts[index] = (byte) planes;
			wordOffset[index] = total;
			decoded.put(index, bits.toLongArray());
			total += planes * WORDS_PER_PLANE;
		}
		words = new long[total];
		for (Map.Entry<Integer, long[]> e : decoded.entrySet())
		{
			long[] w = e.getValue();
			System.arraycopy(w, 0, words, wordOffset[e.getKey()], w.length);
		}
		regionCount = regions.size();
	}

	/** Reads the bundled map; about a second and ten megabytes of heap. */
	public static WorldMap load()
	{
		InputStream in = WorldMap.class.getResourceAsStream(RESOURCE);
		if (in == null)
		{
			throw new IllegalStateException("missing " + RESOURCE);
		}
		return load(in);
	}

	public static WorldMap load(InputStream source)
	{
		Map<Integer, byte[]> regions = new HashMap<>();
		int minX = Integer.MAX_VALUE;
		int minY = Integer.MAX_VALUE;
		int maxX = 0;
		int maxY = 0;
		try (ZipInputStream in = new ZipInputStream(source))
		{
			ZipEntry entry;
			byte[] buf = new byte[8192];
			while ((entry = in.getNextEntry()) != null)
			{
				String[] n = entry.getName().split("_");
				if (n.length != 2)
				{
					continue;
				}
				int x = Integer.parseInt(n[0]);
				int y = Integer.parseInt(n[1]);
				minX = Math.min(minX, x);
				minY = Math.min(minY, y);
				maxX = Math.max(maxX, x);
				maxY = Math.max(maxY, y);
				ByteArrayOutputStream out = new ByteArrayOutputStream();
				int read;
				while ((read = in.read(buf)) > 0)
				{
					out.write(buf, 0, read);
				}
				regions.put((x & 0xFFFF) | ((y & 0xFFFF) << 16), out.toByteArray());
			}
		}
		catch (IOException e)
		{
			throw new UncheckedIOException(e);
		}
		if (regions.isEmpty())
		{
			throw new IllegalStateException("empty collision map");
		}
		return new WorldMap(regions, minX, minY, maxX, maxY);
	}

	public int regionCount()
	{
		return regionCount;
	}

	private int index(int regionX, int regionY)
	{
		int rx = regionX - minRegionX;
		int ry = regionY - minRegionY;
		if (rx < 0 || ry < 0 || rx >= regionsWide || ry >= regionsHigh)
		{
			return -1;
		}
		return rx + ry * regionsWide;
	}

	private boolean flag(int x, int y, int z, int flag)
	{
		if (x < 0 || y < 0 || z < 0)
		{
			return false;
		}
		int index = index(x / REGION_SIZE, y / REGION_SIZE);
		if (index < 0)
		{
			return false;
		}
		int offset = wordOffset[index];
		if (offset < 0 || z >= planeCounts[index])
		{
			return false;
		}
		int bit = (z * REGION_SIZE * REGION_SIZE + (y & REGION_MASK) * REGION_SIZE + (x & REGION_MASK)) * FLAG_COUNT + flag;
		return (words[offset + (bit >> 6)] >>> (bit & 63) & 1L) != 0L;
	}

	boolean n(int x, int y, int z)
	{
		return flag(x, y, z, FLAG_NORTH);
	}

	boolean s(int x, int y, int z)
	{
		return n(x, y - 1, z);
	}

	boolean e(int x, int y, int z)
	{
		return flag(x, y, z, FLAG_EAST);
	}

	boolean w(int x, int y, int z)
	{
		return e(x - 1, y, z);
	}

	private boolean ne(int x, int y, int z)
	{
		return n(x, y, z) && e(x, y + 1, z) && e(x, y, z) && n(x + 1, y, z);
	}

	private boolean nw(int x, int y, int z)
	{
		return n(x, y, z) && w(x, y + 1, z) && w(x, y, z) && n(x - 1, y, z);
	}

	private boolean se(int x, int y, int z)
	{
		return s(x, y, z) && e(x, y - 1, z) && e(x, y, z) && s(x + 1, y, z);
	}

	private boolean sw(int x, int y, int z)
	{
		return s(x, y, z) && w(x, y - 1, z) && w(x, y, z) && s(x - 1, y, z);
	}

	/** No edge of the tile can be crossed: solid, or outside the map. */
	public boolean isBlocked(int x, int y, int z)
	{
		return !n(x, y, z) && !s(x, y, z) && !e(x, y, z) && !w(x, y, z);
	}

	public boolean isBlocked(int packed)
	{
		return isBlocked(Packed.x(packed), Packed.y(packed), Packed.plane(packed));
	}

	/**
	 * The tiles one step away that can be walked to. A diagonal is open only when both cardinal
	 * steps beside it are. From a solid tile (standing inside an object) any open tile beside
	 * it counts, so a route can always leave.
	 */
	public int[] neighbours(int packed)
	{
		int x = Packed.x(packed);
		int y = Packed.y(packed);
		int z = Packed.plane(packed);
		if (!isBlocked(x, y, z))
		{
			int mask = 0;
			if (n(x, y, z))
			{
				mask |= 1;
			}
			if (ne(x, y, z))
			{
				mask |= 1 << 1;
			}
			if (e(x, y, z))
			{
				mask |= 1 << 2;
			}
			if (se(x, y, z))
			{
				mask |= 1 << 3;
			}
			if (s(x, y, z))
			{
				mask |= 1 << 4;
			}
			if (sw(x, y, z))
			{
				mask |= 1 << 5;
			}
			if (w(x, y, z))
			{
				mask |= 1 << 6;
			}
			if (nw(x, y, z))
			{
				mask |= 1 << 7;
			}
			int[] out = new int[Integer.bitCount(mask)];
			int k = 0;
			for (int bit = 0; bit < 8; bit++)
			{
				if ((mask & (1 << bit)) != 0)
				{
					out[k++] = Packed.of(x + DX[bit], y + DY[bit], z);
				}
			}
			return out;
		}
		int[] out = new int[8];
		int k = 0;
		for (int dx = -1; dx <= 1; dx++)
		{
			for (int dy = -1; dy <= 1; dy++)
			{
				if ((dx == 0 && dy == 0) || isBlocked(x + dx, y + dy, z))
				{
					continue;
				}
				if (dx == 0 || dy == 0 || (!isBlocked(x + dx, y, z) && !isBlocked(x, y + dy, z)))
				{
					out[k++] = Packed.of(x + dx, y + dy, z);
				}
			}
		}
		return Arrays.copyOf(out, k);
	}
}

package com.slayersuite.sounds;

import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.audio.AudioPlayer;
import net.runelite.client.util.Filepath;

/**
 * Plays the bundled chimes, or a player's own file of the same name from the plugin's
 * sounds folder when one exists. The folder comes from RuneLite's plugin directory API.
 */
@Slf4j
@Singleton
public class SoundPlayer
{
	public enum Sound
	{
		TASK_DONE("task-done.wav"),
		SUPERIOR("superior.wav"),
		ALERT("alert.wav"),
		TICK("tick.wav"),
		/** No bundled file: plays only when the player supplies level-up.wav. */
		LEVEL_UP("level-up.wav");

		final String file;

		Sound(String file)
		{
			this.file = file;
		}
	}

	private final AudioPlayer audioPlayer;
	private final ScheduledExecutorService executor;
	private volatile long lastPlayedAt;
	/** The plugin's sounds folder; null until the plugin starts, in which case only bundled sounds play. */
	private volatile Filepath directory;

	@Inject
	public SoundPlayer(AudioPlayer audioPlayer, ScheduledExecutorService executor)
	{
		this.audioPlayer = audioPlayer;
		this.executor = executor;
	}

	public void setDirectory(Filepath directory)
	{
		this.directory = directory;
	}

	public Filepath getDirectory()
	{
		return directory;
	}

	private Filepath custom(Sound sound)
	{
		Filepath dir = directory;
		if (dir == null)
		{
			return null;
		}
		Filepath f = dir.joinSegment(sound.file);
		return f.isFile() ? f : null;
	}

	public void play(Sound sound, int volumePercent)
	{
		if (volumePercent <= 0)
		{
			return;
		}
		if (sound == Sound.LEVEL_UP && custom(sound) == null)
		{
			return;
		}
		long now = System.currentTimeMillis();
		if (now - lastPlayedAt < (sound == Sound.TICK ? 80 : 250))
		{
			return;
		}
		lastPlayedAt = now;
		float gainDb = (float) (20.0 * Math.log10(Math.max(1, Math.min(100, volumePercent)) / 100.0));
		executor.execute(() ->
		{
			try
			{
				Filepath custom = custom(sound);
				if (custom != null)
				{
					audioPlayer.play(custom, gainDb);
				}
				else
				{
					audioPlayer.play(SoundPlayer.class, "/com/slayersuite/sounds/" + sound.file, gainDb);
				}
			}
			catch (Exception e)
			{
				log.warn("Slayer Suite: could not play {} ({})", sound, e.toString());
			}
		});
	}
}

package com.slayersuite.task;

import lombok.Value;

/** Posted once when a brand-new assignment begins (not on login into a task already underway). */
@Value
public class AssignmentStarted
{
	String name;
	int amount;
}

package com.slayersuite.task;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

/**
 * The game's own slayer tables, read from the client cache: which task the target
 * value means, which area the area value means, and how each master weights
 * its assignments. This is how the client itself names your task, so it works
 * for every master, Mortimer included, with no gem check.
 */
@Slf4j
@Singleton
public class GameTaskTable
{
	/** Target value the game uses for "a boss task"; the boss id then lives in another value. */
	private static final int BOSS_TARGET = 98;

	@Value
	public static class GameTask
	{
		int taskId;
		String name;
		int remaining;
		String area;
		int masterId;
	}

	private final Client client;
	private final Map<Integer, String> nameCache = new LinkedHashMap<>();
	private final Map<Integer, String> areaCache = new LinkedHashMap<>();
	private final Map<Integer, Map<Integer, Integer>> weightCache = new LinkedHashMap<>();

	@Inject
	public GameTaskTable(Client client)
	{
		this.client = client;
	}

	/** The current assignment straight from the game, or null when there is none or the tables are unavailable. */
	public GameTask currentTask()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return null;
		}
		try
		{
			int remaining = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
			if (remaining <= 0)
			{
				return null;
			}
			int target = client.getVarpValue(VarPlayerID.SLAYER_TARGET);
			int taskId = target;
			if (target == BOSS_TARGET)
			{
				int bossId = client.getVarbitValue(VarbitID.SLAYER_TARGET_BOSSID);
				List<Integer> rows = client.getDBRowsByValue(DBTableID.SlayerTaskSublist.ID, DBTableID.SlayerTaskSublist.COL_TASK_SUBTABLE_ID, 0, bossId);
				if (rows == null || rows.isEmpty())
				{
					return null;
				}
				Object[] f = client.getDBTableField(rows.get(0), DBTableID.SlayerTaskSublist.COL_TASK, 0);
				if (f == null || f.length == 0 || !(f[0] instanceof Integer))
				{
					return null;
				}
				taskId = (Integer) f[0];
			}
			String name = taskName(taskId);
			if (name == null)
			{
				return null;
			}
			String area = null;
			int areaId = client.getVarpValue(VarPlayerID.SLAYER_AREA);
			if (areaId > 0)
			{
				area = areaName(areaId);
			}
			int master = client.getVarbitValue(VarbitID.SLAYER_MASTER);
			return new GameTask(taskId, name, remaining, area, master);
		}
		catch (RuntimeException e)
		{
			log.debug("slayer table lookup failed", e);
			return null;
		}
	}

	/** Display name of a task id from the SlayerTask table, or null. */
	public String taskName(int taskId)
	{
		String cached = nameCache.get(taskId);
		if (cached != null)
		{
			return cached;
		}
		List<Integer> rows = client.getDBRowsByValue(DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID, 0, taskId);
		if (rows == null || rows.isEmpty())
		{
			return null;
		}
		Object[] f = client.getDBTableField(rows.get(0), DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0);
		if (f == null || f.length == 0 || !(f[0] instanceof String))
		{
			f = client.getDBTableField(rows.get(0), DBTableID.SlayerTask.COL_NAME_LOWERCASE, 0);
		}
		if (f == null || f.length == 0 || !(f[0] instanceof String))
		{
			return null;
		}
		String name = (String) f[0];
		nameCache.put(taskId, name);
		return name;
	}

	public String areaName(int areaId)
	{
		String cached = areaCache.get(areaId);
		if (cached != null)
		{
			return cached;
		}
		List<Integer> rows = client.getDBRowsByValue(DBTableID.SlayerArea.ID, DBTableID.SlayerArea.COL_AREA_ID, 0, areaId);
		if (rows == null || rows.isEmpty())
		{
			return null;
		}
		Object[] f = client.getDBTableField(rows.get(0), DBTableID.SlayerArea.COL_AREA_NAME_IN_HELPER, 0);
		if (f == null || f.length == 0 || !(f[0] instanceof String))
		{
			f = client.getDBTableField(rows.get(0), DBTableID.SlayerArea.COL_AREA_TEXT, 0);
		}
		if (f == null || f.length == 0 || !(f[0] instanceof String))
		{
			return null;
		}
		String name = (String) f[0];
		areaCache.put(areaId, name);
		return name;
	}

	/** task id -> weight for one master, from the SlayerMasterTask table (empty when unavailable). */
	public Map<Integer, Integer> masterWeights(int masterId)
	{
		Map<Integer, Integer> cached = weightCache.get(masterId);
		if (cached != null)
		{
			return cached;
		}
		Map<Integer, Integer> out = new LinkedHashMap<>();
		try
		{
			List<Integer> rows = client.getDBRowsByValue(DBTableID.SlayerMasterTask.ID, DBTableID.SlayerMasterTask.COL_MASTER_ID, 0, masterId);
			if (rows != null)
			{
				for (int row : rows)
				{
					Object[] task = client.getDBTableField(row, DBTableID.SlayerMasterTask.COL_TASK, 0);
					Object[] weight = client.getDBTableField(row, DBTableID.SlayerMasterTask.COL_WEIGHT, 0);
					if (task != null && task.length > 0 && task[0] instanceof Integer && weight != null && weight.length > 0 && weight[0] instanceof Integer)
					{
						out.merge((Integer) task[0], (Integer) weight[0], Integer::sum);
					}
				}
			}
		}
		catch (RuntimeException e)
		{
			log.debug("master weights lookup failed", e);
		}
		if (!out.isEmpty())
		{
			weightCache.put(masterId, out);
		}
		return out;
	}

	/** Share of this master's rolls that land on the task, 0..1, or -1 when unknown. Ignores unlocks and blocks. */
	public double rollChance(int masterId, int taskId)
	{
		Map<Integer, Integer> w = masterWeights(masterId);
		if (w.isEmpty() || !w.containsKey(taskId))
		{
			return -1;
		}
		long total = 0;
		for (int v : w.values())
		{
			total += v;
		}
		return total <= 0 ? -1 : w.get(taskId) / (double) total;
	}

	/** Min and max amount this master assigns for the task, or null. */
	public int[] masterAmounts(int masterId, int taskId)
	{
		try
		{
			List<Integer> rows = client.getDBRowsByValue(DBTableID.SlayerMasterTask.ID, DBTableID.SlayerMasterTask.COL_MASTER_ID, 0, masterId);
			if (rows == null)
			{
				return null;
			}
			for (int row : rows)
			{
				Object[] task = client.getDBTableField(row, DBTableID.SlayerMasterTask.COL_TASK, 0);
				if (task != null && task.length > 0 && task[0] instanceof Integer && (Integer) task[0] == taskId)
				{
					Object[] min = client.getDBTableField(row, DBTableID.SlayerMasterTask.COL_MIN_AMOUNT, 0);
					Object[] max = client.getDBTableField(row, DBTableID.SlayerMasterTask.COL_MAX_AMOUNT, 0);
					if (min != null && max != null && min.length > 0 && max.length > 0 && min[0] instanceof Integer && max[0] instanceof Integer)
					{
						return new int[]{(Integer) min[0], (Integer) max[0]};
					}
				}
			}
		}
		catch (RuntimeException e)
		{
			log.debug("master amounts lookup failed", e);
		}
		return null;
	}

	public static String masterName(int masterId)
	{
		switch (masterId)
		{
			case 1: return "Turael";
			case 2: return "Mazchna";
			case 3: return "Vannaka";
			case 4: return "Chaeldar";
			case 5: return "Duradel";
			case 6: return "Nieve";
			case 7: return "Krystilia";
			case 8: return "Konar";
			case 10: return "Mortimer";
			default: return "your master";
		}
	}
}

