		String b = configManager.getConfiguration(SlayerSuiteConfig.GROUP, "discoveredCountVarbit");
		try
		{
			discoveredCountVarp = v == null ? -1 : Integer.parseInt(v);
			discoveredCountVarbit = b == null ? -1 : Integer.parseInt(b);
		}
