/**
 * Measures food eaten, potion doses drunk and prayer points spent per kill from
 * inventory and stat changes, then projects how many kills the current supplies
 * last. Read-only: it never eats or drinks for you.
 */
@Singleton
public class TripTracker
{
	private static final Pattern DOSE = Pattern.compile("\\((\\d)\\)$");
	private static final int MIN_KILLS_FOR_SESSION_RATE = 5;
	private static final long AFTER_BANK_GRACE_MS = 4_000L;

	@Value
	public static class Projection
	{
		long killsUntilDry;
		long shortfall;
		String limitingResource;
		boolean fromHistory;
		/** One human line per resource, for chat and logs. */
		List<String> lines;
		/** The same per resource, structured for the panel's rows. */
		List<Resource> resources;
	}

	/** One consumable on the supplies card: what you carry, how fast it goes, how many kills it lasts (-1 unknown). */
	@Value
	public static class Resource
	{
		String name;
		String have;
		String rate;
		long lastsKills;
	}

	/** How much prayer one dose gives at a prayer level: potions restore 7 + level/4, super restores 8 + level/4, brews 2 + level/10. */
	public static int prayerPerDose(String normalizedName, int prayerLevel)
	{
		if (normalizedName.startsWith("prayer potion"))
		{
			return 7 + prayerLevel / 4;
		}
		if (normalizedName.startsWith("ancient brew") || normalizedName.startsWith("forgotten brew"))
		{
			return 2 + prayerLevel / 10;
		}
		return 8 + prayerLevel / 4;
	}

	/** Minutes of dragonfire protection one dose gives. */
	public static int antifireMinutesPerDose(String normalizedName)
	{
		if (normalizedName.startsWith("extended super antifire"))
		{
			return 6;
		}
		if (normalizedName.startsWith("extended antifire"))
		{
			return 12;
		}
		if (normalizedName.startsWith("super antifire"))
		{
			return 3;
		}
		return 6;
	}

	private final Client client;
	private final ItemManager itemManager;
	private final com.slayersuite.data.SlayerDataset dataset;
	private final ReadinessChecker readiness;
	private final TaskTracker tracker;
	private final TaskHistory history;
	private final SlayerSuiteConfig config;
	private final EventBus eventBus;

	private final Map<Integer, int[]> itemInfo = new HashMap<>(); // id -> {edible 0/1, doses}

	private int foodCount = -1;
	private int doseCount = -1;
	/** Prayer points stored in restore doses and minutes of antifire carried, from the last inventory scan. */
	private int prayerInDoses;
	private int prayerDoses;
	private int antifireMinutes;
	private int antifireDoses;
	private final Map<Integer, String> nameCache = new HashMap<>();
	private int prevPrayer = -1;
	private long bankClosedAt;
	private boolean alertedThisTrip;
	private int tick;

	@Getter
	private double foodEaten;
	/** Cannonballs loaded this assignment and what they cost; counts drops of 1-35 balls between inventory snapshots. */
	@Getter
	private int ballsUsed;
	@Getter
	private long ballsCost;
	private int ballCount = -1;
	private long ballPriceEach;
	@Getter
	private double dosesUsed;
	@Getter
	private double prayerSpent;
	@Getter
	private long sessionKills;
	@Getter
	private Projection projection;

	private double priorFoodPerKill;
	private double priorDosesPerKill;

	@Inject
	public TripTracker(Client client, ItemManager itemManager, com.slayersuite.data.SlayerDataset dataset, ReadinessChecker readiness, TaskTracker tracker, TaskHistory history, SlayerSuiteConfig config, EventBus eventBus)
	{
		this.dataset = dataset;
		this.client = client;
		this.itemManager = itemManager;
		this.readiness = readiness;
		this.tracker = tracker;
		this.history = history;
		this.config = config;
		this.eventBus = eventBus;
	}

	public void reset()
	{
		foodCount = doseCount = -1;
		prevPrayer = -1;
		foodEaten = dosesUsed = prayerSpent = 0;
		ballsUsed = 0;
		ballsCost = 0;
		sessionKills = 0;
		projection = null;
		alertedThisTrip = false;
		priorFoodPerKill = priorDosesPerKill = 0;
	}

	public double foodPerKill()
	{
		return TripMath.perKill(foodEaten, sessionKills);
	}

	public double dosesPerKill()
	{
		return TripMath.perKill(dosesUsed, sessionKills);
	}

	public double prayerPerKill()
	{
		return TripMath.perKill(prayerSpent, sessionKills);
	}

	public int getFoodCount()
	{
		return Math.max(0, foodCount);
	}

	/** False until the inventory has been read this login. */
	public boolean foodKnown()
	{
		return foodCount >= 0;
	}

	public int getDoseCount()
	{
		return Math.max(0, doseCount);
	}

	// ---------------------------------------------------------------- inventory

	private int[] info(int id)
	{
		int[] v = itemInfo.get(id);
		if (v == null)
		{
			ItemComposition comp = itemManager.getItemComposition(id);
			int edible = 0;
			int doses = 0;
			String[] actions = comp.getInventoryActions();
			if (actions != null)
			{
				for (String a : actions)
				{
					if ("Eat".equalsIgnoreCase(a))
					{
						edible = 1;
					}
					else if ("Drink".equalsIgnoreCase(a))
					{
						Matcher m = DOSE.matcher(comp.getName() == null ? "" : comp.getName());
						doses = m.find() ? Integer.parseInt(m.group(1)) : 1;
					}
				}
			}
			v = new int[]{edible, doses};
			itemInfo.put(id, v);
		}
		return v;
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged e)
	{
		if (e.getContainerId() != InventoryID.INV)
		{
			return;
		}
		ItemContainer inv = e.getItemContainer();
		int food = 0;
		int doses = 0;
		int prayerPts = 0;
		int prayerD = 0;
		int fireMin = 0;
		int fireD = 0;
		int prayerLevel = client.getGameState() == GameState.LOGGED_IN ? client.getRealSkillLevel(Skill.PRAYER) : 1;
		com.slayersuite.data.ItemGroups groups = dataset.getItems();
		int balls = 0;
		if (inv != null)
		{
			for (Item it : inv.getItems())
			{
				if (it == null || it.getId() <= 0)
				{
					continue;
				}
				String bn = nameCache.get(it.getId());
				if (bn == null)
				{
					bn = com.slayersuite.data.ItemNames.normalize(itemManager.getItemComposition(it.getId()).getName());
					nameCache.put(it.getId(), bn);
				}
				if (groups.satisfied("cannonballs", java.util.Collections.singleton(bn)))
				{
					balls += Math.max(1, it.getQuantity());
					if (ballPriceEach <= 0)
					{
						ballPriceEach = Math.max(0, itemManager.getItemPrice(it.getId()));
					}
				}
				int[] v = info(it.getId());
				int qty = Math.max(1, it.getQuantity());
				food += v[0] * qty;
				doses += v[1] * qty;
				if (v[1] > 0)
				{
					String n = nameCache.get(it.getId());
					if (n == null)
					{
						n = com.slayersuite.data.ItemNames.normalize(itemManager.getItemComposition(it.getId()).getName());
						nameCache.put(it.getId(), n);
					}
					java.util.Set<String> one = java.util.Collections.singleton(n);
					if (groups.satisfied("prayer_restore", one))
					{
						prayerD += v[1] * qty;
						prayerPts += v[1] * qty * prayerPerDose(n, prayerLevel);
					}
					else if (groups.satisfied("antifire_potion", one))
					{
						fireD += v[1] * qty;
						fireMin += v[1] * qty * antifireMinutesPerDose(n);
					}
				}
			}
		}
		prayerInDoses = prayerPts;
		prayerDoses = prayerD;
		antifireMinutes = fireMin;
		antifireDoses = fireD;
		long now = System.currentTimeMillis();
		boolean settling = readiness.isBankOpen() || now - bankClosedAt < AFTER_BANK_GRACE_MS;
		if (!settling && tracker.hasTask() && foodCount >= 0 && doseCount >= 0)
		{
			int dFood = foodCount - food;
			int dDoses = doseCount - doses;
			// one bite or one sip at a time; bigger jumps are deposits, drops or death
			if (dFood > 0 && dFood <= 2)
			{
				foodEaten += dFood;
			}
			if (dDoses > 0 && dDoses <= 2)
			{
				dosesUsed += dDoses;
			}
		}
		if (!settling && tracker.hasTask() && ballCount >= 0)
		{
			int dBalls = ballCount - balls;
			// loading the cannon takes up to 30 at a time; anything bigger is a deposit, drop or death
			if (dBalls > 0 && dBalls <= 35)
			{
				ballsUsed += dBalls;
				ballsCost += dBalls * ballPriceEach;
			}
		}
		ballCount = balls;
		if (food > foodCount || doses > doseCount)
		{
			alertedThisTrip = false; // restocked
		}
		foodCount = food;
		doseCount = doses;
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded e)
	{
		if (e.getGroupId() == InterfaceID.BANKMAIN || e.getGroupId() == InterfaceID.BANK_DEPOSITBOX)
		{
			bankClosedAt = System.currentTimeMillis();
			alertedThisTrip = false;
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed e)
	{
		if (e.getGroupId() == InterfaceID.BANKMAIN || e.getGroupId() == InterfaceID.BANK_DEPOSITBOX)
		{
			bankClosedAt = System.currentTimeMillis();
		}
	}

	// ---------------------------------------------------------------- task flow

	@Subscribe
	public void onTaskChanged(TaskChanged e)
	{
		foodEaten = dosesUsed = prayerSpent = 0;
		ballsUsed = 0;
		ballsCost = 0;
		sessionKills = 0;
		projection = null;
		alertedThisTrip = false;
		TaskStats stats = history.getCurrent();
		priorFoodPerKill = stats == null ? 0 : stats.getFoodPerKill();
		priorDosesPerKill = stats == null ? 0 : stats.getDosesPerKill();
	}

	@Subscribe
	public void onKillCounted(KillCounted e)
	{
		sessionKills += e.getDelta();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		if (e.getGameState() != GameState.LOGGED_IN)
		{
			prevPrayer = -1;
			foodCount = doseCount = -1;
		}
	}

	@Subscribe
	public void onGameTick(GameTick t)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		TaskStats current = history.getCurrent();
		readiness.setPrayerPerKill(current == null ? 0 : current.getPrayerPerKill());
		if (foodCount < 0 || doseCount < 0)
		{
			ItemContainer inv = client.getItemContainer(InventoryID.INV);
			if (inv != null)
			{
				onItemContainerChanged(new ItemContainerChanged(InventoryID.INV, inv));
			}
		}
		int prayer = client.getBoostedSkillLevel(Skill.PRAYER);
		if (prevPrayer >= 0 && prayer < prevPrayer && tracker.hasTask())
		{
			prayerSpent += prevPrayer - prayer;
		}
		prevPrayer = prayer;

		if (++tick % 10 == 0)
		{
			projection = project();
			if (projection != null && projection.getKillsUntilDry() >= 0 && config.suppliesAlert() && !alertedThisTrip && !readiness.isBankOpen()
				&& projection.getShortfall() > config.suppliesMargin() && sessionKills >= 1)
			{
				alertedThisTrip = true;
				eventBus.post(new SuppliesLow(projection.getKillsUntilDry(), projection.getShortfall(), projection.getLimitingResource()));
			}
		}
	}

	/** True when the task's own protection rules name dragonfire protection; a stray antifire dose at spectres is not a supply. */
	public boolean taskNeedsAntifire()
	{
		com.slayersuite.data.TaskRecord rec = tracker.getRecord();
		if (rec == null)
		{
			return false;
		}
		for (com.slayersuite.data.ItemRule rule : rec.getProtection())
		{
			for (String group : rule.getAnyOf())
			{
				if (group.contains("antifire"))
				{
					return true;
				}
			}
		}
		return false;
	}

	/** Kills the current supplies last, against kills remaining; null when nothing measurable is being consumed. */
	Projection project()
	{
		if (!tracker.hasTask() || tracker.getRemaining() <= 0 || foodCount < 0 || doseCount < 0)
		{
			return null;
		}
		boolean fromSession = sessionKills >= MIN_KILLS_FOR_SESSION_RATE;
		TaskStats stats = history.getCurrent();
		double fpk = fromSession ? foodPerKill() : priorFoodPerKill;
		double dpk = fromSession ? dosesPerKill() : priorDosesPerKill;
		double ppk = fromSession ? prayerPerKill() : (stats == null ? 0 : stats.getPrayerPerKill());
		int remaining = tracker.getRemaining();
		List<String> lines = new ArrayList<>();
		List<Resource> rows = new ArrayList<>();

		long foodKills = TripMath.killsUntilDry(getFoodCount(), fpk);
		String pieces = getFoodCount() + (getFoodCount() == 1 ? " piece" : " pieces");
		if (foodKills >= 0)
		{
			lines.add("Food: " + pieces + ", " + String.format("%.2f", fpk) + " per kill, lasts ~" + foodKills + " kills");
			rows.add(new Resource("Food", pieces, String.format("%.2f/kill", fpk), foodKills));
		}
		else if (getFoodCount() > 0)
		{
			lines.add("Food: " + pieces + ", none eaten yet");
			rows.add(new Resource("Food", pieces, "none eaten yet", -1));
		}

		// Prayer: points you have now plus what the restores hold, against points per kill.
		long prayerKills = -1;
		if (ppk > 0)
		{
			int now = client.getGameState() == GameState.LOGGED_IN ? client.getBoostedSkillLevel(Skill.PRAYER) : 0;
			long available = now + prayerInDoses;
			prayerKills = (long) Math.floor(available / ppk);
			lines.add("Prayer: " + now + " points + " + prayerDoses + " doses (" + prayerInDoses + " points), " + String.format("%.1f", ppk) + " per kill, lasts ~" + prayerKills + " kills");
			rows.add(new Resource("Prayer", now + " pts + " + prayerDoses + (prayerDoses == 1 ? " dose" : " doses") + " (" + prayerInDoses + " pts)", String.format("%.1f/kill", ppk), prayerKills));
		}
		else if (prayerDoses > 0)
		{
			lines.add("Prayer: " + prayerDoses + " restore doses, no prayer spent yet");
			rows.add(new Resource("Prayer", prayerDoses + " restore " + (prayerDoses == 1 ? "dose" : "doses"), "none spent yet", -1));
		}

		// Antifire: minutes carried against the time the task still needs.
		long antifireKills = -1;
		if (antifireDoses > 0 && taskNeedsAntifire())
		{
			double kph = tracker.effectiveKph();
			if (kph > 0)
			{
				antifireKills = (long) Math.floor(antifireMinutes / 60.0 * kph);
				long etaMin = Math.round(remaining / kph * 60);
				lines.add("Antifire: " + antifireDoses + (antifireDoses == 1 ? " dose = " : " doses = ") + antifireMinutes + " min, task needs ~" + etaMin + " min at " + Math.round(kph) + " kills/h");
				rows.add(new Resource("Antifire", antifireDoses + (antifireDoses == 1 ? " dose = " : " doses = ") + antifireMinutes + " min", "task needs ~" + etaMin + " min", antifireKills));
			}
			else
			{
				lines.add("Antifire: " + antifireDoses + (antifireDoses == 1 ? " dose = " : " doses = ") + antifireMinutes + " min");
				rows.add(new Resource("Antifire", antifireDoses + (antifireDoses == 1 ? " dose = " : " doses = ") + antifireMinutes + " min", "no rate yet", -1));
			}
		}

		// Other potions, by dose, as before.
		int otherDoses = Math.max(0, getDoseCount() - prayerDoses - antifireDoses);
		long doseKills = TripMath.killsUntilDry(otherDoses, dpk);
		if (doseKills >= 0 && otherDoses > 0)
		{
			lines.add("Other potions: " + otherDoses + " doses, " + String.format("%.2f", dpk) + " per kill, lasts ~" + doseKills + " kills");
			rows.add(new Resource("Potions", otherDoses + (otherDoses == 1 ? " dose" : " doses"), String.format("%.2f/kill", dpk), doseKills));
		}

		long kills = TripMath.minPositive(foodKills, prayerKills, antifireKills, doseKills);
		if (kills < 0)
		{
			return lines.isEmpty() ? null : new Projection(-1, 0, "", !fromSession, lines, rows);
		}
		String limiting = kills == prayerKills && prayerKills >= 0 ? "prayer" : kills == antifireKills && antifireKills >= 0 ? "antifire"
			: kills == foodKills && foodKills >= 0 ? "food" : "potions";
		long shortfall = remaining - kills;
		return new Projection(kills, Math.max(0, shortfall), limiting, !fromSession, lines, rows);
	}
}

package com.slayersuite.ui;

import java.awt.Color;

/** The one set of colours every in-game surface uses, so a warning looks the same on the card, the bank list and the floor. */
public final class Palette
{
	/** Have it, fine, done. */
	public static final Color OK = new Color(120, 220, 120);
	/** Recommended, running low, worth a look. */
	public static final Color WARN = new Color(255, 200, 80);
	/** Missing, critical, about to vanish. */
	public static final Color BAD = new Color(255, 90, 90);
	/** Numbers and facts that are neither good nor bad. */
	public static final Color INFO = new Color(120, 205, 255);
	/** Labels and small print. */
	public static final Color DIM = new Color(170, 170, 170);
	/** Loot value and the big moments. */
	public static final Color GOLD = new Color(232, 180, 60);
	/** Drops left on the floor. */
	public static final Color MISSED = new Color(225, 135, 135);
	/** Superiors: an exotic violet, with its glow and its calmer shade once you have engaged one. */
	public static final Color SUPERIOR = new Color(190, 70, 255);
	public static final Color SUPERIOR_GLOW = new Color(240, 190, 255);
	public static final Color SUPERIOR_CALM = new Color(165, 125, 230);
	/** A hairline between blocks on a dark card. */
	public static final Color RULE = new Color(255, 255, 255, 28);
	/** The faint well a number tile sits in. */
	public static final Color TILE = new Color(0, 0, 0, 45);

	private Palette()
	{
	}
}

package com.slayersuite;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import com.slayersuite.data.LocationRecord;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

public class CannonTileTest
{
	private static LocationRecord withPins(int[]... pins)
	{
		LocationRecord l = new LocationRecord();
		List<List<Integer>> list = new ArrayList<>();
		for (int[] p : pins)
		{
			list.add(Arrays.asList(p[0], p[1]));
		}
		l.setPins(list);
		return l;
	}

	@Test
	public void picksTheTileCoveringTheMostSpawns()
	{
		// five spawns in a cluster and two far off: the cannon goes in the cluster, not at the spawns' middle
		LocationRecord l = withPins(new int[]{100, 100}, new int[]{103, 102}, new int[]{98, 104}, new int[]{101, 97}, new int[]{104, 99}, new int[]{140, 140}, new int[]{60, 60});
		int[] tile = l.cannonTile();
		int covered = 0;
		for (int[] p : new int[][]{{100, 100}, {103, 102}, {98, 104}, {101, 97}, {104, 99}})
		{
			if (Math.max(Math.abs(p[0] - tile[0]), Math.abs(p[1] - tile[1])) <= LocationRecord.CANNON_REACH)
			{
				covered++;
			}
		}
		assertEquals(5, covered);
	}

	@Test
	public void needsAFewSpawnsToSayAnything()
	{
		assertNull(withPins(new int[]{1, 1}, new int[]{2, 2}).cannonTile());
	}
}

package com.slayersuite;

import com.google.gson.Gson;
import com.slayersuite.data.ItemGroups;
import com.slayersuite.data.ItemNames;
import com.slayersuite.data.ItemRule;
import com.slayersuite.data.LocationRecord;
import com.slayersuite.data.SlayerDataset;
import com.slayersuite.data.TaskRecord;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class DatasetTest
{
	private SlayerDataset load()
	{
		SlayerDataset d = new SlayerDataset(new Gson());
		d.load();
		return d;
	}

	@Test
	public void loadsAndIndexes()
	{
		SlayerDataset d = load();
		assertTrue(d.isLoaded());
		assertTrue("expected at least 60 tasks, got " + d.getTasks().size(), d.getTasks().size() >= 60);
		assertTrue(d.getItems().keys().contains("slayer_helm"));
	}

	/** Tasks the wiki gives no place for: umbrella pages and two bosses whose pages have no pins yet. Anything else here is a build regression. */
	private static final java.util.Set<String> KNOWN_WITHOUT_LOCATIONS = new java.util.HashSet<>(java.util.Arrays.asList(
		"dragons", "giants", "the-maggot-king", "the-shellbane-gryphon", "tzkal-zuk"));

	@Test
	public void everyTaskHasSomewhereToGo()
	{
		SlayerDataset d = load();
		java.util.List<String> missing = new java.util.ArrayList<>();
		int withRegions = 0;
		for (com.slayersuite.data.TaskRecord t : d.getTasks())
		{
			if (t.getLocations().isEmpty())
			{
				if (!KNOWN_WITHOUT_LOCATIONS.contains(t.getKey()))
				{
					missing.add(t.getKey());
				}
				continue;
			}
			boolean regions = false;
			for (com.slayersuite.data.LocationRecord l : t.getLocations())
			{
				if (l.getRegions() != null && !l.getRegions().isEmpty())
				{
					regions = true;
					break;
				}
			}
			if (regions)
			{
				withRegions++;
			}
		}
		assertTrue("tasks with no locations at all: " + missing, missing.isEmpty());
		assertTrue("only " + withRegions + " tasks have a location with map regions", withRegions >= 125);
		assertFalse(d.find("cockatrice").getLocations().isEmpty());
	}

	@Test
	public void findsTasksTheWayTheCorePluginSpellsThem()
	{
		SlayerDataset d = load();
		assertEquals("aberrant-spectres", d.find("aberrant spectres").getKey());
		assertEquals("aberrant-spectres", d.find("Aberrant Spectre").getKey());
		assertEquals("kalphites", d.find("kalphite").getKey());
		assertEquals("cave-krakens", d.find("cave kraken").getKey());
		assertEquals("dark-beast", d.find("dark beasts").getKey());
		assertEquals("tzhaar", d.find("TzHaar").getKey());
		assertEquals("fossil-island-wyverns", d.find("fossil island wyverns").getKey());
		assertEquals("gargoyles", d.find("Gargoyles").getKey());
		assertNull(d.find("not a real task"));
		assertNull(d.find(""));
	}

	@Test
	public void requiredItemsAndRegionsArePresent()
	{
		SlayerDataset d = load();
		TaskRecord t = d.find("aberrant spectres");
		assertNotNull(t);
		boolean nosePeg = false;
		for (ItemRule r : t.getRequiredItems())
		{
			nosePeg |= r.getAnyOf().contains("nose_peg") && r.getAnyOf().contains("slayer_helm") && r.isRequired();
		}
		assertTrue(nosePeg);
		assertTrue(t.getSuperiors().contains("Abhorrent spectre"));
		assertEquals(Integer.valueOf(60), t.getSlayerLevel());
		LocationRecord loc = d.locationFor(t, new int[]{13623});
		assertNotNull(loc);
		assertEquals("Slayer Tower", loc.getName());
		assertEquals(Boolean.FALSE, loc.getCannon());
		assertNull(d.locationFor(t, new int[]{12850}));

		TaskRecord g = d.find("gargoyles");
		assertNotNull(g.getFinishingItem());
		assertEquals(Integer.valueOf(9), g.getFinishingItem().getThreshold());
		assertTrue(g.getFinishingItem().getAnyOf().contains("rock_hammer"));
	}

	@Test
	public void itemNameNormalisation()
	{
		assertEquals("black mask", ItemNames.normalize("Black mask (10) (i)"));
		assertEquals("slayer helmet", ItemNames.normalize("Slayer helmet (i)"));
		assertEquals("antifire potion", ItemNames.normalize("Antifire potion(4)"));
		assertEquals("extended super antifire", ItemNames.normalize("Extended super antifire(2)"));
		assertEquals("anti-venom+", ItemNames.normalize("Anti-venom+(4)"));
		assertEquals("fungicide spray", ItemNames.normalize("Fungicide spray 10"));
		assertEquals("dragonfire shield (uncharged)", ItemNames.normalize("Dragonfire shield (uncharged)"));
		assertEquals("bullseye lantern (lit)", ItemNames.normalize("Bullseye lantern (lit)"));
		assertEquals("salve amulet", ItemNames.normalize("Salve amulet(ei)"));
		assertEquals("kandarin headgear", ItemNames.normalize("Kandarin headgear 4"));
	}

	@Test
	public void itemGroupsMatchHeldNames()
	{
		SlayerDataset d = load();
		ItemGroups items = d.getItems();
		Set<String> held = new HashSet<>(Arrays.asList(
			ItemNames.normalize("Black mask (10)"),
			ItemNames.normalize("Super antifire potion(3)"),
			ItemNames.normalize("Cannon base"),
			ItemNames.normalize("Cannon stand")));
		assertTrue(items.satisfied("black_mask", held));
		assertFalse(items.satisfied("slayer_helm", held));
		assertTrue(items.anySatisfied(Arrays.asList("slayer_helm", "black_mask"), held));
		assertTrue(items.satisfied("antifire_potion", held));
		assertFalse("needs all four parts", items.satisfied("cannon_parts", held));
		assertEquals("Black mask", items.heldName(Arrays.asList("slayer_helm", "black_mask"), held));
	}
}

package com.slayersuite;

import com.google.gson.Gson;
import com.slayersuite.data.DropRecord;
import com.slayersuite.data.MonsterRecord;
import com.slayersuite.data.SlayerDataset;
import com.slayersuite.data.TaskRecord;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class DropOddsTest
{
	private static DropRecord drop(String name, double p, String where)
	{
		DropRecord d = new DropRecord();
		d.setName(name);
		d.setP(p);
		d.setRarity("1/" + Math.round(1 / p));
		d.setWhere(where);
		return d;
	}

	private static MonsterRecord monster(String name, boolean superior, DropRecord... drops)
	{
		MonsterRecord m = new MonsterRecord();
		m.setName(name);
		m.setSuperior(superior);
		m.setDrops(Arrays.asList(drops));
		return m;
	}

	@Test
	public void chanceOfAtLeastOneByNow()
	{
		double half = DropRecord.chanceBy(1.0 / 512, 355);
		assertTrue("355 kills at 1/512 is about a coin flip, got " + half, half > 0.49 && half < 0.51);
		assertEquals(0, DropRecord.chanceBy(1.0 / 512, 0), 0);
		assertEquals(0, DropRecord.chanceBy(0, 100), 0);
		assertEquals(1, DropRecord.chanceBy(1, 3), 0);
		assertTrue(DropRecord.chanceBy(1.0 / 128, 1000) > 0.999);
	}

	@Test
	public void rowsThatOnlyApplyOnSomeTasks()
	{
		assertTrue(drop("Abyssal whip", 1.0 / 512, null).appliesTo(5, null));
		DropRecord key = drop("Brimstone key", 1.0 / 96, "konar");
		assertTrue(key.appliesTo(8, null));
		assertFalse(key.appliesTo(5, null));
		assertFalse(key.appliesTo(-1, null));
		DropRecord larran = drop("Larran's key", 1.0 / 99, "wilderness");
		assertTrue(larran.appliesTo(7, null));
		assertFalse(larran.appliesTo(8, null));
		DropRecord shard = drop("Ancient shard", 1.0 / 128, "catacombs");
		assertTrue(shard.appliesTo(5, "Catacombs of Kourend"));
		assertFalse(shard.appliesTo(5, "Slayer Tower"));
		assertFalse(shard.appliesTo(5, null));
		assertFalse(drop("Imbued heart", 1.0 / 2000, "superior").appliesTo(5, null));
	}

	@Test
	public void unionAcrossVariantsRarestFirst()
	{
		TaskRecord t = new TaskRecord();
		t.setMonsters(Arrays.asList(
			monster("Spectre", false, drop("Robe", 1.0 / 512, null), drop("Staff", 1.0 / 128, null)),
			monster("Deviant spectre", false, drop("Robe", 1.0 / 512, null), drop("Key", 1.0 / 4000, null)),
			monster("Abhorrent spectre", true, drop("Heart", 1.0 / 2000, null))));
		List<DropRecord> rare = t.rareDrops();
		assertEquals(3, rare.size());
		assertEquals("Key", rare.get(0).getName());
		assertEquals("Robe", rare.get(1).getName());
		assertEquals("Staff", rare.get(2).getName());
		assertEquals(Arrays.asList("Spectre", "Deviant spectre"), rare.get(1).getFrom());
		assertEquals(Arrays.asList("Deviant spectre"), rare.get(0).getFrom());
		for (DropRecord d : rare)
		{
			assertFalse("a superior's drop leaked into the task odds", d.getName().equals("Heart"));
		}
		assertTrue("the union is cached", rare == t.rareDrops());
	}

	@Test
	public void datasetCarriesTheRates()
	{
		SlayerDataset d = new SlayerDataset(new Gson());
		d.load();
		TaskRecord abyssal = d.find("Abyssal demons");
		assertNotNull(abyssal);
		DropRecord whip = null;
		for (DropRecord r : abyssal.rareDrops())
		{
			if ("Abyssal whip".equals(r.getName()))
			{
				whip = r;
			}
		}
		assertNotNull("abyssal demons drop the whip", whip);
		assertEquals(1.0 / 512, whip.probability(), 1e-6);
		assertEquals("1/512", whip.getRarity());
		assertTrue(whip.getFrom().contains("Abyssal demon"));
		TaskRecord zombies = d.find("Zombies");
		assertNotNull(zombies);
		for (DropRecord r : zombies.rareDrops())
		{
			assertFalse("a boss's drops are not the task's odds: " + r.getName(), "Draconic visage".equals(r.getName()));
		}
		TaskRecord cerb = d.find("Cerberus");
		assertNotNull(cerb);
		boolean crystal = false;
		for (DropRecord r : cerb.rareDrops())
		{
			crystal |= "Primordial crystal".equals(r.getName());
		}
		assertTrue("a boss task shows the boss's own drops", crystal);
		TaskRecord hell = d.find("Hellhounds");
		for (DropRecord r : hell.rareDrops())
		{
			assertFalse("Cerberus's drops are not the hellhound task's odds", "Primordial crystal".equals(r.getName()));
		}
		int withDrops = 0;
		for (TaskRecord t : d.getTasks())
		{
			if (!t.rareDrops().isEmpty())
			{
				withDrops++;
			}
		}
		assertTrue("only " + withDrops + " tasks have rare drops", withDrops >= 120);
	}
}

package com.slayersuite;

import com.slayersuite.advisor.FairyDial;
import org.junit.Test;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class FairyDialTest
{
	@Test
	public void lettersFollowTheGameOrder()
	{
		assertEquals("AIP", FairyDial.letters(new int[]{0, 0, 0}));
		assertEquals("DLS", FairyDial.letters(new int[]{1, 1, 1}));
		assertEquals("CKR", FairyDial.letters(new int[]{2, 2, 2}));
		assertEquals("BJQ", FairyDial.letters(new int[]{3, 3, 3}));
		assertEquals(3, FairyDial.index(0, 'B'));
		assertEquals(2, FairyDial.index(1, 'k'));
		assertEquals(-1, FairyDial.index(2, 'A'));
		assertTrue(FairyDial.isCode("CKS"));
		assertTrue(FairyDial.isCode("bkp"));
		assertFalse(FairyDial.isCode("CKX"));
		assertFalse(FairyDial.isCode("CK"));
		assertFalse(FairyDial.isCode(null));
	}

	@Test
	public void theShorterTurnIsChosen()
	{
		// A (0) to D (1): one clockwise click when clockwise raises the value
		assertArrayEquals(new int[]{1, 1}, FairyDial.turn(0, 1, 1));
		// A (0) to B (3): one anticlockwise click rather than three clockwise
		assertArrayEquals(new int[]{1, -1}, FairyDial.turn(0, 3, 1));
		// two either way: clockwise
		assertArrayEquals(new int[]{2, 1}, FairyDial.turn(0, 2, 1));
		assertArrayEquals(new int[]{0, 1}, FairyDial.turn(2, 2, 1));
		// a dial whose clockwise click lowers the value turns the other way
		assertArrayEquals(new int[]{1, -1}, FairyDial.turn(0, 1, -1));
		assertArrayEquals(new int[]{1, 1}, FairyDial.turn(0, 3, -1));
	}
}

package com.slayersuite;

import com.slayersuite.history.FloorLootMath;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class FloorLootTest
{
	@Test
	public void countdownRoundsUpToTheSecond()
	{
		assertEquals("gone", FloorLootMath.countdown(0));
		assertEquals("gone", FloorLootMath.countdown(-5));
		assertEquals("2:05", FloorLootMath.countdown(125_000));
		assertEquals("1:00", FloorLootMath.countdown(59_999));
		assertEquals("0:05", FloorLootMath.countdown(4_001));
	}

	@Test
	public void vanishesBeforeTheMatchingWindowCloses()
	{
		// the pickup windows run five seconds past the real despawn, so the mark never outlives the item
		assertEquals(120_000L, FloorLootMath.vanishAfter(125_000L));
		assertEquals(180_000L, FloorLootMath.vanishAfter(185_000L));
		assertTrue(FloorLootMath.vanishAfter(3_000L) > 0);
	}
}

