		acc.quests.add("SINS_OF_THE_FATHER");
		acc.cannon = true;
		LocationScorer.Options o = new LocationScorer.Options();
		o.travelTicks = new java.util.HashMap<>();
		o.travelTicks.put("Slayer Tower", 45);
		o.travelTicks.put("Meiyerditch Laboratories", 300);
