	@Test
	public void averageIncludesBonusesOverTheCycle()
	{
		// 900 plain + 80 x5 + 8 x15 + 8 x25 + 3 x35 + 1 x50 = 1775 base over 1000 tasks
		assertEquals(15 * 1.775, PointsMath.averagePointsPerTask(5), 0.001);
		assertEquals(0, PointsMath.averagePointsPerTask(1), 0.0);
	}

	@Test
	public void nextMilestones()
	{
		assertEquals(130, PointsMath.nextBonusTask(128));
		assertEquals(10, PointsMath.nextBonusTask(0));
		assertEquals(150, PointsMath.nextBigMilestone(128));
		assertEquals(250, PointsMath.nextBigMilestone(200));
		assertEquals(800, PointsMath.nextBigMilestone(750));
		assertEquals(1000, PointsMath.nextBigMilestone(950));
	}

	@Test
	public void skipPayback()
	{
		assertEquals(30 / (15 * 1.775), PointsMath.paybackTasks(30, PointsMath.averagePointsPerTask(5)), 0.001);
		assertEquals(-1, PointsMath.paybackTasks(30, 0), 0.0);
	}

	@Test
	public void blockingTheSlowFrequentTaskGainsMost()
	{
		Map<String, Integer> w = new LinkedHashMap<>();
		w.put("slow", 10);
		w.put("fast", 10);
		w.put("unknown", 5);
		Map<String, Double> x = new HashMap<>();
		x.put("slow", 20_000.0);
		x.put("fast", 60_000.0);
		List<PointsMath.BlockCandidate> c = PointsMath.blockCandidates(w, x, 40_000.0, 3);
		assertEquals(1, c.size());
		assertEquals("slow", c.get(0).getKey());
		assertTrue(c.get(0).getGainPct() > 20);
		assertEquals(0.4, c.get(0).getShare(), 0.001);
	}
}

package com.slayersuite;

import com.slayersuite.advisor.ScenePath;
import java.util.List;
import net.runelite.api.CollisionDataFlag;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class ScenePathTest
{
	private static int[][] grid(int n)
	{
		return new int[n][n];
	}

	@Test
	public void straightLineWhenOpen()
	{
		List<int[]> p = ScenePath.find(grid(10), 0, 0, 5, 5, 60);
		assertEquals(6, p.size());
		assertEquals(5, p.get(5)[0]);
		assertEquals(5, p.get(5)[1]);
	}

	@Test
	public void routesAroundAWallThroughTheGap()
	{
		int[][] f = grid(10);
		for (int y = 0; y < 10; y++)
		{
			if (y != 8)
			{
				f[5][y] = CollisionDataFlag.BLOCK_MOVEMENT_FULL;
			}
		}
		List<int[]> p = ScenePath.find(f, 2, 2, 8, 2, 100);
		int[] end = p.get(p.size() - 1);
		assertEquals(8, end[0]);
		assertEquals(2, end[1]);
		boolean throughGap = false;
		for (int[] t : p)
		{
			assertTrue("never stands in the wall", !(t[0] == 5 && t[1] != 8));
			throughGap |= t[0] == 5 && t[1] == 8;
		}
		assertTrue(throughGap);
	}

	@Test
	public void unreachableTargetEndsAtNearestReachableTile()
	{
		int[][] f = grid(10);
		for (int y = 0; y < 10; y++)
		{
			f[5][y] = CollisionDataFlag.BLOCK_MOVEMENT_FULL;
		}
		List<int[]> p = ScenePath.find(f, 1, 1, 8, 1, 100);
		int[] end = p.get(p.size() - 1);
		assertEquals(4, end[0]);
		assertEquals(1, end[1]);
	}

	@Test
	public void wallFlagsBlockCardinalStepsAndDiagonalsNeedBothSides()
	{
		int[][] f = grid(4);
		f[1][1] = CollisionDataFlag.BLOCK_MOVEMENT_EAST;
		List<int[]> p = ScenePath.find(f, 1, 1, 2, 1, 10);
		assertTrue("must detour instead of stepping east through the wall", p.size() > 2);
		assertEquals(2, p.get(p.size() - 1)[0]);
	}
}

