package com.slayersuite.advisor;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.slayersuite.data.LocationRecord;
import java.util.Arrays;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

public class AdvisorFoldTest
{
	private static LocationRecord spot(int x, int y)
	{
		LocationRecord l = new LocationRecord();
		l.setName("spot");
		l.setX(x);
		l.setY(y);
		l.setPins(Arrays.asList(Arrays.asList(x, y + 20)));
		return l;
	}

	@Test
	public void caveMouthIsNextToTheCaveBelowIt()
	{
		// Iorwerth Dungeon lies 6400 tiles "north" of Prifddinas; its cave mouth is a few tiles from the spawns
		LocationRecord iorwerth = spot(3228, 12371);
		assertTrue(Advisor.foldedDistance(iorwerth, new WorldPoint(3230, 6005, 0)) < Advisor.NEARBY_TILES);
		// the Catacombs' dust devils lie 80-90 tiles from the Kourend castle statue that leads down to them
		LocationRecord catacombs = spot(1713, 10019);
		int fromStatue = Advisor.foldedDistance(catacombs, new WorldPoint(1643, 3673, 0));
		assertTrue(fromStatue > 40 && fromStatue < Advisor.NEARBY_TILES);
		// the Fremennik Slayer Dungeon is a continent away from that cave mouth
		LocationRecord fremennik = spot(2701, 9976);
		assertTrue(Advisor.foldedDistance(fremennik, new WorldPoint(3230, 6005, 0)) > 2000);
	}

	@Test
	public void sameLevelDistanceIsPlain()
	{
		assertEquals(10, Advisor.foldedDistance(spot(100, 100), new WorldPoint(100, 110, 0)));
		assertEquals(-1, Advisor.foldedDistance(new LocationRecord(), new WorldPoint(1, 1, 0)));
	}
}

package com.slayersuite.route;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.junit.BeforeClass;
import org.junit.Test;

public class PlannerTest
{
	static WorldMap map;
	static TransportTable table;
	static Set<Transport> all;
	static final int SMOKE_DUNGEON = Packed.of(3179, 9362, 0);
	static final Planner.Landing POLLNIVNEACH = new Planner.Landing("Fairy ring DLQ", "fairy rings", Packed.of(3359, 2971, 0), 10);

	@BeforeClass
	public static void load()
	{
		map = WorldMap.load();
		table = TransportTable.load();
		all = new HashSet<>(table.all());
	}

	@Test
	public void teleportsWhenTheWalkIsLong()
	{
		Planner.Plan p = Planner.plan(map, table, all, Packed.of(3222, 3218, 0), SMOKE_DUNGEON, Arrays.asList(POLLNIVNEACH), false, 800_000, 3_000_000_000L);
		assertTrue(p.reached());
		assertNotNull(p.teleport);
		assertEquals("Fairy ring DLQ", p.teleport.label);
		assertTrue(p.ticks < 200);
	}

	@Test
	public void walksWhenAlreadyClose()
	{
		Planner.Plan p = Planner.plan(map, table, all, Packed.of(3359, 2971, 0), SMOKE_DUNGEON, Arrays.asList(POLLNIVNEACH), false, 800_000, 3_000_000_000L);
		assertTrue(p.reached());
		assertNull(p.teleport);
	}

	@Test
	public void aShortWalkIsNeverTeleported()
	{
		List<Planner.Landing> silly = Collections.singletonList(new Planner.Landing("Anything", "carried", Packed.of(3210, 3210, 0), 0));
		Planner.Plan p = Planner.plan(map, table, all, Packed.of(3222, 3218, 0), Packed.of(3215, 3212, 0), silly, false, 100_000, 2_000_000_000L);
		assertNull(p.teleport);
		assertTrue(p.reached());
	}

	@Test
	public void ridesTheSpiritTreeFromTheGrandExchange()
	{
		// from the Grand Exchange to the Gnome Stronghold tree: 20 tiles to the GE tree and a ride, not a 700-tile walk
		Planner.Plan p = Planner.plan(map, table, all, Packed.of(3170, 3490, 0), Packed.of(2461, 3444, 0), Collections.emptyList(), false, 800_000, 3_000_000_000L);
		assertTrue(p.reached());
		assertNull(p.teleport);
		boolean rode = false;
		for (Router.Step s : p.route.steps)
		{
			rode |= s.transport.kind == Transport.Kind.SPIRIT_TREE;
		}
		assertTrue(rode);
		assertTrue(p.ticks < 60);
	}

	@Test
	public void aSolidFairyRingCanStillBeUsed()
	{
		// Zanaris's ring sits on a solid tile; standing beside it, the plan still rides it
		Planner.Plan p = Planner.plan(map, table, all, Packed.of(2409, 4434, 0), Packed.of(3426, 3017, 0), Collections.emptyList(), false, 800_000, 3_000_000_000L);
		assertTrue(p.reached());
		boolean ring = false;
		for (Router.Step s : p.route.steps)
		{
			ring |= s.transport.kind == Transport.Kind.FAIRY_RING;
		}
		assertTrue(ring);
	}

	@Test
	public void aTeleportMustBeatTheWalkClearly()
	{
		// a landing that only shaves a few ticks off a short walk loses to the walk, and the walk is kept either way
		Planner.Landing nearby = new Planner.Landing("Nearby ring", "fairy rings", Packed.of(3215, 3212, 0), 10);
		Planner.Plan p = Planner.plan(map, table, all, Packed.of(3222, 3218, 0), Packed.of(3100, 3250, 0), Collections.singletonList(nearby), false, 800_000, 3_000_000_000L);
		assertTrue(p.reached());
		assertNull(p.teleport);
		assertNotNull(p.walk);
		Planner.Plan far = Planner.plan(map, table, all, Packed.of(3222, 3218, 0), SMOKE_DUNGEON, Arrays.asList(POLLNIVNEACH), false, 800_000, 3_000_000_000L);
		assertNotNull(far.teleport);
		assertTrue(far.walk == null || !far.walk.reached || far.walkTicks() > far.ticks + Planner.MARGIN_TICKS);
	}
}

package com.slayersuite.route;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.util.HashSet;
import java.util.Set;
import org.junit.BeforeClass;
import org.junit.Test;

public class RouterTest
{
	static WorldMap map;
	static TransportTable table;
	static Set<Transport> all;

	@BeforeClass
	public static void load()
	{
		map = WorldMap.load();
		table = TransportTable.load();
		all = new HashSet<>(table.all());
	}

	@Test
	public void walksAcrossLumbridge()
	{
		int start = Packed.of(3222, 3218, 0);
		int goal = Packed.of(3210, 3210, 0);
		Router.Route r = Router.find(map, table, all, start, goal, 200_000, System.nanoTime() + 2_000_000_000L);
		assertTrue(r.reached);
		assertEquals(start, (int) r.tiles.get(0));
		assertEquals(goal, r.end());
		assertTrue(r.tiles.size() >= 13 && r.tiles.size() <= 40);
		assertTrue(r.indexOf(goal) == r.tiles.size() - 1);
	}

	@Test
	public void entersTheCatacombsThroughTheStatue()
	{
		int start = Packed.of(1643, 3669, 0);
		int goal = Packed.of(1666, 10052, 0);
		Router.Route r = Router.find(map, table, all, start, goal, 300_000, System.nanoTime() + 3_000_000_000L);
		assertTrue(r.reached);
		assertEquals(1, r.steps.size());
		assertEquals("Investigate Statue", r.steps.get(0).transport.label());
		assertEquals(Packed.of(1639, 3673, 0), (int) r.tiles.get(r.steps.get(0).index));
	}

	@Test
	public void unreachableEndsNearest()
	{
		int start = Packed.of(3222, 3218, 0);
		int goal = Packed.of(1, 1, 0);
		Router.Route r = Router.find(map, table, new HashSet<>(), start, goal, 2_000, System.nanoTime() + 1_000_000_000L);
		assertTrue(!r.reached);
		assertTrue(r.tiles.size() >= 1);
	}

	@Test
	public void headsForTheGroundAboveADungeon()
	{
		// Pollnivneach to the Smoke Dungeon's dust devils, 6400 tiles "north" in the data: down the well
		Router.Route r = Router.find(map, table, all, Packed.of(3359, 2971, 0), Packed.of(3179, 9362, 0), 400_000, System.nanoTime() + 3_000_000_000L);
		assertTrue(r.reached);
		boolean well = false;
		for (Router.Step s : r.steps)
		{
			well |= s.transport.label().contains("Smokey well");
		}
		assertTrue(well);
	}

	@Test
	public void keepsOutOfTheWildernessWhenAsked()
	{
		int tower = Packed.of(3428, 3533, 0);
		int catacombs = Packed.of(1708, 10014, 0);
		Router.Route free = Router.find(map, table, all, tower, catacombs, 800_000, System.nanoTime() + 3_000_000_000L, false);
		assertTrue(free.reached);
		Router.Route safe = Router.find(map, table, all, tower, catacombs, 800_000, System.nanoTime() + 3_000_000_000L, true);
		for (int tile : safe.tiles)
		{
			assertTrue(!Router.inWilderness(tile));
		}
		for (Router.Step s : safe.steps)
		{
			assertTrue(!s.transport.label().contains("Wilderness Ditch"));
		}
	}

	@Test
	public void aPinWithTheWrongFloorMovesToTheFloorThatExists()
	{
		// the Slayer Tower basement is floor 3 in the map; the dataset's pins say floor 0
		int pin = Packed.of(3427, 9943, 0);
		assertTrue(map.isBlocked(pin));
		int fixed = Router.walkableNear(map, pin);
		assertEquals(3, Packed.plane(fixed));
		Router.Route r = Router.find(map, table, all, Packed.of(3428, 3533, 0), fixed, 300_000, System.nanoTime() + 3_000_000_000L);
		assertTrue(r.reached);
		assertEquals("Climb-down Ladder", r.steps.get(0).transport.label());
	}

	@Test
	public void theWildernessSlayerCaveCountsAsWilderness()
	{
		assertTrue(Router.inWilderness(Packed.of(3406, 10145, 0)));
		assertTrue(Router.inWilderness(Packed.of(3100, 3600, 0)));
		assertTrue(!Router.inWilderness(Packed.of(3428, 3533, 0)));
		assertTrue(!Router.inWilderness(Packed.of(3222, 3218, 0)));
	}
}

